window.__D("text/maamarei-admur-hazaken/c001",{"p":[[2100490142,"דאברהם לשרה דהיינו להעלותה במח\"ת באופן שיוכל להיות ממנה עוד בנין ותיקון על להבא והוא שיבנה ממנה בנין רבקה ליצחק כידוע בפי' וינחם יצחק<sup data-n=\"465\">54</sup> אחרי אמו דמפני שכמו שהי' אופן מדריגת שרה לאברהם כך הי' אופן מדריגת רבקה ליצחק וכנ\"ל וד\"ל. וזהו ויבא אברהם לספוד לשרה ולבכותה כו' כי אגרא דהספדא דלויי כנ\"ל ומחמת העלאה זו נבנית בנין רבקה דהיינו בבחי' המשכה חדשה להיות שם ב\"ן לבחי' יצחק כי בחי' יצחק הוא מבחי' גבורות כידוע ושרה הייתה בחי' שם ב\"ן לבחי' מ\"ה דאברהם שהי' איש החסד<sup data-n=\"466\">55</sup> כידוע וע\"כ כדי להחליף ההמשכה מבחי' דמ\"ה דחסד להיות שם ב\"ן לבחי' מ\"ה דגבורה דיצחק הוצרך אברהם לענין ההספד דוקא מטעם הנ\"ל וד\"ל (ועם זה יובן גם בפי' המאמר הנ\"ל במ\"ש קוב\"ה דאתכליל מאתר עילאה כו' שר\"ל בחי' שם ב\"ן אך שהוא בחי' שם ב\"ן דכתר דהיינו מה שעלה סוף מעשה במח' כו' וז\"ש דאתכליל מאתר עילאה דמח' דא\"ק שנק' סדכ\"ס ע\"כ הוא ברזא דמאה ברכאן דהיינו בבחי' היחוד דמ\"ה וב\"ן שבכתר עצמו ואח\"כ יורד עוד למטה ביחוד או\"א ואח\"כ בז' שנים וכולן מסתיימים במל' שהוא שרה שם ב\"ן בפרט) כנ\"ל וד\"ל<sup data-n=\"e17\">*</sup>.",[["465","54","<b>וינחם יצחק</b>: חיי שרה כד, סז."],["466","55","<b>דאברהם שהי' איש החסד</b>: ראה ספר הבהיר סק\"צ-צ\"א. הובא גם בפרדס שער (ב) טעם האצילות. שער (כב) הכנויים פ\"ד. כד הקמח מערכת אורחים בתחלתה (לה, א). אגה\"ק ס\"ה (קח, ב)."],["e17","*","<b>וד\"ל</b>: אחרי סיום המאמר נמצא בכת\"י 70 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: ועיין בלק\"ת פ' הברכה ע\"פ ואתא מרבבות קדש שזהו בחי' עליונה יותר מענין חיי שרה מאה שנה כו' ומאה ברכות זהו בחי' דבור, וע\"י המעשה ממשיכין מבחי' גבוה יותר כמ\"ש בד\"ה הבאים ישרש יעקב."]]],[2100490143,"<h3>להבין בתוס' ביאור שרש ענין הנ\"ל</h3>\n<b></b><b>בעזר\"ה, ביאור על הנ\"ל בענין מאה שנה כו'</b>\n<b>להבין</b> בתוס'<sup data-n=\"467\">1</sup> ביאור שרש ענין הנ\"ל, ותחלה יש להקדים להבין שרש ענין המאמר הנ\"ל כבוצינא<sup data-n=\"468\">2</sup> כו' דכד תסתכל לא תשכח אלא בוצינא חדא כו'. הנה י\"ל שרש ענין ההפרש בין לבושי מחדו\"מ לשכל ומדות כנ\"ל בהיות שאנו רואים שע\"ס דאצי' שהזכיר במאמר דאליהו<sup data-n=\"469\">3</sup> לא הזכירם רק כמו שהן מלובשים בכלים כמו חכמה מוחא מלגיו כו' כתר קרקפתא כו' חסד דרועא ימינא כו' וכיוצא ולכאורה אינו מובן למה לא הזכירם כמו שהן אורות פשוטים מבלתי התלבשות בכלים. אך הענין יובן",[["467","1","<b>להבין בתוס'</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 סט, א. עם הגהות בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ. נמצא ג\"כ בכת\"י 1001 מג, א. 70 ח, א. 1052 קיג, א. (וסיומו שם דף יט, א).\nהנחת ר' משה בן אדה\"ז נדפס לקמן ע' צה.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ע' קמ."],["468","2","<b>כבוצינא</b>: ראה זח\"ג רפח, א."],["469","3","<b>במאמר דאליהו</b>: ראה הקדמת ת\"ז (יז, א)."]]],[2100490144,"בהקדים תחלה להבין שרש ענין מחדו\"מ שנק' לבושים וי\"ס שמלובשים בכלים כנ\"ל נק' גופא כמבואר במאמר דאליהו דהנה ג' לבושים דמחדו\"מ באמת לא על גופי מהות המח' והדיבור בלבד אמרו אלא גם על בחי' הכחות שלהם דהיינו בחי' כח המח' וכח הדיבור וכח המעשה הגם שכחות הללו נק' בחי' אורות לגבי התפשטות מהות המח' והדו\"מ מ\"מ גם הכחות נק' לבושין לגבי עצם האדם ומתחלה י\"ל איך שהן נק' אורות כי הנה מה שבלשון המקובלי' נק' אורות נק' בלה\"ק הפשוט בשם כחות כי הכח הוא מה שיש בעצם תמיד באדם כמו כח התנועה שיש באדם להניע כל דבר גם קודם שיניע כמו שיש בכח היד לזרוק האבן הנה יש אותו כח תמיד ביד וכשיניע לזרוק האבן אינו אלא גילוי אותו כח מן ההעלם ואין פי' העלם שאיננו אלא אדרבא ישנו תמיד ביד ברוחניות גלויי' רק שלא נתפשטה בהתגלות חוץ ליד רק ע\"י הזריקה וגם אחר שנתפשטה בזריקה אין הענין שתצטרך הכח להתגלו' זאת לצאת דרך הבשר והגידים של היד בדרך בקיעה להיותם גשם עב מונעים התפשטותו אלא הענין הוא שתיכף שעלה ברצונו להניע כחו שביד יניע הכח את היד פתאום מבלתי הצטרכות לצאת מגדרי גשם היד כי לגבי כח הרוחני אין גשם היד מונע ולא מעכב כידוע שאין הגשם מפסיק לרוחני כו' והנה כשזורק האבן כאשר יכלה כח הזריקה יפול האבן ועד שעדיין לא כלה הכח ינשא ויוליך את האבן למעלה או למרחוק כפי אופן הזריקה והרי מוכרח מזה שאותו הכח הרוחני נושאו כל אותו המרחק כידוע כפי המדה בלבד שנתגלה מאותו הכח שיש בעצם ביד כו' וע\"כ נק' כח זה שיש בעצם ביד לזרוק כהנה וכהנה בשם אור והתגלות אותו האור הוא בשעת הזריקה במדה וקצבה והוא עד\"מ שיאיר האור לפעמים בהתפשטו' רב או בהתפשטו' מעט כו' ואין שינוי בעצם האור מפני זה כו' וד\"ל. ועד\"ז יובן גם בכחות של המחדו\"מ שכמו שכח התנועה שהוא כח המעשה נק' אור והתפשטו' הוא בחי' גילוי האור כנ\"ל כך גם במח' בחי' כח המחשבה שיש בעצם תמיד במוח נק' אור והתפשטו' שלה לחשוב ממש לפעמים במיעוט ולפעמי' בהתרחבו' הוא בחי' גילוי האור ועד\"ז בדיבור ונק' גם הם בשם או\"כ (ויש בהם מדריגות חלוקות כענין הקטנות והגדלות ג\"כ כמו בשכל ומדות כי הרי הבהמה יש לה כח התנועה בשלימות בבחי' או\"כ כמו בזריקת צרורות וכיוצא ובדיבור אין לה רק קול<sup data-n=\"470\">4</sup> פשוט ובמח' רק כח הדמיון כו' משא\"כ באדם) ואמנם לגבי בחי' גופא גם בחי' המחדו\"מ נק' לבושים נפרדי' כנ\"ל כי הרי אנו רואים שתתחלף המח' למח' אחרת וכמ\"ש כלבוש תחליפם<sup data-n=\"471\">5</sup> מזה מוכרח שגם אותו הכח הרוחני של המח' אינו מתאחד כ\"כ עם הנפש כמו המדות והשכל הנק' גופא שאין האברי' מתחלפים לעולם והרי תמיד הן בקיומן בלי שום שינוי ללבוש ולפשוט כמו בג' כחות דמחדו\"מ שהרי היד שמורה על החסד תמיד בקיומו ואיננו מתחלף כלל וגם הרגל ושאר האברים הפנימים והחיצוני' כולן לא ישנו תפקידם לעולם כידוע מפני שמתאחדי' עם האורות של הנפש בתכלית היחוד שהרי הגוף איננו נראה נפרד כלל מן האורות וכחות של השכל והמדות שמלובשים באברי הגוף וכאלו הן עצם א' ממש כו' וע\"כ נק' ג' כחות דמחדו\"מ בשם לבושים לגבי גופא כו' עד\"מ הלבוש שהאדם יכול לפושטו וללובשו מפני שהוא נפרד משא\"כ",[["470","4","<b>קול</b>: בכת\"י 1001: כח קול."],["471","5","<b>כלבוש תחליפם</b>: תהלים קב, כז."]]],[2100490145,"מאברי גופו לא יוכל לפשוט כי המה עצמיי' בנפשו הגם שהן רק בחי' כלים לשכון בו כו' וד\"ל. וכדוגמא זו יובן למשכיל למעלה עיקר ההפרש בין אצי' לבי\"ע דע\"ס דאצי' כמו חכ' מוחא כתר קרקפתא חסד דרוע' ימינא כו' היינו בחי' אורות של המאציל שמלובשי' בבחי' כלים שהן הנה בבחי' עצם א' מתאחדי' עם האורות וגם בכתר הראש והגלגולת עצם א' נחשב עם האור של הכתר אעפ\"י שהגלגולת שהיא בחי' גשמיו' לגבי' כו' ועד\"ז בשאר האורות שמלובשת בכלים כמו חכ' מוחא חסד בדרוע' ימינא כו' משא\"כ בבי\"ע נק' לבושים דמכסיין על גופא כו' פי' מפני שהם נפשטי' מן בחי' העצמו' דאדם דאצי' כמו כח המח' שפושטה ולובשה כנ\"ל וד\"ל. והנה בכ\"ז מובן טעם ההפרש שבאצי' איהו וחיוהי<sup data-n=\"472\">6</sup> וגרמוהי חד כו' משא\"כ בבי\"ע אך עוד טעם אחר יש והוא במה שיש בחי' הפרסא המפסיק בין אצי' לבי\"ע<sup data-n=\"473\">7</sup> כידוע.\nב) <b>ולהבין</b> ענין הפרסא תחלה י\"ל בסדרי ההשתלשלו' בג' עולמות דבי\"ע עצמו כי גם בהן יש בחי' פרסא או מעקה<sup data-n=\"474\">8</sup> שמפסיק בין עולם לעולם כידוע. דהנה התהוות נפש השכלי' שלנו בעולם השפל ידוע שהוא רק מבחי' חיצוני' הכלים די\"ס דעשי' ע\"י<sup data-n=\"475\">9</sup> זיווג דמ\"ה וב\"ן שבי\"ס דעשי' תחלה כו'. וביאור הדבר הנה ידוע בכ' האריז\"ל דיש ג' מדריגות בכל עולם דהיינו נר\"נ ושרשם בכלל הן מבחי' ל' כלים<sup data-n=\"476\">10</sup> דאצי' שנעשה נר\"נ כללי בבי\"ע ומתחלק לפרטיות נר\"נ בכל עולם כו'. והנה בחי' אור הנשמה שבכל עולם גם בעולם העשי' הוא בחי' אלקות עדיין ובחי' נפש ורוח הן בחי' נברא ובחי' הכלים של נר\"נ כולן הן בחי' נברא גם בחי' כלי של נשמה כו' וידוע שמבחי' הכלים של עולם העליון נעשה בחי' אורות בעולם התחתוני' כמ\"ש במ\"א באריכו' ואמנם הנה כאשר יצטרך שיולד אור בריאה חדשה כמו דוגמת נפש דעשי' שמלובשת בגופות שלנו הנה בהכרח שיתייחדו האורות והכלים בי\"ס דעשי' בבחי' היחוד דמ\"ה וב\"ן דעשי' כו' ומולידים אז אור נפש חדש מאין ליש וע\"ד דוגמת זיווג הגשמי שהזיווג והיחוד הוא בחיצוני' הכלים והאברים כך למעלה מתייחדי' בחי' חיצוני' הכלים דמ\"ה עם חיצוני' הכלים דב\"ן<sup data-n=\"477\">11</sup> ומולידים וענין ההולדה הוא ג\"כ יציאת וירידת מדריגה עוד למטה כי הוא ע\"ד דוגמא מהולדת ולד למטה מזיווג זו\"נ גשמיי' שהולד נולד ויוצא מופרד לעצמו ואיננו שייך לאמו ולאביו אחרי הולדו כי נלקח מחיצוני' שלהם שכבר נפרדו מן עצמם כו' וד\"ל. והנה אחרי כל הירידות של המדרי' הנ\"ל דהיינו רק מזיווג חיצוני' הכלים דמ\"ה וב\"ן דעשי' ונולדה הנפש החדשה בבחי' פירוד אזי יורדת ונכנסת אח\"כ בגוף חומרי בעוה\"ז יתמעט אורה עוד הרבה מפני גשמיו' חומריות הגוף כידוע ואעפ\"כ הנה אנו רואים שהנפש הזאת היא יכולה להיות משכלת בכל חכ' ומדע כמו חכמת שלמה וכיוצא וא\"כ מזה אנו רואים",[["472","6","<b>איהו וחיוהי</b>: ראה הקדמת ת\"ז (ג, ב)."],["473","7","<b>הפרסא. . בין אצי' לבי\"ע</b>: ראה ע\"ח שער (מז) סדר אבי\"ע פ\"א. עמק המלך שער עולם הבריאה רפ\"א. פ\"ג. פ\"ו."],["474","8","<b>פרסא או מעקה</b>: ראה ע\"ח שער (מב) דרושי אבי\"ע פי\"ג-י\"ד."],["475","9","<b>ע\"י</b>: בכת\"י 1001: ואף גם זאת ע\"י. ובכת\"י 1156 זה בסוגריים, ואולי הכוונה להוציא."],["476","10","<b>ל' כלים</b>: ראה עץ חיים שער (מד) השמות."],["477","11","<b>דב\"ן</b>: בכת\"י 1001 נוסף: ובכלל הוא יחוד דנשמה דמ\"ה עם נפש ורוח דב\"ן. ובכת\"י 1156 זה בסוגריים, ואולי הכוונה להוציא."]]],[2100490146,"על אחת כמה וכמה בכפלי כפליי' לאין שיעור עוצם הפלאת רוממות מעלת אור החכ' כמו שהיא בי\"ס דעשי' עצמו כו' וד\"ל. באמת הרי אין ערוך כלל ליתן דמיון לחכ' שלנו עם בחי' חכ' שבי\"ס דעשי' לא מיני' ולא מקצתי' אפי' בדוגמא דדוגמא עפ\"י אופן ירידת מדריגות הנ\"ל אלא רק יובן קצת דוגמא כזאת ממה שאנו רואים עד\"ז גם כאן בעוה\"ז השפל דילוג מדריגות כיוצא בזה, דהנה כמו תפוח הצומח מן האילן הנה כח הצומח מצמיחו והמזל העליון מכה ומגדלו כידוע והנה בתפוח יש הרבה מדריגות במינים טעמים הרבה יש תפוח מתוק ויש תפוח חמוץ או ערב כו' כידוע ובודאי שזה השינוי אינו מצד עצמו רק מחמת כח המגדלו שהצמיחו וגידלו במהות מתיקות זאת או חמיצות כו' וידוע שאין ערוך כלל וכלל בין טעם מתיקות גשמי' שנרגש לחיך גשמי למתיקות רוחניו' שבנפש שאינו נרגש לחיך גשמי כו' והנה זהו עכ\"פ מוכרח לומר שבודאי א\"א שיהי' מציאת מתיקות גשמי' כזאת במזל העליון הרוחני כו' אלא ענין המתיקות שבמזל הוא ע\"ד ענין מציאת מתיקות ועריבות שיש לאדם מן השכל וסברא הטובה או מן הניגון הערב לנפשו וכיוצא שמתיקות ועריבות הללו רוחניי' הם ואינם נרגשים לחיך גשמי כידוע ועד\"ז מציאת מתיקות הרוחניות שבמזל העליון וממנו נסתעף מתיקות גשמיו' שבתפוח ע\"י ההגדלה שגידלו והמשיך בו מעט מעט וכיוצא בזה הדילוג המדריגה יובן ענין דוגמא מזה למעלה איך שנולד נפש שכלי' שלנו מזיווג מ\"ה וב\"ן דחיצוני' הכלים די\"ס דעשי' ואיך שהנפש המשכלת עכ\"פ קצת מעין ודוגמא דדוגמא ממהות אור החכ' הנמצא בחיצוני' הכלים די\"ס דעשי' ע\"ד דוגמת מתיקות התפוח לגבי מתיקות הרוחני שבמזל (וכיוצא בזה יובן עוד למעלה מעלה מהולדות אורות חדשות בעולם העשי' מזיווג חיצוניו' שבי\"ס דיצי' מכלים דמ\"ה וב\"ן דיצי' ועד\"ז ענין הולדות אורות חדשות ביצי' מזיווג מ\"ה וב\"ן דבריאה כו' וכ\"ז מפני שאין ערך כלל בין עולם התחתון לגבי העליון כנ\"ל וד\"ל) והנה עיקר הסיבה מה שאין ערך בין עשי' ליצי' ובין יצי' לבריאה<sup data-n=\"478\">12</sup> הוא מפני שיש בחי' מעקה המפסיק בין יצי' לעשי' וכן מבריאה ליצי' כידוע וענין המעקה ידוע להיות כי בחי' מל' שביצי' נעשה בחי' עתיק לעשי' כידוע ופי' עתיק ידוע שהוא מלשון המעתיק הרים<sup data-n=\"479\">13</sup> כו' שנעתקו ממקומם כך בחי' מל' דיצי' נעתק ומובדל מערך ההשתלשלו' שבעולם העשי' (וגם נק' עתיק מיומין דיצי' מפני שאינו אלא ע\"ד המעתיק שמעתיקין מספר לספר כך בחי' מל' דיצי' נעתקה מעולם היצי' כו') וכידוע שזהו פי' המתנשא מימות עולם<sup data-n=\"480\">14</sup> כו' לפי שגם בחי' התחתונה שבעליון נעשה בחי' מקיף ומקור לתחתון כידוע והנה לזה הטעם בהכרח שכאשר יבא אור השפע מיצי' לעשי' אינו ע\"י סדר השתלשלות מעילה לעילה כמו בעולם היצי' עצמו אלא מוכרח שיתלבש ויתעלם האור בלבוש גס ועב כמו מסך והאור הבוקע המסך העב עד\"מ הוא שיכול עולם העשי' לקבל מאחר שגם מבחי' מל' דיצי' לא יכלו לקבל רק בבחי' מקיף כו' וענין ההלבשה הזאת במסך מבדיל נק' מעקה או פרסא והוא נק' אור של תולדה<sup data-n=\"481\">15</sup>",[["478","12","<b>לבריאה</b>: בכת\"י 1001 נוסף: עד שמחיצוניות הכלים דיצי' נעשי' ונתהווי' אורו' חדשו' בעשי' וכנ\"ל. ובכת\"י 1156 זה בסוגריים, ואולי הכוונה להוציא."],["479","13","<b>המעתיק הרים</b>: איוב ט, ה."],["480","14","<b>המתנשא מימות עולם</b>: ברכת יוצר."],["481","15","<b>אור של תולדה</b>: ראה ע\"ח שער (מב) דרושי (כללות) אבי\"ע פרק יג. סידור (עם דא\"ח) שער המילה קמה, ב. ביאוה\"ז ויצא יז, א. תו\"א לך יב, ב."]]],[2100490147,"כמ\"ש במ\"א והיינו מה שנראה אור נולד דרך<sup data-n=\"482\">16</sup> בקיעה בלבד דרך המסך העב כו' וידוע ענין הבנת המסך הזה מדוגמא שמצינו למטה בהלבשת איזה אור שכל עמוק במשלים וחידות כמו משלי שלמה שהעלים עמקות חכמה במשלים והנה השומע המשל בלבד ואינו מבין מה שנרמז בתוכו אין המשל אצלו רק דברים בטלים בעלמא ומי שמבין השכל הנרמז בו ג\"כ איננו משיגו כמו שהוא רק אפס קצהו ממה שמובן מתוך דברי המשל וה\"ז כמי שרואה את האור הגדול דרך המסך המבדיל בינו לבין האור שאיננו רואה מהות האור ממש רק הארתו דרך המסך כנ\"ל<sup data-n=\"483\">17</sup> וכמ\"ש במ\"א באריכות וכך יובן הדוגמא ענין התלבשו' שפע מיצי' לעשי' אינו אלא ע\"י העלם השפע בתוך המסך הנק' פרסא והאור שיבקע מתוכו אותו בלבד יכולים לקבל וכ\"ז מטעם שאין ערוך כלל ביניהם כי מבחי' מל' דיצי' נעשה עתיק לעשי' כנ\"ל (וע\"כ זאת הסיבה ג\"כ מה שנולדו אורות חדשות בעשי' רק מזיווג חיצוני' הכלים דיצי' כו') ועד\"ז ממש יובן מבריאה ליצי' וד\"ל (וגם ענין המסך הזה הוא נמצא בכל חלקי הפרצופים העליוני' כידוע שהרי משכל למדות ג\"כ יש פרסא כי הנה התפעלו' המדות אין ערך להם כלל עם מהות השכל כידוע ולכאורה יפלא איך תתפעל המדה מחמת ההתבוננו' וכיוצא אחר שאין ערך כלל וכלל ביניהם אלא הענין הוא ג\"כ שבא האור השכל בדרך התלבשו' בבחי' מסך ומעקה עד שיקבלו המדות אור השכל ויתפעלו גם הם כו' וענין זה המסך שבין השכל והמדות<sup data-n=\"e18\">*</sup> והנה ע\"ד הנ\"ל יש מעקה כללית בין אצי' לבי\"ע עד שמחמת זה ג\"כ הוא הסיבה שמזיווג חיצוני' הכלים דמ\"ה וב\"ן דאצי' נולדו אורות חדשים בעולם הבריאה להיות נהנין מזיו כו' כי מל' דאצי' נעשה עתיק לבריאה כו' אבל באצי' עצמו איהו וחיוהי וגרמוהי חד כנ\"ל וע\"כ הוא הטעם השני להתאחדות המדות והשכל בנפש יותר מג' כחות לבושי מחדו\"מ כנ\"ל והיינו שהזכיר במאמר דאליהו בחי' הכלים דוקא משום דאיהו וחיוהי כו' וד\"ל.\nג) <b>אך</b> עדיין י\"ל למה לא הזכיר בחי' האורות די\"ס כמו שהן מבלתי התלבשו' עדיין בכלים ואברים כו'. אך הענין יובן בהקדי' ענין ההפרש בין בחי' הפרסא דבין אצי' לבי\"ע ובין בחי' צמצום החלל והמקו\"פ שבין עצמות אא\"ס לנאצלים כי הנה בבחי' הפרסא הנ\"ל הגם שמלובש ונעלם האור מאד בלבוש המסך מ\"מ כשרואין מחוץ לפרסא דרך בקיעה עכ\"פ מ\"מ רואין את האור אלא שאין רואין אותו כמו שהוא ממש אלא במיעוט גדול מפני ההעלם כנ\"ל וגם בענין המשל שמלביש השכל",[["482","16","<b>דרך</b>: בכת\"י 1156: בנקב. וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחיקה."],["483","17","<b>כנ\"ל</b>: בכת\"י 1001 נוסף: (אך בין מוחין למדות יש בחי' פרסא ג\"כ כנ\"ל ובין איברים הפנימי' לאברים החיצוני' שנק' חצר הכבד כו'). ובכת\"י 1156 זה בסוגריים, ואולי הכוונה להוציא."],["e18","*","<b>והמדות</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: הוא מבואר במ\"א ע\"פ ועל ראשי החיות<sup data-n=\"5794\">18</sup> רקיע כעין הקרח כו' אמנם יש הפרש בין פרסא זו לבחי' הפרסא והמסך שבין עולם לעולם, ואין כאן מקום ביאורו)."],["5794","18","<b>ועל ראשי החיות</b>: ראה יחזקאל א, כב."]]],[2100490148,"ג\"כ הלא משיגים קצת גופו של שכל מתוך המשל אלא שאין משיגים כמו שהוא ממש אלא בהעלם מתוך דברי המשל כו' אבל בחי' החלל והוא נק' מקו\"פ כידוע<sup data-n=\"e19\">*</sup> הנה ומבואר בע\"ח שהמקו\"פ וריקן לגמרי והוא העדר<sup data-n=\"e20\">*</sup> גילוי האור וע\"ד דוגמא בגשמיו' הוא כמו שאין השמש מאיר בבית אפל שסתמו חלונותיו שלא יאיר אור השמש כו' שבבית הזה אין אור השמש כלל ואין זה דומה למשל הפרסא שהאור ממש עכ\"פ מאיר גם מתוכו אלא שהוא במיעוט כו' ויובן ענין וטעם לצמצום זה דבחי' החלל ומקום הפנוי דוקא בין עצמו' אא\"ס לנאצלי' כו' בהקדי' תחלה ביאור ענין המאמר הנ\"ל כהאי בוצינא דאתפשט לכל סטר כו' וכד תסתכל לא תשכח אלא בוצינא חד כו'. דהנה הע\"ס נק' י\"ס<sup data-n=\"484\">19</sup> בלי מ\"ה פי' בלי מהות ולכאורה יפלא הלא המה מהות מציאות חכ' או בינה אלא הענין הוא עד\"מ ממה שאנו רואים באדם שיש אצלו בחי' כח עצמי שהוא הנק' כח היולי כידוע וענינו ידוע שעדיין לא נתפשט ונמשך כלל להיות נק' בשם איזה מציאות דבר מה אלא עדיין הוא אצלו בכח בעצמותו ויכול להמשך ממנו לכל דבר מה שיחפוץ כמו ע\"ד דוגמא כח החכ' עצמה יש בה ב' מדריגו' הא' מה שכבר נתפשט כחה בלימוד איזה השכלה אם תכונה או חכמת הרפואה שנק' הכח הזה כבר בשם איזה מציאת דבר מה ואם היא חכמת הרפואה אינה חכמת התכונה וכיוצא אבל כשעדיין לא נתפשט כח חכמתו כלל בלימוד אלא עדיין הכח הזה בעצמו כולל בהכנה שלימה שכאשר ירצה להשכיל בה ישכיל בכח זה בכל חכמה שירצה כו' והרי גם שיכול הוא להטות כח זה לכל חכ' אבל כח הזה עצמו מופשט ומושלל לגמרי עדיין מכל מהות ומציאות שם חכ' והשכלה גלוי' פרטי' רק שממנו יומשך כחות השכלות רבות בכל מיני חכ' כו' ונק' זה בשם בחי' כח היולי כידוע ועיקר הכונה בו שאינו נק' עדיין בשם ולא יש דבר מה שיתפס בו עדיין אלא מוכן הוא להתפס להשכלות** רבות ומיני חכמות שונות<sup data-n=\"485\">**</sup> וכיוצא ע\"כ בהכרח לומר בו א' מב' פנים או שאינו בגדר מציאות דבר מה כלל וכלל או אם ימשך להתפס בשם מציאות יוכל להמציא ממנו כמה מיני מדריגות עד אין שיעור בבחי'<sup data-n=\"486\">**</sup>** החכ' והשכל כו' וד\"ל. וגם זה מובן בו שגם אחרי המשך ממנו כמה מציאות עדיין כלולים בבחי' הכח היולי ולא נחשבים לכלום כי בהיותם חוזרים אליו הרי הן כאלו לא נתפשטו במציאות כלל כו' כי הרי ממנו הם מציאות התפשטותם וד\"ל<sup data-n=\"e21\">*</sup>.",[["484","19","<b>י\"ס בלי מה</b>: ספר יצירה פ\"א, מ\"ב."],["485","**","<b>להשכלות רבות ומיני חכמות שונות</b>: בכת'י 1156 רשום: אם אור החכ' או בינה, וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחיקה."],["486","**","<b>בבחי' החכ' והשכל</b>: תיבות אלו ניתוספו בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ בכת\"י 1156.\n20)מאתו: בכת\"י 1001 נוסף: הרי אנו רואים בחוש, וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחיקה.\n**)אות אורו ית': בכת\"י 1156 רשום: את עצמותו, וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחיקה."],["e19","*","<b>כידוע</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: הוא צמצום יותר גדול לאין ערוך מן צמצום הפרסא והמסך הנ\"ל כי ידוע."],["e20","*","<b>העדר גילוי</b>: בכת\"י 1156 רשום: העדר האור לגמרי, וכ\"ק אדמו\"ר הצ\"צ העביר קו על תיבה ”לגמרי\", והוסיף תיבה ”גילוי\". ורשם: שלפני הצמצום לגמרי לגבי העולמות והברואים שבתוכם."],["e21","*","<b>וד\"ל</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: אמנם מ\"מ הכח היולי הזה גם הוא מוגדר באמת היותו מקור לחכ' לבד ולא לחו\"ג וכיוצא רק שבבחי' החכ' הוא היולי."]]],[2100490149,"<b>ועד\"ז</b> יובן בכללות ג\"כ שיש בחי' כח היולי כללי בנפש האדם שמכח הזה יתפשטו כמה מיני מציאו' כמו כח החכ' או כח הרצון וכח המדות וכיוצא ואותו הכח כוללם יחד בא' מב' פנים הנ\"ל או שיוכל להמשך מאיתו ריבוא רבבו' אופני מציאות כחות כאלו או שגם אחרי התפשטותם כשחוזרים אליו הרי כאלו לא היו עדיין במציאות כי באמת הרי אין כאן אלא כח א' פשוט שימצא מאתו הרבה מציאות כחות והוא עצמו אינו בגדר שום מציאות כח נגלה עדיין כו' וד\"ל. והנמשל מכ\"ז יובן למשכיל למעלה די\"ס הנאצלים מעצמות אור הפשוט של המאציל הרי עצמו' הארת המאציל הוא אור א' פשוט בתכלית בדוגמת כח היולי הנ\"ל שיוכל להמשך ולהאציל עד אין קץ ושיעור כמו מאה ריבוא פעמים י\"ס או להאציל ספי' שאינם במציאו' י\"ס הללו דהיינו מציאות ספירות אחרות שאינם לא כתר ולא חכ' כו' וגם אחרי שהאציל י\"ס נק' י\"ס בלי מ\"ה<sup data-n=\"e22\">*</sup> כי כלולים הכל בבחי' עצמות אור הפשוט והרי הוא אינו נק' בשם מציאות דבר מה עדיין כלל וכלל אלא רק מה שיש בכחו להאציל עדיין וא\"כ גם אחרי שהאציל כאלו אינם במציאו' אצי' לגביו מה\"ט וד\"ל וזהו פי' כד תסתכל לא תשכח אלא בוצינא חד כו' פי' מפני שלא נמצא עדיין במציאו' דבר ולא יש דבר שיתפס בו כלל אלא רק כמו בחי' כח היולי דאתפשט לכל סטר וגם אחרי התפשטותו אינו אלא בוצינא חד דהיינו אור א' פשוט בתכלי' הפשיטו' כנ\"ל וד\"ל. ועתה יובן הטעם שלא הזכיר במא' אליהו ענין האורות כמו שהן פשוטי' מבלתי התלבשו' בכלים כי מצד הארתן העצמי מאור המאציל הפשוט הנה הן נק' י\"ס בלי מ\"ה כנ\"ל מפני שאור המאצילן פשוט הוא וא\"כ אין מיוחד אור א' מחבירו לומר עליו כי הוא זה מציאות מיוחד כמו מציאת חכ' ולא בינה שבהיותם כלולים יחד בבחי' כח היולי כו' הרי יכול להיות מציאת בינה במקום שהי' ראוי להיות מציאת כתר כי מאחר שיכול להוציא מן הכח כל מה שירצה באופני' שונים כנ\"ל אלא עיקר הבדל האורות די\"ס להיות ניכרין במציאותן ומהותן לומר על מציאות חכ' מיוחד במהות חכ' לבד וכיוצא אינו אלא כשמתלבשין בכלים דוקא כתר קרקפתא חכ' במוחא כו' וכיוצא ע\"כ הזכירם בכלים דוקא וד\"ל.\n<b>ואחכ\"ז</b> יובן ענין טעם ההפרש בין בחי' הפרסא מאצי' לבריאה ובין בחי' צמצום פנוי כו' כי מאצי' לבריאה אין שם התחדשות גמור כ\"כ רק ענין אור הנברא מאין ליש הוא נעשה מסיבת הירידה של אור דאצי' אבל גופו ומהותו של הנברא כבר הי' בתחלה בבחי' אצי' רק שירד האור ונתגשם במסך כו'<sup data-n=\"e23\">*</sup> אבל מן",[["e22","*","<b>מ\"ה</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: פי' האורות די\"ס מצד עצמן טרם התלבשותן בכלים הם בלי מהות דבר מ\"ה."],["e23","*","<b>כו'</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: וכמשל הגשמת המתיקות שבתפוח מהמתיקות רוחנית שבכח המצמיחו שמ\"מ אינו התחדשו' גמורה כי גם המתיקות רוחניו' מהות מתיקות הוא אלא שבתפוח מתגשם כו' וככה עד\"מ התהוות חכ' דבי\"ע מחכ' דאצי' וכנ\"ל."]]],[2100490150,"עצמו' המאציל לנאצל א\"א עד\"ז כי באמת עצמות<sup data-n=\"e24\">*</sup> לפי ענין הנ\"ל בדוגמת בחי' כח היולי עם כחות הנמצאים מאתו שמציאות הכחות הנמצאים מחודשים הן לגמרי שלא היו מציאותן כלל נמצא במהות כזה בהיותם עדיין כלולים בכח ההיולי כי מושלל הוא לגמרי מכל וכל מכל בחי' גדר מציאת דבר מה כנ\"ל<sup data-n=\"e25\">*</sup> דבר מה שהוא מחודש כו' הוצרך להעלים את** אורו ית' לגמרי ולא בדרך מסך בלבד והוא ענין צמצום הראשון הנק' מקו\"פ כו' ואמנם אין ענין מקו\"פ הזה ע\"ד ההגשמה ח\"ו כדוגמת חלל ריקן למטה אך הענין יובן עפ\"י משל דוגמתו שאנו רואים כאשר ישפיע הרב איזה שכל לתלמידו אזי בודאי הרי נגלה איזה אור וכח שכלי מעצמות השכל של הרב בשעה שמשפיע. והנה כשמפסיק מלהשפיע אין לומר שנסתלק אותו גילוי אור השכל הקדום ונעלם לגמרי אלא הענין הוא שנכלל הגילוי הזה בכח העצמי של אותה שפע ההשכלה שישנה בתמידות אצלו גם מקודם שישפיע אותה כו' וה\"ז כהתכללות אור במאור. ואמנם התכללות זאת לא עשתה שום שינוי ממש גם בבחי' גילוי אור אלא שלא נתגלה עוד כמו הסוגר כלי העין שאור גילוי הראי' נשאר בכח שאין זה שינוי כלל בעצם כח האור של הראי' רק שלא נתפשט עוד וכדוגמא זו הוא משל גשמי הנ\"ל בחלל הבית אפל שאין האור של השמש זורח שם שאין זה שינוי כלל בעצם זיו ואור השמש ואעפ\"י שבמקום זה סתמו החלונות ולא",[["e24","*","<b>עצמות</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: המאציל לאו מכל אינון מדות איהו כלל לגמרי ובחי' י\"ס דאצי' אין ערוך כלל אצלו ית' ולא כמו ערך העשי' לגבי האצי' כו' לא מיני' ולא מקצתי' וגם בחי' ההארה שהוא ית' מאיר בבחי' אור וזיו ממהותו ועצמותו ית' כמו שהיא מצד עצמה לפני הצמצום היא ג\"כ אינה בערך שיתהוו ממנה י\"ס שהם בחי' מציאות דבר מה פרטי חכמה חסד כו' כי האור מעין המאור וכמובן קצת."],["e25","*","<b>כנ\"ל</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: ובאמת שמשל ההיולי אינו דומה לנמשל מכל צד רק בצד א' והוא מה שבההיולי אין ממהות המסתעפי' ממנו ואינו בערך מהותם שכמ\"כ למעלה כו' כנ\"ל אבל מ\"מ בצד א' אינו דומה כי ההיולי הוא מוגדר ומיוחד להיות מקור לכחות המסתעפי' ממנו להן דוקא ולא לזולתם כמובן ממשל הנ\"ל שכח השכל נק' היולי לגבי ההשכלות הגלויות הרי עם שאין בו ממהות שכל גלוי לא מיני' ולא מקצתי' מ\"מ גם הוא יש להגבילו ולומר כי הוא זה כח מיוחד להשכיל ונבדל מן כח המיוחד להתחסד כו' ועד\"ז גם ההיולי הכללי מיוחד להיות מקור לכחות המסתעפי' ממנו כמספרן עשר רצון ושכל כו' ולא זולתם משא\"כ למעלה שהוא ית' פשוט בתכלית הפשיטו' וא\"כ גם ההארה שהוא ית' מאיר מאתו היא ג\"כ בתכלי' הפשיטו' ואין שייך לומר בה שום מקור למציאות ספי' אלו דוקא כנ\"ל שהי' יכול להמשיך ספירות אחרים כו'. ולכן היא למעלה מעלה ממדריגת ההיולי רק שמשל ההיולי נאמר כאן לשלול שאין שם ממהות הי\"ס עכ\"פ. ולהיות כן מובן למשכיל שכדי שיצאו ויתהוו מהארה זאת בחי' י\"ס במציאות."]]],[2100490151,"נגלה בו האור מ\"מ בעצם האור אין זה שינוי כלל וכלל כו' וכך מכל אלה המשלים יובן בדוגמא דדוגמא למשכיל למעלה מעלה בבחי' החלל ומקום הפנוי שבין עצמות המאציל לנאצלים שאינו אלא בחי' העדר גילוי אור מפני שנכלל בעצמות המאציל שנק' מאור שאין זה שינוי כלל בעצם האור רק כמו עד\"מ כח היולי שברב שנכלל בו גילוי שפע השכל כשמפסיק מלהשפיע וכיוצא וכ\"ז המשל בהכרח לומר כן מפני שמבואר למעלה בפי' המאמר כבוצינא חד כו' שבחי' עצמו' כח ואור המאציל הוא אור פשוט בתכלית וע\"כ כדי שיהי' נאצל מאיתו מציאות דבר מה בהכרח הוא דוקא ע\"י בחי' העדר גילוי האור לגמרי בתחלה הנק' מקו\"פ וחלל כו' ולא נשאר בחלל רק בחי' הרשימו כמו נקודא בעלמא כמ\"ש בע\"ח ומשם נמשך שרש<sup data-n=\"487\">*</sup>** הנאצלים ולהיות יוצאים ונמשכים בבחי' מציאות דבר מ\"ה כו' וה\"ז עד\"מ כמו הרב שיצמצם כח השכלתו העצמי ויוכלל הגילוי בהעלם כח היולי שבו ויניח וישאר מ\"מ רק אפס קצהו ההארה מאור אותו השכל הנשפע לתלמידו בכדי שיוכל שאת ועדיין הארה זו הנשארה אצלו כלולה בכח אך שהוא נשאר בבחי' גילוי להיות נובעת ונמשכת לתלמידו. וכמ\"כ למעלה יובן מזה שזהו בחי' הרשימו שנשאר בחלל ומקו\"פ להיות מסתעף ממנה הארת<sup data-n=\"488\">21</sup> שרש כל הנאצלים<sup data-n=\"e26\">*</sup>. ובכ\"ז יובן ג\"כ פי' התחלת המאמר דאליהו אנת הוא חד ולא בחושבן פי' ולא בחושבן י\"ס אלא לריבוא רבבו' ספירו' עד אין קץ ושיעור וגם שלא בחושבן י\"ס כלל וכלל כי אחרי בחי' החלל ומקו\"פ דוקא הוא שיתכן לומר בחי' מספר הי\"ס אבל קודם צמצום זה שהאור א' פשוט בעצמות המאציל כפי המובן מתוך משלים הנ\"ל הרי לא יתכן לומר בו ענין מספר וחשבון כלל אלא כבוצינא חד כו' וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן בתוס' ביאור שרש ענין דברי המאמר הנ\"ל בפי' הפסוק ויהיו חיי שרה כו' קוב\"ה דאתכליל מאתר עילאה כו' שהוא בחי' הכתר הממוצע כנ\"ל והנה יתבאר זה עפ\"י הנ\"ל בענין צמצום מקו\"פ כו' דיש הפרש גדול בין לפני צמצום הזה שהוא אור אחד פשוט בתכלית וזהו הנק' אתר עילאה סדכ\"ס וגם נק'",[["487","*","<b>שרש הנאצלים</b>: בכת\"י 1156 רשום: שרש האורות של הנאצלים, וכ\"ק אדמו\"ר הצ\"צ העביר קו על תיבות: האורות של."],["488","21","<b>הארת</b>: בכת\"י 1156 רשום: הקו והחוט, וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחיקה."],["e26","*","<b>הנאצלים</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: אך מ\"מ הצמצום הזה הוא רק לגבי העולמות שאין מאיר בתוכם האוא\"ס בגלוי כמו שהוא כדי שיהי' כמו שהם עתה ולא יתבטלו ממציאותם לגמרי אבל קמי' ית' אין שום שינוי כלל ע\"י הצמצום והוא ית' נמצא גם עתה בתוך כל העולמות וגם בבחי' החלל הנק' מקו\"פ כמו שהי' לפני הצמצום רק שאינו בבחי' גילוי לגבי המקבלי' ועש\"ז נק' מקו\"פ ר\"ל לגבי המקבלים שאין האור מתגלה עליהם נק' פנוי אבל באמת אינו כן ומקרא מלא כתיב את השמים <sup data-n=\"5795\">22</sup>ואת הארץ אני מלא ובזוהר לית אתר פנוי מיני' כו'. ולהבין הדבר איך ומה לקרב קצת אל השכל אין כאן מקום ביאורו כידוע וד\"ל."],["5795","22","<b>את השמים. . מלא</b>: ירמי' כג, כד."]]],[2100490152,"עתיקא דעתיקין בדרך כלל כידוע בסה\"ק ובין אחרי הצמצום הזה שכבר הוכן שם כח ושרש למציאות התפשטותו אור המאציל לכמה מיני מדריגות שונות כנ\"ל במשל שפע שכל הרב לתלמיד וכיוצא וזהו בחי' הכתר עליון בכלל שהוא שרש וראש לנאצלי' ולא בחי' פרסא בלבד מפסיק בין עצמות המאציל לנאצלים אלא דוקא בחי' צמצום מקו\"פ מטעם הנ\"ל ומ\"ש קוב\"ה דאתכליל מאתר עילאה כו' התכללות זאת בכתר הוא ע\"י בחי' ההארה שנמשכת מעצמו'<sup data-n=\"489\">24</sup> המאציל כמו שהוא לפני הצמצום כו' וע\"כ הוא ברזא דמאה ברכאן דוקא כו' דהיינו להיות כלול בבחי' ראש ושרש של כל מה שעתיד להסתעף מאתו עד\"מ הנ\"ל ברשימו שנשאר ברב המשפיע כו' וע\"כ הוא כולל מאה לפי ערך ההסתעפו' די\"ס העתיד להיות כו' וד\"ל. ומ\"ש בפירוש מאה שנה דאעפ\"י שהן מספר מאה מ\"מ הן שנה אחת ברזא דיחודא כו' הענין מובן שהוא מצד התכללות זאת עצמה דהיינו מה שאותה הרשימו כלולה גם ממה שלפני הצמצום ששם האור פשוט ונק' שנה א' כו' והיינו שא' דאתכליל מאתר עילאה כו' וב' מיני התכללות יש כאן הא' ממה שלפני הצמצום והב' ממה שאחר הצמצום והכל ע\"י בחי' הרשימו והקו<sup data-n=\"490\">25</sup> וד\"ל.\n<b>ומ\"ש</b> בפי' עשרים שנה וז' שנים מבואר למעלה. ומה שמסיי' בפי' ויהיו חיי שרה דהוו ממש כו' הענין הוא מובן מתוך הנ\"ל בדרך אחרת. דהנה מבואר למעלה דיש הפרש בין בחי' פרסא לבחי' החלל ומקו\"פ כו' דמאצי' לבריאה אין זה התחדשות גמור כו' והנה מה שמאיר האור מאצי' לבריאה ע\"י בקיעת הפרסא זהו הנק' שני חיי שרה כידוע דשרה<sup data-n=\"491\">26</sup> הוא שם ב\"ן ושני חיי שרה הוא מה שמושפע מאיתה לבי\"ע ע\"י בחי' הפרסא שמקבלת ע\"י כל האורות העליוני' כנ\"ל אבל בחי' שרש ומקור כל הנאצלים ק' שנה ועשרי' שנה כו' כמו שהיו לפני הצמצום דחלל ומקו\"פ הנ\"ל. זהו שאמר ויהיו חיי שרה דהוו כבר כו' משום דיותר אין ערוך בין נאצל למאציל מכמו שאין ערוך בין בריאה לאצי' כנ\"ל וע\"כ אמר ויהיו מפני שהי' רק בבחי' כח היולי ואח\"כ נתפשט למטה בדילוג המדריגה מאד כנ\"ל וד\"ל (ושרש* ענין<sup data-n=\"492\">*26</sup> ותמת שרה בקרית ארבע כו' שהוא ענין העלאת שם ב\"ן מלמטה למעלה בבחי' או\"ח כו'. הנה יתבאר ג\"כ מתוך ענין הנ\"ל בפי' המאמר קוב\"ה דאתכליל מאתר עילאה כו' דהנה מבואר בע\"ח* דכלל גדול הוא בפי' המאמרי' בזוהר מה שלפעמי' בספירה ואור א' ישונה הלשון לקרותן פעמים בלשון זה ופעמים בלשון אחר שהוא מפני שבזהר הכוונה מיוחדת לספי' ואור פרטי דוקא ואינו מדבר בדרך כללות ההשתלשלו' כמו שלפעמים ידבר במל' דנקודים או במל' דעקודים ולפעמי' במל'",[["489","24","<b>ההארה. . מעצמו'</b>: בכת\"י 1156 רשום: הרשימו שנשאר מעצמו' המאור שלו, וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחוק."],["490","25","<b>והקו</b>: בכת\"י 1052: שהוא בחי' הממוצעת כמבואר מתוך המשלים הנ\"ל. ובכת\"י 1156 זה בסוגריים, ואולי הכוונה להוציא."],["491","26","<b>שרה שם ב\"ן</b>: ראה אוה\"ת בראשית (כרך ב) תמז, ב. תמה, א. (כרך א) מ, ב."],["492","*26","<b>(ושרש ענין</b>: בכת\"י 1001 לא נסמן סיום החצע\"ג.\nבע\"ח: בכת\"י 1156, 1052: בהקדמת ס' הע\"ח, ובכת\"י 1052 העביר כ\"ק אדמו\"ר הצ\"צ קו למחיקה על תיבות: בהקדמת ס'."]]],[2100490153,"דכתר ולפי אופן הכוונה ישנה הלשון וגם כאן הנה פי' קוב\"ה הוא בחי' מל' דא\"א ושרשו עוד למעלה ממנו היינו בחי' הרשימו הנ\"ל שנשאר בחלל כו' ולהיות שרשימו הנ\"ל כלולה ממה שלפני הצמצום ומה שאחר הצמצום כנ\"ל כי הקו שהוא נמשך מהאור שלמעלה מהצמצום מתלבש ברשימו ע\"כ אמר קוב\"ה דאתכליל מאתר עילאה כו' כנ\"ל וד\"ל (והנה<sup data-n=\"493\">27</sup> מה שהיא כלולה מכל מה שעתיד להיו' בהשתלשלו' זהו בבחי' או\"י ומה שכלולה ממה שלפני הצמצום הוא בבחי' או\"ח וזהו מ\"ש ורוח אלקים מרחפת<sup data-n=\"494\">28</sup> ע\"פ המים ואמרו נוגע ואינו נוגע<sup data-n=\"495\">29</sup> כו' וד\"ל. וז\"ש ותמת שרה בקרית ארבע כו' שהוא העלאת שם ב\"ן דא\"א עד רום המעלות להיות בבחי' או\"ח היפך הירידה וההמשכה בבחי' א\"י כו' והיינו אחרי שהזכיר ענין ויהיו חיי שרה עד שכפל עוד ואמר שני חיי שרה וכנ\"ל באריכות אמר ותמת שרה שנסתלק שם ב\"ן להיות רק בבחי' או\"ח בלבד והעלאה זו עולה בעילוי אחר עילוי בעצמות אא\"ס ומתוך זה יוכל להיות אח\"כ ירידת האור בבחי' א\"י ובאופן ומדריגה יותר גבוה מבראשונה כי אחר שנתעלה כ\"כ א\"כ מאותו מקום ומדריגה שנתעלה שם משם דוקא ירד כו' וד\"ל. וזהו שרש ענין ויבא אברהם<sup data-n=\"496\">30</sup> לספוד לשרה כו' ואגרא דהספדא<sup data-n=\"497\">31</sup> דלויי' כו' דהיינו להעלות בעילוי יותר כדי שיהי' אור היורד אח\"כ ביתרון מעלה והוא בנין רבקה ליצחק שהוא יותר גבוה וכמ\"ש לעתיד כי אברהם לא ידענו<sup data-n=\"498\">32</sup> כו' וכמ\"ש במ\"א מטעם יתרון מעלת הגבורות על החסדי' כיתרון מעלת הזהב על הכסף כו' וד\"ל.",[["493","27","<b>(והנה</b>: בכת\"י 1001 לא נסמן סיום החצע\"ג."],["494","28","<b>ורוח אלקים מרחפת</b>: בראשית א, ב."],["495","29","<b>נוגע ואינו נוגע</b>: ראה ב\"ר פ\"ב, ד."],["496","30","<b>ויבא אברהם</b>: חיי שרה כג, ב."],["497","31","<b>ואגרא דהספדא</b>: ברכות ו, ב."],["498","32","<b>כי אברהם לא ידענו</b>: ישעי' סג, טז."]]],[2100490154,"<h3>להבין ענין מ\"ש בתיקונים דקוב\"ה ושכינתי' יגערו בס\"מ</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"499\">2</sup> ענין מ\"ש בתיקונים<sup data-n=\"500\">1</sup> דקוב\"ה ושכינתי' יגערו בס\"מ כו' ויריבו בו ובגערה ונזיפה זו יפול מרשעתו כו' ע\"ש. וזהו ענין ומלך גבור לריב ריבם וכן בחנוכה או' רבת<sup data-n=\"501\">3</sup> את ריבם כו'. דהנה עיקר שרש<sup data-n=\"502\">4</sup> השנאה שיש לכל שר ושר מאוה\"ע בישראל למטה עד שתשוקתם נפלאה להרע להם בכל היכולת בגשמיות הוא רק מפני בחי' הקנאה שמתקנא מאד השר ההוא למעלה בראותו עוצם חיבת ישראל למעלה והפלאת עוצם קדושתם, ודרך כלל זו היתה בחי' הקנאה<sup data-n=\"503\">5</sup> של נחש",[["499","2","<b>להבין ענין מ\"ש בתיקונים דקוב\"ה ושכינתי' יגערו בס\"מ</b>: ראה ת\"ז ת\"ח."],["500","1","<b>להבין ענין מ\"ש בתיקונים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 (עא, ב)."],["501","3","<b>רבת את רבם</b>: נוסח על הניסים."],["502","4","<b>שרש השנאה שיש לכל שר משר מאוה\"ע</b>: ראה ג\"כ ספר הליקוטים דא\"ח לכ\"ק אדהצ\"צ ערך שר."],["503","5","<b>הקנאה של נחש הקדמוני באדה\"ר</b>: ראה סנהדרין נט, ב. מאמרי אדה\"א הנחות תקע\"ז ע' רלא. תו\"ח בראשית לג, א. שם טז, א ובהנסמן לשם."]]],[2100490155,"הקדמוני באדה\"ר ואשתו, ומשם נמשכה הקנאה שלו בכללות הע' שרים שמקבלים ממנו ע\"י שבא נחש על חוה<sup data-n=\"504\">6</sup> והטיל בה זוהמה ולא פסקה זוהמה זו מע' שרים, אך ישראל שעמדו בהר פסקה מהן בחי' זוהמא זו כו', כמ\"ש במ\"א<sup data-n=\"505\">7</sup>.\n<b>וביאור</b> הדבר וענין הקנאה הזאת אעפ\"י שלמטה בגשמיות לא יתכן לומר שיתקנא האומה הגשמי' בעוצם מעלת ישראל בתורתם ועבודתם שהרי אין נחשבים בעיניהם כלל, ואדרבא מתלוצצים מהם כו', אך למעלה בהיות השר שלהם בעל חומר וצורה הוא מבחי' נפש ורוח דחיצוניי' הכלים די\"ס דעשי' כידוע, ובבחי' החומר שלו הוא גשמי מעורב טו\"ר בתכלית עד שיוכל להיות באיזה מדה רעה בתכלית כמו מפני כח רוחניות התאוה או הרציחה שנמצא בשר של ישמעאל למעלה דלכך נמצא תאוות ורציחות גשמיו' באומה של ישמעאל וכיוצא כו', אבל בבחי' הצורה שלו הוא מכיר את בוראו ואומר שירה וכמו שאנו מוצאים בשרו של עשו כו' אלא שיוכל למרוד לפרקים לומר לי יאורי ואני עשתיני<sup data-n=\"506\">8</sup> כו', וע\"כ בראותו עוצם חיבת ישראל למעלה מתקנא מאד על שהוא עומד בריחוק מקום כו' ומזאת הקנאה הוא שנמצא באומה שלו השנאה לשנוא את ישראל בלא טעם ודעת כו'.\n<b>והעצה</b> להסיר קנאתו אינו אלא הגערה והנזיפה בו שכאשר יגער בו ה' ויריב בו ממילא יפול מקנאתו ושנאתו וכמ\"ש יגער<sup data-n=\"507\">9</sup> ה' בך השטן כו'. והטעם לזה יובן עד\"מ ממלך ב\"ו שיש לו בן חכים לו ביותר, ועבדו המושל בכל אשר לו מתקנא לפרקים באהבת וחביבת האדון לבנו, ומקטרג עליו להפילו ממדריגת האהבה כו', שאין עצה למלך כ\"א להשפיל העבד הזה בגערה ונזיפה לזכור לו שהוא עבד ושאין לו ערך אליו להתקנא בו, כי כלום מתקנא אלא כמו חכם בחכם בדבר שהוא מערכו כו', ואז ממילא תפול הקנאה שלו ולא יקטרג עוד עליו, וכך הנמשל למעלה שהקב\"ה יגער בשטן וישפילנו בגערה ובנזיפה שיכיר ערכו ולא יתקנא בישראל וממילא יסור מעמו השנאה למטה מישראל ויתהפך לאוהב כו', וזהו שא' בתיקוני' דקוב\"ה ושכינתי' יגערו בס\"מ ויריבו כו'. וזהו מלך גבור לריב ריבם וכמ\"ש בחנוכה רבת את ריבם כו' כי אין עצה להסיר הקנאה שלו כ\"א בגערה ונזיפה בלבד מטעם הנ\"ל. וזהו שהי' עונש הנחש הקדמוני ג\"כ רק בבחי' השפלות והוא מ\"ש לו על<sup data-n=\"508\">10</sup> גחונך תלך ועפר תאכל כל ימי חייך שאינו אלא כדי שלא יתקנא עוד כו' וד\"ל כנ\"ל וד\"ל.",[["504","6","<b>שבא נחש על חוה</b>: שבת קמו, א. זח\"א נב, ב."],["505","7","<b>ישראל שעמדו בהר פסקה. . כמ\"ש במ\"א</b>: שבת וזהר שם. וראה תו\"א עו, ד. ובכ\"מ."],["506","8","<b>לי יאורי ואני עשתיני</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' ערה. לקו\"ש חכ\"א ע' 40, וש\"נ."],["507","9","<b>יגער ה' בך השטן</b>: זכרי' ג, ב."],["508","10","<b>על גחונך תלך</b>: בראשית ג, יד."]]],[2100490156,"<h3>להבין שרש התהוות הזמן</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b> שרש התהוות הזמן<sup data-n=\"509\">1</sup>, הנה הזמן הוא בחי' נברא מחודש מאין ליש כשאר כל השתלשלות, גם לפי\"ד הפלוסופים ובראשם הראב\"ע כידוע<sup data-n=\"510\">2</sup>, והוא מפני שיש ג' בחי' עולם שנה נפש כידוע<sup data-n=\"511\">3</sup>, וכמו שעולם מחודש כך בחי' שנה מחודש כו', ואחד מן המופתים החזקים לזה הוא ממה שאנו רואים במצות ק\"ש ובמצות השבת שתלויים בזמן, וזמן מצותם אין משתווה בכל המקומות, והוא מפני שיש שינוי גדול במדינות בזמן אור הבוקר ועת הערב שאין כל א' דומה לחבירו, יש מדינות וארצות שיאיר להם היום בזמן קדום ויש מדינות שיתאחר להם אור היום הרבה, עד שבדרך כללות יוכל להיות שבמדינות הצפוני' יהיו הימים ארוכים ובמדינות הדרומי' יהיו קצרים כימי חורף וכיוצא, ואם הזמן אינו נברא בודאי זמן ק\"ש לכולם א' למעלה והי' מהראוי שלא יתחלף הזמן דק\"ש לגבי מקומות מושבי המדינות כו' אם הזמן אינו נברא ומחודש כו'. ועוד זאת יותר יפלא איך שבמצות השבת ג\"כ בהכרח יהי' בהם שינוים אלה שהרי במדינות הצפוני' בקיץ הוא כמו חורף בדרום (ומאחרים כנ\"ל) במצות הכנסת ליל שבת ובמדינות הדרומי' מקדימין בקיץ וכן במוצאי שבתות בהיפך וכענין מכניסי שבת בטברי' ומוציאי שבת בציפורי כו' כידוע, ואם אין הזמן מחודש אלא גם למעלה יש בחי' זמן כמו למטה הי' מהראוי שיהי' זמן מצות השבת א' לכולם כמו שהוא למעלה בין בכניסה בין ביציאה בקיץ ובחורף כו'.\n<b>אך</b> הנה מכ\"ז הוראה גמורה על שהזמן הוא בחי' נברא מחודש מאין ליש כנ\"ל, ואמנם למעלה בבחי' האצי' הוא עדיין למעלה מגדר ובחי' הזמן ועבר הוה ועתיד הכל כא' נסקרין בסקירה א', ואפי' כל שיתא אלפי שני דהוי עלמא עם כל הזמנים פרטיי' הנמצאים במשך זה הכל נסקר בסקירה א' למעלה וכענין המאמר צופה ומביט עד סוף כל הדורות<sup data-n=\"512\">4</sup> כו', וא\"כ כשיש התגלות למעלה באיזה שפע והמשכה אלקית כמו אור שפע דח\"ע במצות ק\"ש וכה\"ג הנה זאת השפע הוא בבחי'",[["509","1","<b>להבין שרש התהוות הזמן</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 (עב, א).\nלכללות המאמר ראה ג\"כ דרך מצותיך נז, א-ב. וראה ספר הליקוטים לאדמו\"ר הצ\"צ ערך ”זמן\" ע' קלח ואילך. וראה אגה\"ק כ\"ק אדמו\"ר זי\"ע כרך א מכתב קנו, כרך ב מכתב רפג."],["510","2","<b>הזמן הוא בחי' נברא. . גם לפי\"ד הפלוסופים ובראשם הראב\"ע כידוע</b>: ראה דרך מצותיך שם: וביאור הענין הנה גם חכמי הפלסופי' הסכימו והוכיחו שהזמן הוא נברא ובראשם הרב רבי אברהם בן עזרא, ולקרב הדבר אל השכל, בראיה ברורה ומכרחת, הוא שהרי אנו רואים שהזמן הוא דבר המתחלק לחלקים היום א' משס\"ה חלקי השנה, ושעה א' מכ\"ד ביום, ורגע א' מתתר\"ף בשעה, והרגע היא גבולית כמימרי', ובהקבץ תתר\"ף חלקים גבוליים כאלו יהי' משך שעה, ובהקבץ כ\"ד שעות יהי' משך יום (שהוא משך הקפת הגלגל היומי) ובהקבץ שס\"ה ימים יהי' שנה, ובקיבוץ שנים רבות יהי' שמיטה ויובל או אלף שנה או שית אלפי שני דהוי עלמא, ומאחר שהוא מקובץ מחלקים הרי נמנע שיהי' בלי מוגבל בפועל. וראה לעיל ע' נט."],["511","3","<b>עולם שנה נפש כידוע</b>: ראה ספר יצירה פ\"ג מ\"ג ואילך."],["512","4","<b>צופה ומביט עד סוף כל הדורות</b>: ראה ברכת זכרונות. ראש השנה יח, א."]]],[2100490157,"שלמעלה מגדר הזמן דעבר הווה כו' אלא בבוא שפע זו למטה בעולם הפירוד שהזמן כבר נברא בו מאין ליש שם מתחלקת שפע אור זה לפי התחלקות הזמן הנמצא שם אבל למעלה אין שפע זו בגדר זמן כו' וע\"כ בזמן מצות ק\"ש הגם שהזמן ניתן למעלה משיאיר היום ולאנשי מזרח שיאיר להם קודם יבא להם אור השפע קודם במצות ק\"ש ולאנשי מערב יתאחר לבא להם השפע מ\"מ אין איחור והקדמה זאת ענינו שינוי כלפי מעלה ששם למעלה עדיין מענין הקדמה ואיחור כנ\"ל אלא שבכאן הוא מתחלק לזמן קדום או זמן מאוחר כו', וע\"כ אין מתחלף זמן מצות ק\"ש לפי המקומות אלא הכל שוין רק שיאיר היום כו', וכן במצות השבת שלמעלה הוא ענין בחי' הארת ספי' שאינה מספי' דיומין דחול כידוע אין זה ענין יום א' בזמן כי שם למעלה מהזמן, אך בבוא אור זה לעולמות מאיר דוקא ביום הז', ושינוי זמן יום הז' בהקדמה או באיחור לפי המקומות כנ\"ל אין זה שינוי כלל כלפי מעלה שבחי' השבת אשר למעלה הכל א' אך בעולמות מתחלק בהקדמה או באיחור לפי שינוי הזמן בימים שלהם לאנשי צפון יקדימו בליל שבת בימי החורף ואנשי דרום מאחרים ובליל מ\"ש בהיפוך ואין כ\"ז שום שינוי לגבי שבת שלמעלה כו' וד\"ל. וע' בשו\"ע של אדמ\"ו<sup data-n=\"513\">5</sup> א\"ח סי' א' סעי' ח' נת' כ\"ז בדרך קצרה.\n<b>וע\"כ</b> אמר ר' יוסי יהא חלקי ממכניסי שבת בטברי'<sup data-n=\"514\">6</sup> ומוציאי שבת בציפורי, ואם הי' מצות שבת רק יום מוגבל מעל\"ע גם למעלה אין בזה יתרון מצוה ממה שיקדי' יותר מדאי ויאחר לצאת יותר מדאי אלא מפני שהזמן הוא נברא ואנשי ציפורי מקיימין מצות שבת באיחורם וגם אנשי טברי' מקיימין בקדימה לפי הזמן שלהם וכלפי מעלה אין זה כתרתי דסתרי אהדדי מטעם הנ\"ל, דשם הוא למעלה מן הזמן ואינו שם ענין יום מוגבל מעל\"ע, ואעפ\"י שבאמת בזמן שהוא יום שבת לאנשי טברי' אינו יום שבת לאנשי ציפורי זהו כאן דוקא בבחי' הזמן משא\"כ למעלה. ומ\"ש ר' יוסי יהא חלקי אין ר\"ל במקום קיום יום השבת בפ\"מ דזה א\"א עפ\"י הטבע דאם הוא בדרום אינו בצפון ואם הוא בצפון מקדי' בכניסתו אינו מאחר ביציאתו ובדרום הוא בהיפוך וא\"א שיהיו שניהם כא' להקדים כמו בצפון ולאחר כמו בדרום, אלא ר\"ל יהא חלקי בשכר קיום יום שבת למעלה ששם למעלה מן הזמן וכל מה שנמצא קיום שבת בחלוקי הזמן הכל נסקר שם בסקירה א' וע\"כ ביקש שיעלה לשם חלקו בשכר בעוה\"ב מכל קיום מצוה שבא בבחי' התחלקות הזמן מטברי' וצפורי מפני ששניהם קיימו מצוה ולשניהם נמשך קדוש' אור השבת לזה בקדימה ולזה באיחור ולכן נתאוה שיהי' חלקו בשכר המשכ' קדושת אור השבת בריבוי יותר כקדימ' של זה ואיחור של זה, ר\"ל שיקבל השכר מהבחי' שנמשך לשניהם וד\"ל.\n&lt;מח&gt;",[["513","5","<b>בשו\"ע של אדמ\"ו</b>: בכת\"י רשום בש\"ע של רבינו, וכ\"ק אדמו\"ר הצ\"צ העביר ע\"ז קו למחיקה וכתב אדמ\"ו."],["514","6","<b>יהא חלקי ממכניסי שבת בטברי'</b>: שבת קיח, ב."]]],[2100490158,"<h3>ויהיו חיי שרה</h3>\n<b></b><b>בעזר\"ה ליל ש\"ק פ' חיי שרה, תקסוואו לפ\"ק</b>\n<b></b>[נוסח אחר מד\"ה להבין מאמר הזוהר פ' חיי\"ש]\nויהיו<sup data-n=\"515\">1</sup> חיי שרה מאה שנה ועשרים שנה ושבע שנים<sup data-n=\"516\">*1</sup>, ואיתא ע\"ז בזוהר (ד' קכ\"ב ע\"ב) אינון חיין כלהו לעילא, מאה שנה לעילא כו' אר\"ש ת\"ח רזא דמלה מאי שנא בכלהו דאמר שנה שנה ובאינון שבע דאמר שנים כו' אלא כלא חד מאה שנה כללא דכלא קב\"ה דאתכליל מאתר עלאה סתימא דכל סתימין, במאה ברזא דמאה ברכאן וכן עשרים שנ\"ה רזא דיחודא דלא אתפרש מחשבה ויובלא לעלמין, שבע שנים אלין אתפרשן ונפקאן מכללא סתימאה דלעילא ואע\"ג דכלא יחודא חדא אבל מתפרשן בדינא ורחמי בכמה סטרין ואורחין מה דלא הוה הכי לעילא מקדמת דנא ובג\"כ באלין שבע שנים כתיב בהו שנים ולא שנה וכולהו אקרון חיי שרה כו' ע\"ש.\n<b>הנה</b> אליהו פתח ואמר אנת<sup data-n=\"517\">2</sup> הוא דאפיקת עשר תיקונין וקרינן להון עשר ספירין, פי' ספירה<sup data-n=\"518\">3</sup> הוא מלשון ספי\"ר שמורה על בהירותן וזהרוריתן, שהאורות המלובשי' בתוכם אינם מכוסים ומוסתרים בהן כ\"א הם מזהירי' בהם ומתנוצצים על ידם דרך מעביר בעלמא ואינם מסתירים ומלבישים &lt;מט&gt;\nאותם כלל וכענין שנאמר כמראה<sup data-n=\"519\">4</sup> אבן ספיר דמות כסא דכמו הספיר מזהיר מאד ומאיר כך עד\"מ דמו' כס\"א העליון בחי' מל' דאצי' מקור דבי\"ע איננה מלבשת ומסתרת האורו' דאצי' בתוכה כ\"א האורות מאירי' על ידה לבי\"ע ואין הכלי מסתרת כלל מצד בהירותה שהיא כמראה אבן ספיר כו' דמו\"ת כס\"א שנמשלה לדמות ומראה (שקורין שפיגול בל\"א) נדמה דכמו המראה שמסתכל בה האדם מראה לנגדו תוארו ודמותו ממש בלי שינוי כלל ואעפ\"כ הוא הדמות שלו ולא עצם עצמו, כך עד\"מ מדת מל' דאצי' היא המראה והדמות עליון שמתגלין ע\"י אורות עליונים דאצי' כדמותן ממש בלי הסתר והגבלה כלל, כי הלבוש המכסה ומסתיר גורם שינוי לזולתו דהיינו כשיתראה האדם בלבושים אחרים אזי יגרום שינוי לזולתו שכאשר יסתיר פניו במסוה לא יכירנו חבירו כו' מצד הלבוש המסתיר עליו משא\"כ המרא\"ה שמראה דמותו כצלמו ממש ואעפ\"כ אין זה עצמותו זולתי דמות הנראה בתוך כלי המראה כו' כנ\"ל, כך ממש למעלה במל' דאצי' שנק' דמות העליון להראות ולגלות דמו' האורו' עליונים בבי\"ע בלי הסתר והלבשה כלל ואעפ\"כ אינם כצלמן שהי' באצי' מצד העברתן דרך הכלי כנ\"ל וכמו כל עשרה מאמרו' שבמל' דאצי' שבהן נבראו עולמות בי\"ע ויאמר<sup data-n=\"520\">5</sup> אלקים יהי אור הוא חסד שבמל' אין הכונה שכלי החסד שבמל' מסתיר האור א\"ס ב\"ה המלובש בו ונראה ליש ודבר נפרד בפ\"ע האומר להתהוות אור כ\"א עצמו' אור אין סוף מאיר הארתו דרך הכלי להתהוות אור כמ\"ש ויאמר אלקים הוא עצמו' אור אין",[["515","1","<b>ויהיו חיי שרה מאה שנה</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קפ, א). נמצא ג\"כ בכת\"י 207 יא, א. הנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' סו. וראה בהמ\"מ שם."],["516","*1","<b>ויהיו חיי שרה</b>: חיי שרה כג, א."],["517","2","<b>אנת הוא דאפיקת</b>: ראה הקדמת ת\"ז (יז, א)."],["518","3","<b>ספירה מלשון ספיר</b>: ראה לקו\"ת אמור לה, ב."],["519","4","<b>כמראה אבן ספיר</b>: יחזקאל א, כו."],["520","5","<b>ויאמר אלקים יהי אור</b>: בראשית א, ג."]]],[2100490159,"סוף ב\"ה יהי אור ויהי אור רק שעבר השפע דרך הכלי אבל אין הכלי מסתרת כלל שהיא ספיר\"ה כמראה אבן ספי\"ר כנ\"ל ועד\"ז כל הע\"ס דאצי' דקרינן לון עשר ספירי\"ן מצד הבהירות והזוהרות שלהן שאין מסתירים על האורו' זולתי הם כלים ותיקונין שלו שעל ידן נפעל פעולות האורות של המאציל והם מחברים אותו עם הנפעלים שהם תכשיטי\"ן דילי' ותיקונין שנתקנו לצורך פעולתו ית' כמשנת\"ל<sup data-n=\"521\">6</sup> בארוכה ע\"ש.\n<b>משא\"כ</b> הלבושים דמדו\"מ דאצי' שהמה מלבישים האורות המלובשין בתוכן בהעלם והסתר מצד שהמה לבושי' הנפרדים כמשנת\"ל, והיינו שדרך כלל נחלקים העשר תיקוני' עלאין לשני חלקים גדולי' והמה שכל ומדות, שכל כולל ג' מוחין חב\"ד, ומדות חג\"ת ונה\"י הם בחי' תחתונה שבהם שמתלבשי' בהלבושי' דמדו\"מ כנראה בנפש האדם שעצמו' המדו' א\"א להתגלות אפי' במחשבה כלל זולתי חיצוניותן בלבד הוא בחי' נה\"י שבהם השפעו' המדו' הם מתלבשי' בהמחשבה לחשוב הדבר ההוא המתאוה לו כו' וכן הדו\"מ כי שבשעת שנתלבשה חיצוניות המדה בהמחשבה אזי מוסתרת בתוך אותיות המחשבה ואותיו' המחשבה מלבישי' אותה ומסתירים עליה ממש ומכ\"ש הדבור ומעשה כנראה בעליל משא\"כ המדות כשהשכל מאיר בהן אינם מכסים ומסתירים עליהם כ\"א ניכר ונרגש פעולתו בהן כמו כשעובר השפע של השכל דרך המדות אל הדבור לדבר איזה מושכל לזולתו שאין המדות מסתירי' אותו כלל כ\"א מזהיר ומבריק דרך הכלי' של המדות &lt;נ&gt;\nאל הדבור בלי שום דבר חוצץ כלל ואין משתנה ע\"י עברו בהם כלל זולתי עיקר השינוי נעשה לאחר התלבשותו באותיו' הדבור שניכר השינוי לזולתו דלא קאים אינש אדעתא דרבי' כו' כנודע. וז\"ש אליהו ז\"ל על ע\"ס דאצי' אנת אפיקת עשר תיקונין וקרינן לן עשר ספירין כנ\"ל משא\"כ הלבושי' דמדו\"מ שמתלבשי' בבי\"ע כדכתיב כבוד\"י בראתיו יצרתיו אף עשיתיו שמכונה אותם בשם לבושי\"ן ולא בשם תיקוני\"ן כמ\"ש להלן לבושין תקינת להון דמינייהו פרחין נשמתא לב\"נ כו' וכנ\"ל.\n<b>והנה</b> נז' בס\"י<sup data-n=\"522\">7</sup> עשר ולא תשע עשר ולא אחד עשר כו' שכך עלה ברצונו הפשוט להיות נאצלי' רק עשר ספי' לא פחות ולא יותר שזהו צמצום גדול ועצום מאד, כי באמת המאציל ית' הוא כל יכול וכשמו כן הוא אין לו סוף ותכלה כלל לזאת הי' באפשרי להאציל רבוא רבבות ספי' שונות אין קץ כלל, אך כך עלה ברצונו הפשוט שייאצלו רק עשר ספי' ולא י\"א כו' כנ\"ל. והנה באמת למעלה מע\"ס הנאצלי' בעצמו' אור אין סוף הפשוט ימצא עדיין ג\"כ בחי' הכח לפעול רבבות ספי' אין קץ כלל רק הוא בכח הנעלם ולא בפועל ממש כי הוא פשוט בתכלית הפשיטות מושלל מגדר וסוג הספי' דאצי' שהם מהו' דבר מה מחולקי' זמ\"ז מהות החכמה שהוא מהו' בפ\"ע ומהו' בינה שהוא מהו' בפ\"ע ואחר שהם בגדר מספר שהם עשר במנין ומספר",[["521","6","<b>כמשנת\"ל בארוכה</b>: ראה לעיל ד\"ה פתח ואמר אנת הוא חד."],["522","7","<b>בס\"י עשר ולא תשע עשר</b>: פ\"א מ\"ד."]]],[2100490160,"משא\"כ לפני<sup data-n=\"523\">8</sup> אחד מה אתה סופר שהוא פשוט בתכלית הפשיטות כנ\"ל זולתי בכח הארתו להאציל רבוא רבבות ספירו' אין קץ ואינן מחולקים זמ\"ז בפ\"מ כ\"א רק בכח הנעלם בהארה בעלמא הפשוט שלו שכלא חשיבי קמי' עצמותו המאור ית' כביטול זיו השמש ואין שם עדיין מהו' דבר מה שאינו בגדר מספר כלל רק כחו עצום להיותו כל יכול לפעול רבבות ספי' והכח הזה הוא הארה בעלמא בטילה בו ית' כנ\"ל. אך הנה הכת\"ר<sup data-n=\"524\">9</sup> דאצי' הוא ממוצע בין המאציל לנאצלים כמ\"ש בכתבי אריז\"ל שכלול משתיהן שפנימיות הכת\"ר הוא בחי' תחתונה שבמאציל וחיצוניו' הכת\"ר הוא שרש הנאצלי' כנודע.\n<b>ולזאת</b> נאמר ויהיו חיי שרה מאה שנה, שמספר המא\"ה הוא בכת\"ר שרש הנאצלי' שכולל מספר הגדול שבכולם שע\"ס כלול כאו\"א מעשר שעולה בחשבון מא\"ה. אך זהו מצד היותו שרש הנאצלי' לכך הוא בגדר מספר שנק' בשם מא\"ה, אבל מצד היותו בחי' תחתונה שבמאציל הפשוט דלפני אחד מה אתה סופר רק הוא כל יכול בכח הארתו הפשוטה לפעול רבוא רבבות ספי' אין קץ אך הוא בלי מ\"ה כלל זולתי הארה בעלמא הפשוטה בתכלית הפשיטות ומיוחדת בו ליכלל ולהבטל כביטול זיו השמש במאור השמש ואין שם גדר מספר כלל, לזאת מצד זה נק' בשם שנה לשון יחיד מצד היותו בחי' תחתונה שבמאציל שלפני אחד מה אתה סופר שאינו בגדר מספר כלל רק אחדות פשוט בתכלית הפשיטות זולתי בכח הנעלם הפשוט לפעול רבבות ספי' בלי קץ וסוף כלל ולזאת הגם שנק' מאה שהוא בגדר מספר מצד היותו שרש הנאצלי' אעפ\"כ המאה זו נק' שנה מצד &lt;נא&gt;\nאחדותן במקורן בחי' תחתונה שבמאציל ב\"ה (זולתי מצד היותו שרש הנאצלי' והוא העליון שבכולם לכך אדרבה היא הנותנת שכשמצטרך להיות בגדר מספר יהיו מספר הגדול שבכולם) וזהו כמ\"ש בזוהר כבוצינא<sup data-n=\"525\">10</sup> דא דאתחזי בה כמה נצוצין וכד אסתכל בה אינה אלא בוצינא חדא שזהו בחי' הכ\"ע הממוצע בין המאציל לנאצלי' שהיא אתחזי לכמה ניצוצין היינו מצד היותו שרש הנאצלים שכולל המספר הגדול מספר מאה שע\"ס כאו\"א כלולה מעשר כו' וכד תסתכל בה אינה אלא בוצינא חדא דהיינו מצד היותו בחי' תחתונה שבמאציל שלפני אחד מה אתה סופר שאף המאה נק' בש' שנה לשון יחיד מטעם זה כנ\"ל וד\"ל.\n<b>ועשרים</b> שנה הנה או\"א<sup data-n=\"526\">11</sup> הם תרין רעין דלא מתפרשין לעלמין שזהו ענין ההתחדשו' תמידיי מאין לי\"ש כי החכמה<sup data-n=\"527\">12</sup> מאין תמצא ובינה<sup data-n=\"528\">13</sup> נק' יש כמ\"ש להנחיל<sup data-n=\"529\">14</sup> אוהבי י\"ש וגו' דזיווגיהו תדיר ולא פסיק להחיות עולמות כנודע, ולזאת נק' עשרים שנה פי' אע\"פ שהם במספר קטן יותר מן הכת\"ר שהם ביחד עשרי\"ם דהיינו החכמה כוללת ע\"ס בלבד וכן הבינה כוללת רק עשר ולזאת שניהם",[["523","8","<b>לפני אחד מה אתה סופר</b>: ספר יצירה פ\"א מ\"ז."],["524","9","<b>הכתר. . ממוצע</b>: ראה ע\"ח שער (מב) דרושי אבי\"ע פ\"א. סידור שו, ב."],["525","10","<b>כבוצינא דא דאתחזי</b>: ראה זח\"ג רפח, א."],["526","11","<b>או\"א תרין רעין</b>: ראה זהר ויקרא ד, א."],["527","12","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["528","13","<b>ובינה נק' יש</b>: נסמן לעיל ע' עב הערה 28."],["529","14","<b>להנחיל אוהבי יש</b>: משלי ח, כא."]]],[2100490161,"ביחד נק' עשרים אעפ\"כ הם כאחד שנ\"ה מצד היחוד תמידיי שלהן בלי הפסק כלל כנ\"ל והגם שהם בחי' נאצלי' רק מצד התלבשו' אור א\"ס ב\"ה בחכמה כנודע וחכמה מיוחדת בבינה שהם ריעים דלא מתפרשין לכך נק' שנה לשון יחיד, רק אינו דומה לבחי' הכת\"ר הממוצע בין המאציל לנאצלי' שיש בו מבחי' תחתונה שבמאציל ממש ולכך ימצא בו הכח דא\"ס לחדש רבוא רבבות ספי' והם בכח הנעלם בבחי' הפשוט בתכלית הפשיטו' שאינו בגדר מספר כלל ולזאת כשנעשה ראש ושרש לנאצלי' נתהוו ממנו מאה ספי' כנ\"ל משא\"כ חו\"ב שהם הם הנאצלי' ממש שכלולי' שניהם יחד רק מעשרים מצד שהם נאצלי' בבחי' ההתחלקות למהות דבר מ\"ה ואעפ\"י שאור א\"ס שורה בחכמה הוא רק בדרך השראה בלבד להיות ששורה בה בבחי' העלם ג\"כ כענין משה<sup data-n=\"530\">15</sup> רע\"ה שהי' בחי' יסוד אבא שאמר ונחנו<sup data-n=\"531\">16</sup> מ\"ה ואעפ\"כ אמר לו המאציל וראית את אחורי ופני לא יראה שלא השיג פנימיו' החכמה בחי' אור א\"ס השורה בכלי החכמה שלו כו', ואעפ\"כ מצד היחוד דאו\"א נק' עשרים שנ\"ה לשון יחיד כנ\"ל, משא\"כ הכת\"ר שהוא ממוצע ממש בין המאציל לנאצלי' שיש בו מבחי' תחתונה במאציל ממש כנ\"ל וד\"ל.\n<b>ושבע</b> שנים זהו בז\"א דאצי' שמתחלקים ז' מדות דידי' בהתחלקות נפרד ממש עד שהם הפכי' ומנגדי' זל\"ז כמו ב' מדות חו\"ג הם ענפין מתפרדין שהחסד הוא היפך הגבור\"ה אך המאציל ב\"ה עושה שלום במרומיו ע\"י מדת הת\"ת הממוצע המכריע ביניהם הכוללם יחד מצד גילוי אי\"ן האמתי בהם שמתבטלין ומתכללי' זב\"ז ואעפ\"כ מצד שימצא בהם הפרוד וההתחלקות אף שנכללי' זב\"ז נק' שבע שנים ל' רבים, שהם במספר קטן יותר מכולם מספר שב\"ע והם מתחלקי' בהתחלקות רבוי ופירוד להיותם נקראים שנים לשון רבים כנ\"ל, (והיינו בהיות ידוע שסדר הזמן דמל' דאצי' &lt;נב&gt;\nמקור דבי\"ע הוא בז\"א דאצי' מצד הפרוד וההתחלקות שלהם שהם בבחי' רו\"ש שזהו שרש הזמן כנודע לכך נק' שני\"ם לשון רבים וכמשי\"ת וד\"ל).\n<b>וזהו</b> ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים, פי' שרה<sup data-n=\"532\">17</sup> היא מדת מל' דאצי' מקור דבי\"ע כי תרגומו דשרה הוא מטרוניתא שהיא אימא תתאה מקור דבי\"ע כנודע ולזאת קמל\"ן קרא שחיי שרה הוא פנימי' החיים והאורו' הנמשכי' לתוך מדת המל' דאצי' מקור דבי\"ע הוא בגדר זמן כדכתיב ה'<sup data-n=\"533\">18</sup> מלך ה' מלך ה' ימלוך כו' שהתחלת הזמן ממש הוא ממל' דאצי' ואילך (משא\"כ קודם לכן באצי' שאינו רק סדר הזמ\"ן כנ\"ל כנודע שלכך מצות<sup data-n=\"534\">19</sup> עשה שהזמן גרמא נשים שנמשכו מעלמא דנוק' פטורות כו' לזאת לא ימצא בה בחי' מאה ועשרים שנ\"ה לשון יחיד שימצא בהם היחוד עליון שלמעלה מהזמן עד שאף",[["530","15","<b>משה. . יסוד אבא</b>: ראה לקו\"ש ח\"ו ע' 244. וש\"נ."],["531","16","<b>ונחנו מה</b>: בשלח טז, ז-ח."],["532","17","<b>שרה. . מלכות</b>: ראה לקו\"ת להאריז\"ל חיי שרה כג, ב."],["533","18","<b>ה' מלך. . מלך. . ימלוך</b>: ראה זח\"א לד, א."],["534","19","<b>מצות עשה שהזמן גרמא</b>: קידושין כט, א (במשנה). ראה ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ד."]]],[2100490162,"לאחר התחלקותן בגדר מספר נק' שנ\"ה שנה ל' יחיד כנ\"ל לזאת קמל\"ן קרא ויהיו חיי שרה מאה שנה ועשרים שנה כו' שאף המאה ועשרים שנה ימצא בה מצד שכל האורו' דאצי' נשפעים בה והיא כלולה מכולם והראי' שנמצא אף בבריאה בחי' הכת\"ר הכולל מא\"ה שנ\"ה שנמשך ממל' דאצי' מצד שנשפעו בה כל האורות דאצי' שהם החיים שלה ולזאת משפעת לבי\"ע ג\"כ להיות כתר דבריאה שנק' מאה שנ\"ה וחו\"ב דבריאה שנק' עשרים שנה כו' כנ\"ל וז\"ש להלן שני חיי שרה שזהו בחי' האורות הנמשכי' משרה מל' דאצי' להיות לחיים בבריאה להיות נעשה שם בחי' כת\"ר שהוא יחידה דבריאה שנק' מאה שנה כו' והיינו כענין תשובת<sup data-n=\"535\">20</sup> ר\"א ב\"ד שגעה בבכי' כו' שזהו בחי' יחיד\"ה בחי' אהבת מאד\"ך שמופשט מגדר כלי שאין שום כלי יכולה להכילנה כנודע אך לגבי אצי' נק' כל החיים של הכח\"ב דבריאה שנק' שם מאה ועשרים שנה כנ\"ל בשם שנים לשון רבים מצד מציאות הזמן שנמצא בבריאה שהתחלת התהוות הזמן הוא ממל' דאצי' ואילך כנ\"ל, משא\"כ חיי שרה הם מאה ועשרים שנ\"ה שאף לגבי אצי' נק' בשם שנה ל' יחיד כנ\"ל. וזהו כונת הזוהר קב\"ה דאתכליל מאתר עלאה כו' במאה ברכאן שכונתו כאן שקב\"ה הוא בחי' מל' שנק' שרה דאתכלילת מכלהון כנ\"ל, אך באמת אין כונת המאמר הזהר דרך כלל על ע\"ס דאצי' כ\"א כונתו דרך פרט שקב\"ה הוא מל' דנקודי' כו' ועד\"ז סובב הולך כל המאמר ודו\"ק.\n<b>ותמת</b><sup data-n=\"536\">21</sup> שרה בקרית ארבע וגו' פי' זהו בחי' ההסתלקות וההעלא' מ\"ן דמדת מל' דאצי' לחזור למקורה באצי' בחי' אור חוזר שזוהי ענין המיתה דשרה אל קרית ארב\"ע הוא ז\"א דאצי' היא חברו\"ן כנודע ויבא<sup data-n=\"537\">22</sup> אברהם לספוד לשרה ולבכותה וכמארז\"ל<sup data-n=\"538\">23</sup> אגרא דהספדא דלויי שזהו ההספד של אברהם שהוא בחי' חסד דאצי' שבא לספוד לשרה להעלותה ולהגביה אותה עי\"ז למקור שרשה כנ'\"ל ולעשות הכנ\"ה להמשיך האורו' שלה לרבקה שהיא ג\"כ מבחי' מל' דאצי' אך בחי' אחרת שתיקונה א\"א זולתי ע\"י יצחק גבורה דאצי' משא\"כ תיקן דשרה הי' ע\"י אברהם חסד דאצי' (וכמ\"ש במ\"א &lt;נג&gt;\nדשרה<sup data-n=\"539\">24</sup> היא כת\"ר שבמל' ורבקה חכמה שבמל' אחורי' של הכת\"ר כדכתיב וינחם<sup data-n=\"540\">25</sup> יצחק אחרי אמו אחרי דייקא) כו' כנ\"ל וד\"ל.",[["535","20","<b>תשובת ר\"א ב\"ד</b>: ע\"ז יז, א."],["536","21","<b>ותמה שרה בקרית ארבע</b>: חיי שרה כג, ב."],["537","22","<b>ויבא אברהם לספוד לשרה</b>: שם."],["538","23","<b>אגרא דהספדא דלויי</b>: ברכות ו, ב."],["539","24","<b>דשרה. . שבמל'</b>: ראה לקו\"ת להאריז\"ל חיי שרה כג, ב."],["540","25","<b>וינחם יצחק אחרי אמו</b>: חיי שרה כד, סז."]]],[2100490163,"<h3>ותוספת ביאור הדברים הנ\"ל</h3>\n<b></b><b>בעזרה\"י, ליל מש\"ק הנ\"ל</b>\nליל מוצאי ש\"ק הנ\"ל\n<b>ולתוספת</b><sup data-n=\"541\">1</sup> ביאור באר היטב הדברים הנ\"ל, הנה עשר תיקונין הם עצמו' הכלי' דע\"ס דאצי' שנקראי' בשם תיקונין מצד שהם הכלים המחוברים ומיוחדים בהאורות של המאציל ב\"ה דאיהו וגרמוהי חד ואינם בחי' לבושי' נפרדי' כהלבושי' דמד\"מ שהמה מכסי' ומסתירים עליהם מצד שהמה לבושים נפרדים ממש ואינם מחוברים אל העצם כלל כמשנ\"ת בארוכה (בש\"ק<sup data-n=\"542\">2</sup> פ' וירא ע\"ש) ומבשרי אחזה שהשכל והמדות אף שאינן מהות העצמות של הנפש אעפ\"כ הם מחוברים ומיוחדים בעצמות הנפש בתכלית היחוד שלא ישתנו ולא יתחלפו לעולם דהיינו כמו טבעי' מדת אהבה שאוהב לאיזה דבר בטבעו אזי לא ישתנה ולא יתחלף לעולם המדה זו להתחלף למהו' אחר לשנוא מאחר שאהוב לו בטבעו (וכמו שאהוב לו החיים ושנאוי לו המות כנודע) משא\"כ הלבושי' דמדו\"מ שהם מתחלפים כדכתיב כלבוש<sup data-n=\"543\">3</sup> תחליפ' כו' והיינו שיכול להחליף כמה וכמה מחשבות שונות אין קץ והגם שהמדות מתלבשי' בהמחשבה שמחשב ומהרהר הדבר הנחמד לו אין זה עצמות שלו כעצמו' המדה שלא תשתנה ולא ימירנה כנ\"ל כי הרי יכול להחליף צרופי אותיו' המחשבה ההם לחשוב היפך רצונו ותאותו כמו כשאוהב הממון יכול לחשוב במחשבתו היפך האהבה לזרוק אותם בים וכדומה (ודבר זה תלוי במורכב ופשוט שהמדו' הם עצם פשוט מיוחדי' עם הנפש משא\"כ המחשבה שמורכבת מאותיו' רבים לכך אף שמתיחדי' אין זה יחוד אמתי פשוט כ\"א מורכב לכך יכול להחליף ההרכבה והאריגה שלהן ולכך היא נפרדת וכמשל העיסה הנבללת מכמה חלקים קטנים ביחד שאינה דומה לעצמו' גוש פשוט כ\"א היא מורכבת כמ\"ש במ\"א בארוכה ע\"ש) ולזאת מחדו\"מ הם לבושי' נפרדים שהאדם מתלבש בהן והם מלבישים אותו והם כלבוש תחליפם כו' כנ\"ל משא\"כ עשר תיקונין שהם ע\"ס שבנפש שהם מחוברים ומיוחדים עמה בתכלית היחוד וכמ\"כ ממש למעלה בכלים דאצי' דאיהו וגרמוהי חד משא\"כ בי\"ע כו' כמשנת\"ל בארוכה.\n<b>והנה</b> לא זו בלבד שהאותיו' של המו\"ד ופעולת המעשה המה נפרדי' אלא אפי' הכחו' שלהן הם לבושי' נפרדים דהיינו כח המחשבה וכח הדבור וכח המעשה כו'.\n&lt;נד&gt;\n<b>ביאור</b> ענין כח, הנה חכמי המקובלים קראו וכינו לכל מהות כח בשם או\"ר שהכל א' ומבשרי אחזה כמו כאשר יזרוק האדם בחמת כחו אבן הרחק כמטחוי קשת שהכח היוצא מהיד וישא האבן בריחוק מקום נק' בשם או\"ר שאור וכח שיצא מן היד הוא נושאו את האבן בריחוק מקום ומנשאו שלא יפול לארץ כו' (שאין האור בקע דרך עור היד לישא האבן מצד שהוא כח רוחניי שאין לו שייכו' הסתרת העור כו') וכן כח הדבור הוא בחי' אור וכח המתפשט מהנפש וכן הכח של המחשבה שכ\"ז",[["541","1","<b>ולתוספת ביאור</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קפד, ב).\nהנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' עו."],["542","2","<b>(בש\"ק פ' וירא ע\"ש)</b>: ראה לעיל ד\"ה פתח ואמר אנת הוא חד."],["543","3","<b>כלבוש תחליפ'</b>: תהלים קכ, כז."]]],[2100490164,"הם לבושי הנפש כנ\"ל וד\"ל. והנה נז' בכ' אריז\"ל שמיחוד העליון דאצי' דת\"ת ומל' דאצי' נמשכי' הנשמות הגבוהות מאד כנודע ואף מיחוד ת\"ת ומל' דבריאה יצירה נמשכים הנשמות המעולים כו' משא\"כ מיחוד ת\"ת ומל' בנר\"נ דעשי' שנשמה דעשי' הכלי היא בחי' נברא והאור הוא בחי' אלקות משא\"כ נפש ורוח דעשי' שאף האורו' שלהן הם בחי' נברא ולזאת מזווג שלהן נבראים נשמות של לומדי התורה נגלית ויוכל להיות חכם גדול בתורה נגלית וגם ירא שמים ומקיים מצות גשמיות הן בבחי' סור מרע והן בחי' ועשה טוב כו' ויש עוד יחוד חיצוניי דעשי' שנמשכי' נשמת עמי הארץ אעפ\"כ יכול להיות חכם בחכמו' חיצוניות בשבע מיני חכמו' כו' נמצא שמהארה בעלמא דלמעלה יסתעף למטה מהו' נברא בר שכל שהטפה הנמשכ' מהדכר היא הארה בעלמא חיצוניות ממנו כנודע וכ\"ז הוא סדר ההשתלשלות דאבי\"ע מל' דאצי' נעשה עתיק דבריאה וכן מל' דיצירה כו' שבחי' תחתונה של עולם העליון נעשה ראש לעולם התחתון כו' עד שאפי' מיחוד חיצוני דעשי' נבראים הנשמות עם שכל ומדות כו' כנ\"ל.\n<b>אבל</b> אנת<sup data-n=\"544\">4</sup> הוא חד ולא בחושבן שהתהוות החכמה מעצמו' ית' אינו בגדר ההשתלשלות מצד שאין לה ערך ויחס אליו כלל שהחכמ\"ה<sup data-n=\"545\">5</sup> מאי\"ן תמצא, פי' שלגבי המאציל ב\"ה אף החכמה נק' בחי' יש מהו' דבר מ\"ה משא\"כ עצמו' אור אין סוף פשוט בתכלית הפשיטות בלי מ\"ה כלל, ולזאת אור החכמה שמאין תמצא איננה עולה בשם דבר מ\"ה כלל להיות נק' בשם חכמה מצד שהאור החכמה עצמו כשנמשך מאור א\"ס ב\"ה הוא עדיין פשוט בתכלית הפשיטות בחי' עצם פשוט היולי עד שאינו עולה בשם כלל כ\"א הוא רק בחי' ההשפעה של אור א\"ס שיוכל להיות נתהוה ממנה הכל או חכמה או חסד או נצח כו' ואין לו עדיין שייכות אל כלי החכמה יותר משאר הכלי' מצד שאינו בחי' מהו' דבר מ\"ה כלל זולתי כח ההיולי עצם פשוט שיוכל להצטייר ממנו מהו' חכמה ומהו' חסד כו' רק כיון שנכנס ומתלבש בתוך הכלי של החכמה אז משתנה מצד הכלי למהו' דבר מ\"ה להיותו נק' בשם חכמה ששייך אליה יותר מן השאר כו' (וכמ\"ש במ\"א כמשל המים שאין להם גוון זולתי משתנה לפי גוון הכלי כו' ע\"ש) וזהו והחכמ\"ה מאי\"ן תימצא מבחי' אי\"ן שהוא עצמו' אור אין סוף הפשוט בלי מהו' דבר מ\"ה כלל שבהגע' אור החכמה לתוך הכלי אז נק' ע\"ש בשם חכמה כנ\"ל. וזהו מ\"ש בס\"י<sup data-n=\"546\">6</sup> עשר ספירות בלי מ\"ה, פי' בלי מהות כלל מצד שהאורו' עצמן הם &lt;נה&gt;\nפשוטי' בלי מהו' כלל זולתי ע\"י הכלי' נעשו מהו' ודבר מ\"ה להתחלק לעשר ולהיות בגדר מספר משא\"כ בעודן בשרשם נעלמי' בעצמו' אור אין סוף הי' בלי מ\"ה כמשנת\"ל שבכח הנעלם דעצמו' אור אין סוף הוא לחדש חדשים רבוא רבבות ספי' שונות אין קץ כלל אך הם בלי מ\"ה רק בכח הנעלם הפשוט דהארת אור אין סוף ב\"ה שהוא הארה בעלמא הבטילה בו ית' ואינה מהות דבר מ''ה שאז הי' בגדר מספר כ\"א הם בלי מ\"ה בכח הנעלם הפשוט שלו ית' שהוא כל יכול כנ\"ל (כך שמע ממורו ע\"ה שזהו פי' ע\"ס בלי מ\"ה) רק",[["544","4","<b>אנת הוא חד</b>: תקו\"ז בהקדמה (יז, א)."],["545","5","<b>שהחכמה מאין תמצא</b>: איוב כח, יב."],["546","6","<b>בס\"י עשר ספירות בלי מ\"ה</b>: פ\"א מ\"ב."]]],[2100490165,"הכת\"ר<sup data-n=\"547\">7</sup> שהוא ממוצע בין המאציל לנאצלי' שיש בו בחי' המאציל והנאצלי' שכלול משתיהן לכך נק' מא\"ה שנ\"ה שמצד היותו שרש הנאצלי' הוא בגדר מספר מא\"ה שנ\"ה שנעשה הספי' מהו' דבר מ\"ה להיותם בגדר מספר עשר ספי' וכאו\"א כלולי' מעשר כו' רק מצד היותו בחי' תחתונה שבמאציל ב\"ה היחיד ומיוחד שלפני<sup data-n=\"548\">8</sup> אחד מה אתה סופר לכך נק' שנה לשון יחיד כנ\"ל וד\"ל.",[["547","7","<b>הכתר. . ממוצע</b>: ראה ע\"ח שער (מב) דרוש אבי\"ע פ\"א. סידור שו, א."],["548","8","<b>שלפני אחד מה אתה סופר</b>: ס\"י פ\"א מ\"ז."]]],[2100490166,"<h3>אני הנה בריתי אתך</h3>\n<b></b><b>שנת תקסואו בעזרה\"י, יום חמישי פ' תולדות </b>\nיום חמישי פ' תולדות\nתורה ברבים, בסעודת מצוה, בברית מילה<sup data-n=\"549\">1</sup>\nאני<sup data-n=\"550\">*1</sup> הנה בריתי אתך*<sup data-n=\"551\">**1</sup> והיית לאב המון גוים, ולא יקרא עוד את שמך אברם והיה שמך אברהם כי אב המון גוים נתתיך.\n<b>איתא</b><sup data-n=\"552\">2</sup> במדרש בשאלת ההיא מטרוניתא אם הי' מצטרך להיות הולד נמול היה נולד מהול ומפני מה נברא בערלה ומשנין סדר הבריאה למולו כו' והתשובה הי' לה כהאי תורמסא<sup data-n=\"553\">3</sup> דצריכא מיתוק עד דשלקי לי' ז\"פ כו' ע\"ש.\n<b>והענין</b> דהנה כתיב כי<sup data-n=\"554\">4</sup> בו שבת מכל מלאכתו אשר ברא אלקי' לעשות<sup data-n=\"555\">5</sup> פי' לתק\"ן דהיינו שעד\"ז הי' הבריאה של כל מלאכתו אשר ברא בעולמו שיצטרכו ישראל אח\"כ לעשות פי' לתק\"ן מצד שלא גמר מלאכתו בשלימו' אלא הניח להם לישראל שיגמרו ויתקנו מלאכתו אשר ברא בשלימות והיינו כהאי תורמסא שנברא מר וע\"י שילוקו ז' פ' מתמתק וכן המילה שהולד נוצר בערלה ולאחר שנולד מתקנין ישראל בהכרתת הערלה שזהו גמר מלאכתו בשלימות כנ\"ל.\n<b>ובאור</b> הענין הנה נאמר ובטובו<sup data-n=\"556\">6</sup> מחדש בכל יום תמיד מעשה בראשית, מחדש ממש מאין לי\"ש תמיד בכל יום ובכל עת ובכל שעה, והיינו &lt;נו&gt;\nדכמו שהי'",[["549","1","<b>בברית מילה</b>: ברי\"מ של כ\"ק ר' ברוך שלום בן כ\"ק אדמו\"ר הצ\"צ. וראה לקמן ע' קצח, רא."],["550","*1","<b>אני הנה בריתי אתך</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קפז, א). הנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נדפס בסידור קמה, א. הנחה אחרת נדפס בתו\"א יב, א.\nהמאמר עם הגהות נדפס באוה\"ת בראשית כרך ד תשטו, א. וראה שם תשיז, א. תשיג, א. וראה מאמרי אדה\"א הנחות תקע\"ז ע' עדר ואילך."],["551","**1","<b>אני הנה בריתי אתך</b>: לך יז, ד."],["552","2","<b>איתא במדרש בשאלת ההיא מטרוניתא</b>: ראה ב\"ר פי\"א, ו."],["553","3","<b>תורמסא. . ז\"פ</b>: ראה ברכות לח, ב."],["554","4","<b>כי בו שבת מכל מלאכתו</b>: בראשית ב, ג."],["555","5","<b>לעשות פי' לתקן</b>: ראה פרש\"י לב\"ר יא, ז. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתסח. דברים ח\"ד ע' א'רט."],["556","6","<b>ובטובו מחדש בכל יום תמיד</b>: ברכת יוצר."]]],[2100490167,"במקדש שלמטה בחי' פרוכת<sup data-n=\"557\">7</sup> המבדילות בין קודש לקודש הקדשים ובהיכל ובדביר כו' שתרגומו של פרוכ\"ת הוא פרס\"א כו' כך עד\"מ בדוגמא זו למעלה בחי' ירידת השפע עליונה של אור אין סוף לצורך חיות וקיום העולמות כולן שעוברת השפע דרך מסכים רבים שנק' בחי' פרסות המבדילות בין קודש לק\"ק כו' והיינו דכמו הפרוכת המסך המסתיר אור הנר כדומה והאור זורח הוא שם דרך מעביר המסך שאז נשתנה האור המגיע להאדם שאחורי הפרוכת מכמו שהי' מקדם הפרוכת, שאינו מאיר כ\"כ מצד הסתרת הפרוכת, כך עד\"מ למעלה בירידת השפע עליונה אל הנבראים דרך פרגודי' ומסכים רבים שעי\"ז נשתנה השפע המגיע אל הנבראי' מה שלאחר הפרגוד מכמו שהי' מקדם באופן ההגשמה שלה שנעשו מהו' אחר ממש מחודש באופן הגשמתה מה שלא הי' מעולם באופן ההגשמה זו מקדם העברתה דרך הפרגוד ומסך הנ\"ל שזה גרם השינוי שלה בחי' הסתרת הפרסא ומסך הנ\"ל שמדי עברה בה נשתנה לגריעותא למהו' י\"ש מחודש מה שלא הי' מקדם כלל באופן זה כנ\"ל, וזהו ענין התחדשו' הנבראים מאי\"ן ליש מחודש שנתהוו מבחי' השפע עליונה שעברה דרך הפרס\"א המבדלת בין קודש לק\"ק שע\"י עברה דרך הפרסא נשתנה למהו' יש מחודש מה שלא הי' מקדם שבחי' השפע שקודם הפרס\"א נק' לגבה בחי' אי\"ן, וזהו ובטובו מחדש דוקא מאי\"ן לי\"ש מחודש מעשה בראשי\"ת היינו כדכתיב כולם<sup data-n=\"558\">8</sup> בחכמה עשית וראשי\"ת חכמה מאי\"ן תימצא כנודע, וכ\"ז ההתחדשו' מאי\"ן ליש הוא מצד הפרסו' המבדילות כנ\"ל אבל לולא זאת אם היתה השפע יורדת דרך סבת ההשתלשלות מעילה לעלול בלי מסכי' ופרסו' כלל לא הי' נק' זה בחי' התחדשות כלל כי מאחר שהשפע עליונה כמו שהי' למעלה בהעילה היא יורדת למטה אל העלול הגם שנתמעטה במיעוט אחר מיעוט אעפ\"כ מאחר שלא הי' מסך מבדיל בין העילה להעלול אזי לא נשתנה השפע ממהותה הראשון למהו' אחר מחודש ממש כ\"א כמות שהיא בהעילה כך היא במהותה ואיכותה בהעלול (רק במיעוט וצמצום מעט כו'), ולכך נעשו הפרסות להבדיל בין קודש לק\"ק כו' בכדי שיתחדשו הנבראי' המחודשי' מאי\"ן לי\"ש מחודש ממש כנ\"ל, וז\"ש במשכן והבדילה הפרוכת לכם בין קודש לקודש הקדשים כו' בהיות במשכן ובמקדש הי' עיקר השראת השכינה בבחי' גילוי ממש בהיכל ק\"ק ששם היה הארו\"ן וכרובי' פורשי כנפי' למעלה כו' שההיכל ק\"ק שלמטה במקדש הי' הכלי ומכון לשבתו ית' שנעשה בדוגמא דלעילא שיש למעלה ג\"כ בחי' היכל ק\"ק שבו עיקר גילוי השראת השכינה ב\"ה ולזאת הבדילה הפרוכת בין קודש ובין ק\"ק דכדי שהמשכת השפע דזיו השכינה ב\"ה מהיכל ק\"ק מצטרך להיות דרך מעבר הפרוכ\"ת שתרגומו פרס\"א כו' וכנ\"ל וד\"ל.\n<b>והנה</b> כ\"ז הוא בחי' הפרוכ\"ת המבדילות בין קודש לקדש הקדשי' וכמו במקדש<sup data-n=\"559\">9</sup> שני היו י\"ג פרוכת כדאמרי' בגמ' כך ממש למעלה ימצא כמה וכמה",[["557","7","<b>פרוכת המבדילות בין קדש לקודש הקדשים</b>: ראה תרומה כו, לג."],["558","8","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["559","9","<b>במקדש שני היו י\"ג פרוכת. . בגמ'</b>: יומא נד, א."]]],[2100490168,"פרסאות ומסכי' המבדילות בין עולם העליון לעולם התחתון &lt;נז&gt;\nועולמות אין מספר כלל שכ\"ז הוא באלקות וקדושה ממש להבדיל בין קדושה שבעולם העליון לקדושה שבעולם התחתון ממנו שזהו והבדילה הפרוכת בין קדש ובין קדש הקדשי' שאף מה שלאחר הפרוכ\"ת נק' קד\"ש ורק שאינו קדש הקדשי' כו' כנ\"ל.\n<b>אך</b> לאחר רבוי ההשתלשלות ומסכי' רבים ההם אזי בתכלית כל סדרי ההשתלשלות עלה שהוא עולם העשי' שהוא תכלית וסוף כל דרגין שלמעלה שאין למטה הימנו במדרגה, ימצא עוד בחי' פרוכת ופרס\"א המבדי\"ל בין קודש לחול וכמ\"ש בהבדלה<sup data-n=\"560\">10</sup> דמ\"ש המבדיל בין קודש לחול כו' ובין ישראל לעמים ובין יום השביעי כו' שזהו מסך עב וגשמיי יותר שכמוהו לא הי' לפניו בכל סדרי ההשתלשלות בהפרסו' המבדילות בקדושה עצמה בין קודש לקודש הקדשים כו' מפני שהפרסות והמסך העב הזה מבדיל בין קודש לחו\"ל, בכדי שיוכל להתמשך בחי' קליפת נוג\"ה דעשי' הם כל המאכלי' היתר דעשי' ותדשא<sup data-n=\"561\">11</sup> הארץ דשא עשב וזריעת תבואות<sup data-n=\"562\">12</sup> השדה היוצא שנה בשנה כי אין<sup data-n=\"563\">13</sup> לך עשב כו' שאין לו מזל כו', ויש עוד פרסא עב וגשמיי מהראשונה בכדי שיתהוו ע' שרים דקליפה ממש דכתיב רם<sup data-n=\"564\">14</sup> על כל גוים ה' שאל מסתתר מהם בבחי' התנשאות והתרוממו' עד דקרו<sup data-n=\"565\">15</sup> לי' אלהא דאלהא והם בעצמם בחי' נפרדי' ממש וכדכתיב הודו<sup data-n=\"566\">16</sup> לאלקי האלקי' כל\"ח שזהו גורם הפרסא והמסך העב הזה להסתיר גילוי כבודו ית' מהם שיהי' רם על כל גוים דקרו לי' אלקי האלקי' בלבד וכדכתיב ואתה<sup data-n=\"567\">17</sup> מחי' את כולם שאין לך דבר שחוץ ממנו ית' רק החיות שלהם הוא ע\"י מסכים עבים וגשמיים הנ\"ל וכדכתיב אלביש<sup data-n=\"568\">18</sup> שמים קדרות ושק אשים כסותם וגו' שזהו המסך העב הגשמיי הזה שנק' בחי' לבוש ש\"ק כנודע.\n<b>והנה</b> יש ב' בחי' ומדריגות שונות בבחי' החו\"ל עצמו, והיינו החול דישראל אף שנבדל מן הקדש כמ\"ש המבדיל בין קדש לחול שהמבדי\"ל הוא הפרסא העב הנ\"ל, אעפ\"כ נבדל הוא מהחול דאוה\"ע דהיינו שהחול שלהם הוא למטה יותר עד שיש עוד פרסא המבדיל בין הטמא לטהור שבחול עצמו, והענין שבחי' החו\"ל דישראל נק' בחי' חולי\"ן<sup data-n=\"569\">19</sup> שנעשו על טהרת הקודש כו' בחי' חולו של מוע\"ד והיינו שנמשך להם מקדושת שבת שלעבר לג' יומין קמייתא הארת שבת ותלת יומא בתריתא הם הכנה לשבת הבאה וכמאר\"ל מי<sup data-n=\"570\">20</sup> שטרח בע\"ש יאכל בשבת ופי' שכל",[["560","10","<b>בהבדלה</b>: ראה דרך מצותיך מצות מילה ז, ב."],["561","11","<b>ותדשא הארץ דשא</b>: בראשית א, יא."],["562","12","<b>תבואות השדה היוצא שנה בשנה</b>: דברים יד, כב — תבואות זרעך היצא השדה שנה שנה."],["563","13","<b>כי אין לך עשב כו'</b>: ראה ב\"ר פ\"י, ו. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. ע' תתעו ואילך."],["564","14","<b>רם על כל גוים ה'</b>: תהלים קיג, ד."],["565","15","<b>דקרו לי אלהא דאלהא</b>: מנחות בסופה."],["566","16","<b>הודו לאלקי האלקים כל\"ח</b>: תהלים קלו, ב."],["567","17","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["568","18","<b>אלביש שמים קדורות</b>: ישעי' נ, ג."],["569","19","<b>חולי\"ן שנעשו על טהרת הקדש</b>: חגיגה יט, ב. וש\"נ. וראה ג\"כ תו\"א משפטים עז, ד. לקו\"ת פנחס עז, ב. דרך מצותיך ח, א. ס' המאמרים ה'ת\"ש ע' 57. סה\"מ תרכ\"ו ע' א. לקו\"ש חי\"ג ע' 108 הערה 36."],["570","20","<b>מי שטרח בע\"ש יאכל בשבת</b>: ע\"ז ג, א."]]],[2100490169,"ל\"ט מלאכות שאסורי' בשבת ומותרי' בחול הוא בחי' עבודת האדם בחול<sup data-n=\"571\">21</sup> במלאכת הברורין לאתהפכא מחשוכא לנהורא וממרירו למיתקא ע\"י המעשה של האדם אשר יעשה האדם בכל ל\"ט מלאכות בזריעה וחרישה וקצירה כו' וחי בהם לפרנס א\"ע ואח\"כ יתפלל בכח האכילה ההיא וכדומה שעי\"ז יתהפך מחשוכא לנהורא וממרירו למיתקא ולהעלותן כולו לה' אחד ב\"ה, ולזאת נעשה הפרוכת היא הפרסא המבדיל בין קודש לחו\"ל, בכדי שיהי' חו\"ל ויוכלו ישראל לעבוד עבודה זו של ששת ימי המעשה דכתיב<sup data-n=\"572\">22</sup> ששת ימים תעבוד ועשית כל מלאכתך דייקא וכתיב יגיע<sup data-n=\"573\">23</sup> כפיך כי תאכל יגיע כפך דיקא בכדי שיחדש האדם דבר בעצמו ע\"י מלאכתו &lt;נח&gt;\nאשר עשה בו' ימי החול להזריע זרע בארץ וימצא אח\"כ מאה שערים שתתחדש תבואו' השדה חדשי' הבא מכח עבודת האדם דוקא ואח\"כ יהפך אותם לקדושה ממרירו למיתקא ולזאת א\"א להיות זולתי הפרסא המבדיל בין קדש לחו\"ל דאל\"כ הי' כולו קדושה והי' נגלה כבודו ית' בבחי' גילוי לעיני כל עם הארץ ואז בלתי אפשר הי' להאדם לעבוד מלאכתו בכל ששת ימי המעשה ולעשות צרכיו מחמת גודל עוצם הביטול לפני כבודו ית' עד שלא יוכל להרים יד במלאכת צרכיו זולתי יהי' בבחי' הביטול תמידי לפני כבודו ית' וכמו עד\"מ במלך ב\"ו כשהעבד עומד ורואה פני המלך אזי אם ירים יד במלך או יעשה איזה מלאכה לפניו מתחייב ראשו למלך כדאי' במדרש במעשה שהרים ידו לפני המלך וקטע ידו כו' וגם לא יוכל האדם לחדש דבר מעצמו מאחר שניכר פעולתו ית' שממך הכל ואפס זולתו כו' כנ\"ל וד\"ל)<sup data-n=\"574\">24</sup> והיינו וכמו תפלת<sup data-n=\"575\">25</sup> ש\"ע שאסור להרים יד כו' כ\"א יעמוד בביטול אמיתי בכריעו' והשתחוואו' דח\"י ברכאן כו' וכן בשבת<sup data-n=\"576\">26</sup> הוא בחי' מנוחה, כדכתיב וביום<sup data-n=\"577\">27</sup> השביעי שבת להוי' אלקיך לא תעשה כל מלאכה וגו' מצד התגלות כבודו ית' למטה שמצטרך להיות בחי' הביטול אמיתי לשבות מכל מלאכה ולא לקבל חיות משום דבר בעולם זולתי יהי' נזון מכבודו ית' שאף האכילה לא הותרה אלא המוכן מע\"ש כו' משא\"כ בחול שמצטרך האדם לעבוד בכל מלאכתו בכדי לאהפכא ממרירו למתיקא ושיהי' האדם מחדש דבר מעצמו לכך נעשה הפרסא להבדיל בין הקדש לחול בכדי שיהי' נסתרה דרכי ה' ויתראה העולם ליש ודבר בפ\"ע ויוכל האדם לעבוד ויעשה כל מלאכתו כו' כנ\"ל וזהו אשר ברא אלקים לעשות פי' לתק\"ן לאתהפכא ממרירו למתיקא שזהו המצוה<sup data-n=\"578\">28</sup> של העבודה בו' ימי המעשה שזהו בחי' חולין שנעשו על טהרת הקודש בחי' חולו של מועד מפני שעיקר הכונה בעובדין דחו\"ל לעשות את<sup data-n=\"579\">29</sup> שמי שטרח בע\"ש יאכל בשבת שהעובדי' דחול בההתהפכו' ממרירו למתיקא הוא לצורך השבת",[["571","21","<b>בחול במלאכת הבירורין</b>: ראה לקו\"ת תזריע כ, ד. תו\"ח בראשית לא, ד. שמות [הוצאת קה\"ת — תשס\"ג] תיא, ג."],["572","22","<b>ששת ימים תעבוד</b>: שמות כ, ט."],["573","23","<b>יגיע כפיך כי תאכל</b>: תהלים קכח, ב."],["574","24","<b>וד\"ל)</b>: בכת\"י חסר התחלת המוסגר."],["575","25","<b>תפלת ש\"ע. . יעמוד בביטול</b>: ראה תניא פל\"ט (נג, א)."],["576","26","<b>בשבת הוא בחי' מנוחה</b>: ראה פרש\"י בראשית ב, ב. וראה הנסמן לעיל ע' ס."],["577","27","<b>וביום השביעי שבת להוי' אלקיך</b>: יתרו כ, י."],["578","28","<b>המצוה של העבודה בו' ימי המעשה</b>: מכילתא הובאה בדרשות ר' יהושע אבן שועב פ' וישב ובס' מנחה בלולה פ' יתרו כ, ט. לקו\"ש ח\"א ע' 189 הערה 8. חל\"ג ע' 143 הערה 40."],["579","29","<b>את</b>: בהכת\"י חסר תיבה."]]],[2100490170,"בכדי שיתעלה אח\"כ השפע עליונה של הקב\"ה מה דלא סגי בלא\"ה כדכתיב ששת<sup data-n=\"580\">30</sup> ימים תעבוד כו' וביום השביעי שבת לה' אלקיך לא תעשה כל מלאכה שכ\"ז מציאות הביטול שבשבת בבחי' מנוחה בא ונסתעף מעובדי' דחו\"ל כו' כנ\"ל ולכך נק' חולו של מועד חולי\"ן שנעשו על טהרות הקדש וכנ\"ל וד\"ל. משא\"כ החול דאוה\"ע שהוא חו\"ל גמור כדכתיב אשר<sup data-n=\"581\">31</sup> חלק ה' אותם לכל העמים כו' שהם בחי' יש ודבר נפרד גמור ולא יסתעף מהם אח\"כ ההתהפכו' לקדושה עד עת קץ שיבולע<sup data-n=\"582\">32</sup> המות לנצח ורוח הטומאה יעבר כו' לכך יש עוד פרסא המבדיל בין ישראל לאומות כו' ובין הטהור לטמא וכמארז\"ל בשבע הבדלות והבדלתם<sup data-n=\"583\">33</sup> בין הטמא כו' וד\"ל.\n<b>וזהו</b> ענין בחי' המילה שקודם המילה נק' אב<sup data-n=\"584\">34</sup> רם ולאח\"כ אברה\"ם כי<sup data-n=\"585\">35</sup> אב המון גוים נתתיך כו' והיינו כי הנה כתיב נעשה<sup data-n=\"586\">36</sup> אדם בצלמינו &lt;נט&gt;\nכדמותינו שנברא האדם בצלם ודמות העליון, לכך נברא בערלה המכסה על הברית בהיות אבר זה המשפיע שימצא בו בחי' המוליד מצטרך להיות נברא בערלה המכסה עלי' ואח\"כ יתתקן ע\"י ישראל להעביר ולכרות הערלה כו' מפני שהוא בדוגמא שלמעלה שהערלה למעלה הוא בחי' הפרסא המכסה על ברית קדישא בחי' צדיק עליון המשפיע החיים לכל הנפעלי' שנאמר ובטובו מחדש בכל יום מע\"ב מחדש דוקא מאין ליש מצד הסתרת המסכי' והפרסו' שהאור הנולד מבחי' הפרסא נק' אור התולדה שהוא בחי' התחדשות גמורה מאין ליש ממש עד שבההשתלשלות רבות ומסכים רבים נסתעף למטה בחי' הפרסא המבדיל בין קדש לחו\"ל עד שיסתעפו בחי' התהוות הגויים שיהי' רם על כל גוים הוי' דקרו לי אלהא דאלהא כדכתיב הודו לאלהי האלהים וגו' כנ\"ל, וזהו בחי' א\"ב ר\"ם פי' א\"ב<sup data-n=\"587\">37</sup> הוא בחי' החכמה עליונה שמאין תימצא שהיא בחי' ראשית הגילוי מעצמו' אור אין סוף ב\"ה שהוא מקור החיים שלמטה שהוא עיקר המשפיע החיים לכל הנפעלי' לחדש חדשים מאי\"ן ליש ממש כמאמר ובטובו מחדש בכל יום מעשה בראשית דוקא וכתיב ראשית<sup data-n=\"588\">38</sup> חכמה שנק' ראשית שמשם מקור ההתחדשות מאין לי\"ש כנודע, ור\"ם הוא מצד הפרסא המבדיל בין קדש לחול עד שיסתעפו בחי' אוה\"ע שהם בחי' יש נפרד ממש דקרו לי' אלהא דאלהא כי רם על כל גוים ה' ולכך נברא אאע\"ה בערלה בדוגמא דלעילא שאז הי' נק' א\"ב ר\"ם מצד שרשו הנעלה שהוא בחי' הח\"ע לכך נק' א\"ב ומצד הערלה החופה על האבר המשפיע שלמעלה בכדי שיהי' רם על כל גוי\"ם נק' ר\"ם. אך לאח\"כ כשנצטוה על המיל\"ה להעביר הערלה הוא הפרסא המבדיל בין קוד\"ש לחו\"ל אזי נק' אברה\"ם<sup data-n=\"589\">39</sup>",[["580","30","<b>ששת ימים תעבוד</b>: יתרו כ, ט."],["581","31","<b>אשר חלק ה' אותם לכל העמים</b>: דברים ד, יט."],["582","32","<b>שיבולע המות לנצח</b>: ישעי' כה, ח."],["583","33","<b>וכמארז\"ל בשבע הבדלות והבדלתם בין הטמא</b>: שמיני יא, מז. פסחים קג, ב."],["584","34","<b>אב רב</b>: ראה זהר (סתרי תורה) לך עט, ב."],["585","35","<b>כי אב המון גוים נתתיך</b>: לך יז, ד."],["586","36","<b>נעשה אדם בצלמינו</b>: בראשית א, כו."],["587","37","<b>אב הוא בחי' החכמה</b>: ראה זהר (אדרא זוטא) האזינו רצ, א. ראה תניא פ\"ג. ביאורי הזהר ויצא טז, ג. בלק קג, ב. לקו\"ת שה\"ש יג, סע\"ד."],["588","38","<b>ראשית חכמה. . שנק' ראשית</b>: תהלים קיא, י. וראה זהר בראשית לא, ריש ע\"ב. וראה גם פלח הרמון ר\"פ בראשית."],["589","39","<b>אברהם. . להוסיף גרים מאוה\"ע</b>: ראה ב\"ר פל\"ט, יד הובא ברש\"י לך יב, ה. וראה לקו\"ש ח\"ה ע' 143 הערה *16."]]],[2100490171,"כי אב המון גוים נתתיך להוסיף גרים מאוה\"ע, שקודם לכן בלתי אפשר הי' שיתגיירו מאוה\"ע מאחר שרם על כל גוים ה' והם לאחורי הפרגוד והפרסא הוא הערל\"ה המכסה על הברי\"ת עליון איך ישובו ויתכללו בקדושה שקודם הפרסא אך לאחר שנמול א\"ב ר\"ם ונק' אברה\"ם<sup data-n=\"590\">40</sup> בחי' אב\"ר מ\"ה שמתגלה מאבר המשפיע דצדיק עליון בחי' מ\"ה הוא תכלית הביטול דקדושה שלמעלה בלי שום מסך מבדיל, אזי נדיבי<sup data-n=\"591\">41</sup> עמי' נאספו עם אלקי אברה\"ם להתוסף גרים מאוה\"ע שיוכל אף הגוי להתגייר ולהכנס תחת כנפי השכינה ב\"ה מצד שאין שום מסך המבדיל ביניהם שכבר נכרתה הערלה בבחי' המיל\"ה ואח\"כ הפריע\"ה שמילה הוא לשון התגלות<sup data-n=\"592\">42</sup> שהוא כמו שנאמר והוא<sup data-n=\"593\">43</sup> יושב ממולי פי' לנגדי שדבר הנראה ומתגלה נק' בחי' ממולי כו' ולזאת בחי' הדבו\"ר נק' בחי' רוח<sup data-n=\"594\">44</sup> ממללא כתרגומו דנפש חי' כו' מצד שהדבור מגלה הנעלם לזולתו וז\"ס מיל\"ה<sup data-n=\"595\">45</sup> צירוף אותיו' מ\"ל י\"ה דהיינו שי\"ה הוא בחי' חו\"ב שלמעלה שהי' תחילה בבחי' העלם והסתר מצד הערל\"ה המכסה ומבדיל בין קדש לחול שז\"ס א\"ב ר\"ם כנ\"ל אבל עתה לאחר שנמו\"ל אבר\"ם נק' אבר מ\"ה אז מל י\"ה שנתגלה השפע עליונה דחו\"ב שהחכמה שמאין תימצא שהוא בחי' א\"ב המוליד חדשות מאין ליש כמאמ' ובטובו מחדש בכל יום מעשה בראשית דוקא נתגלה בבחי' גילוי בבחי' הדבור עליון בלי שום מסך מבדיל שזהו מ\"ל י\"ה שי\"ה נתגלו בבחי' הדבור עליון שנק' בחי' ממללא וכמו עד\"מ &lt;ס&gt;\nבנפש האדם שכאשר החכם מופלא טרוד בעומק ההשכלה נפלאה בינו לבין עצמו אזי נעלמה מעין כל חי משא\"כ כשמדבר החכמה ההיא בפיו לזולתו אזי נתגלה החכמה לזולתו אל השומעי' מפיו, כך ממש עד\"מ למעלה שכאשר נכרתה הערלה המכסה על הברי\"ת עליון הוא האבר המשפיע השפע עליונה אל הנפעלי' אזי מתגלה בחי' י\"ה בבחי' הדבור בבחי' גילוי ממש בלי שום מסך מבדיל והסתר כלל וז\"ס מיל\"ה מל י\"ה, וזהו ענין החשמ\"ל שראה יחזקאל הנביא ע\"ה כדאמרי' בגמ' מאי<sup data-n=\"596\">46</sup> חשמ\"ל תנא עתים חשות ועתים ממללות פי' שהחיות<sup data-n=\"597\">47</sup> רצוא ושוב כמראה הבזק שלפעמים הם חשות בבחי' ביטול האמיתי דחכמה עלאה שארז\"ל סיג<sup data-n=\"598\">48</sup> לחכמה שתיקה בחי' העלם והתכללות, ולפעמים ממללות בבחי' הדבור בבחי' גילוי ממש מצד שהם בבחי' רו\"ש בתמידיו' כנ\"ל, אך כ\"ז הוא עתה בזמן הגלות שימצא השינויי' אלו דרו\"ש מ\"ל שעתים חשות ועתי' ממללות וכן יחזקאל ראה בזמן הגלות בבל על נהר",[["590","40","<b>אברהם בחי' אבר מה</b>: ראה זהר בהקדמה ד, רע\"א."],["591","41","<b>נדיבי עמי' נאספו</b>: תהלים מז, י."],["592","42","<b>שמילה הוא לשון התגלות</b>: ראה תו\"א יב, ב. לקו\"ת במדבר יד, ד. פנחס עט, ג. דרך מצותיך יא, א."],["593","43","<b>והוא יושב ממולי</b>: בלק כב, ה."],["594","44","<b>רוח ממללא כתרגומו דנפש חי'</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["595","45","<b>מילה. . מ\"ל י\"ה</b>: ראה ע\"ח שער (לג) אונאה פ\"ג. טעמי המצות (להאריז\"ל פ' לך) סוד מצות מילה ופריעה. תו\"א יב, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' פג. וראה ג\"כ לקו\"ת ראה יט, א. וראה סה\"מ תרל\"ג ח\"ב ע' ת — בחי' מילה שפי' בת\"ז מל י\"ה."],["596","46","<b>מאי חשמל תנא עתים</b>: חגיגה יג, ב."],["597","47","<b>שהחיות רצוא ושוב כמראה הבזק</b>: יחזקאל א, יד."],["598","48","<b>סיג לחכמה שתיקה</b>: אבות פ\"ג י\"ג."]]],[2100490172,"כבר וכמ\"ש ואני<sup data-n=\"599\">49</sup> בתוך הגולה וגו' אבל לע\"ל דכתיב אז<sup data-n=\"600\">50</sup> אהפוך אל עמים שפה ברורה וגו' ויהי' נגלה כבוד ה' אשר עין בעין יראו ולא יכנף עוד מוריך כו' ואת<sup data-n=\"601\">51</sup> רוח הטומאה יעבור מן הארץ אז נאמר וראו<sup data-n=\"602\">52</sup> כל בשר יחדיו כי פי ה' דב\"ר דהיינו שיתגלה השפע דחו\"ב שלמעלה בבחי' הדבור עליון בבחי' גילוי ממש בלי שום מסך מבדיל שלא יכנף עוד מורי\"ך וז\"ס המילה מ\"ל י\"ה שעיקר הגילוי יהי' לע\"ל כנ\"ל.\n<b>והפריעה</b><sup data-n=\"603\">53</sup> היא בחי' התגלות יותר כי מל<sup data-n=\"604\">54</sup> ולא פרע כאלו לא מ\"ל והיינו כמ\"ש דאתפריעו כל נהורין כו' וד\"ל. וזה ענין התשובה לההוא מטרוניתא כהאי תורמסא דצריכא מיתוק כו' כך המילה שנברא<sup data-n=\"605\">55</sup> האדם בצל\"ם ודמות העליו\"ן בערל\"ה המכסה על הברית שזהו למעלה בחי' הפרס\"א המבדיל<sup data-n=\"606\">56</sup> בין קדש לחול שעיקר הכונה של התהוות החו\"ל שיתתקן ע\"י עבודת האדם דוקא לאהפכא<sup data-n=\"607\">57</sup> מחשוכא לנהורא וממרירו למיתקא שנ' ששת<sup data-n=\"608\">58</sup> ימים תעבוד ועשית כל מלאכתך כו' ר\"ל שזהו ענין חולי\"ן<sup data-n=\"609\">59</sup> שנעשו על טהרת הקדש שמי<sup data-n=\"610\">60</sup> שטרח בע\"ש יאכל בשבת וזהו כהאי תורמסא דצריכא מיתו\"ק לאהפכא ממרירו למיתקא ע\"י עבודת האדם דוקא וכמ\"ש אשר ברא<sup data-n=\"611\">61</sup> אלקי\"ם לעשו\"ת פי' לתקן כנ\"ל וד\"ל. ולזאת בהבדלה דמ\"ש לא נאמר רק המבדיל בין קדש לחול ולא נזכר ההבדלה בין הטמא לטהור שנאמר בגמ' במנין ז' הבדלות מפני שא\"צ בחי' ירידה גדולה כזו לעשות פרסא העב להבדיל בין טמא לטהור כו' כ\"א די בהבדלה זו שיהי' חולין שנעשו ע\"ט הקדש וכו' וד\"ל.\n<b>וזהו</b> הנסתרות להוי' אלקינו<sup data-n=\"612\">62</sup> והנגלות לנו ולבנינו פי' שקודם שנמול אברהם אע\"ה הי' נק' א\"ב ר\"ם ואז הנסתרות להוי' אלקינו הם חו\"ב עלאין שהם בבחי' הסתר והעלם מצד הערל\"ה המכסה על הברית עליון ולזאת &lt;סא&gt;\nאברם<sup data-n=\"613\">63</sup> אינו מוליד כו' והנגלות לנ\"ו ולבנינ\"ו זהו לאחר המילה שעיקר הגילוי הוא לבנינ\"ו בבחי' ההולדה וההשפעה לזולתו שמ\"ל י\"ה וזהו אברהם מוליד כו' כנ\"ל וד\"ל ולכך אף כשנוסף ה\"א באברהם לא נתבטל הרי\"ש כי הוא ר\"ם כמקודם רק שמתגלה בבחי' גילוי שהוא בחי' אב\"ר מ\"ה וד\"ל (וזהו ה\"ה דבה\"י ברא\"ם באברהם כו' כנודע).",[["599","49","<b>ואני בתוך הגולה</b>: יחזקאל א, א."],["600","50","<b>אז אהפוך אל עמים שפה ברורה</b>: צפני' יג, ט."],["601","51","<b>ואת רוח הטומאה אעביר מן הארץ</b>: זכרי' יג, ב."],["602","52","<b>וראו כל בשר יחדיו</b>: ישעי' מ, ה."],["603","53","<b>והפריעה. . התגלות. . דאתפריעו כל נהורין</b>: ראה זהר ויגש רי, א."],["604","54","<b>מל ולא פרע כאילו לא מל</b>: שבת קלז, ב (במשנה)."],["605","55","<b>שנברא האדם בצלם</b>: ראה בראשית א, כז. נח ט, ו."],["606","56","<b>המבדיל בין קודש לחול</b>: נוסח הבדלה."],["607","57","<b>לאהפכא מחשוכא</b>: ראה זהר בהקדמה ד, א."],["608","58","<b>ששת ימים תעבוד</b>: יתרו כ, ט."],["609","59","<b>חולין שנעשה על טהרת הקדש</b>: ראה לעיל הערה מס' 19."],["610","60","<b>שמי שטרח בע\"ש</b>: ע\"ז ג, א."],["611","61","<b>אשר ברא אלקים לעשות פי' לתקן</b>: בראשית ב, ג. וראה פרש\"י לב\"ר פי\"א, ז."],["612","62","<b>הנסתרות להוי' אלקינו</b>: נצבים כט, כח."],["613","63","<b>אברם אינו מוליד</b>: ב\"ר מד, יב. זח\"א צ, ב."]]],[2100490173,"<h3>להבין שרשן של הדברים הנ\"ל</h3>\n<b></b><b>בעזרה\"י, שבת קודש פ' תולדות (ביום השלישי למילה)</b>\nש\"ק פ' תולדות\n<b>להבין</b><sup data-n=\"614\">1</sup> שרשן של הדברים הנ\"ל באר היטב, הנה נז' בע\"ח<sup data-n=\"615\">2</sup> שלבוש החשמ\"ל הוא מחיצוניות אימא דאצי' המלביש זו\"ן דאצי' מצדדיהם שלא ינקו החצונים מהם ואח\"כ נעשה מנעל למטה תחת רגליהם והוא הפרסא והפרגוד המפסיק בין אצי' לבריאה דכדי שיתחדשו הנבראים מאין ליש מאור התולדה הנולדה מן הפרסא כו' וז\"ש מה<sup data-n=\"616\">3</sup> יפו פעמיך בנעלים כו' וז\"ש ויעש<sup data-n=\"617\">4</sup> כתנות עו\"ר וילבישם שהוא לבוש החשמ\"ל המלביש לזו\"ן דאצי' שנק' כתנות עו\"ר כנודע וכן בבי\"ע בכל סדרי ההשתלשלות ימצא הכל בחי' לבוש החשמ\"ל המלביש זו\"ן להגין מיניקת החצוני' מן הצדדין, ואח\"כ נעשה מנעו\"ל תחת רגליהם בכדי להיות פרסא המבדיל בינו לעולם התחתון כו' וכמו בזו\"ן דבריא\"ה שהחשמ\"ל מלבישם מהצדדי' ואח\"כ נעשה מנעול תחת רגליהם הוא בחי' מל' דבריאה שנעשה עתי\"ק ליצירה<sup data-n=\"618\">5</sup> שהיא עצמה הפרסא כנודע וכן מיצירה לעשי' כנודע לי\"ח.\n<b>והנה</b> ארז\"ל בגמ' י\"ג<sup data-n=\"619\">6</sup> פרוכת היו במקדש שני ז' כנגד ז' שערים ב' בדביר כו' ע\"ש ופירש\"י שם שהפרוכת הללו לצניעותא בעלמא עבידי שביום השערים נפתחים ולזאת עביד הפרוכת הללו לצניעותא בעלמא כו'.\n<b>והענין</b> כמ\"ש בזוהר<sup data-n=\"620\">6</sup> פ' לך לך שבהמ\"ק שלמטה הי' בדוגמא דלעילא מכוין ממש נגד מקדש שלמעלה עם כל שעריו ועזרות והר הבית כו' שנעשה הכל בדוגמא שלמעלה וכמ\"ש בד\"ה שאמר דוד המלך ע\"ה הכל בכתב מיד<sup data-n=\"621\">7</sup> ה' עלי השכיל שקיבל משמואל הרואה וכמו המשכן של משה נעשה בתבנית שלמעלה שהראה<sup data-n=\"622\">8</sup> לו ה' כזה תעשו כו' כך במקדש ראשון ושני הכל בכתב מיד ה' עליהם השכיל כנ\"ל והיינו כמו שלמטה בציור הבית שלמטה היו ז' שערים שבלילה הי' סוגרין וביום היו נפתחין ואז הבדילו הפרוכת דעבידא לצניעותא כו' כך ממש במל' דאצי' מקור דבי\"ע בחי' ירושלים שלמעלה שימצא בה בחי' מקדש דלעילא בציור",[["614","1","<b>להבין שרשן של הדברים</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (קצג, ב). הנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נדפס בסידור קמז, א. הנחה אחרת נדפס בתו\"א יב, ג.\nלכללות הענינים ראה ג\"כ דרך מצותיך ו, ב ואילך.\nנו\"א נמצא בכת\"י 866 כד, א (ומתחיל: הנה חיצוניות אימא)."],["615","2","<b>בע\"ח שלבוש החשמל הוא מחיצוניות אימא דאצי'</b>: ראה ע\"ח (שער כללות דרושי אבי\"ע) שמ\"ב פי\"ג. וראה אוה\"ת נח כרך ג ע' 1338. דרך מצותיך ז, א."],["616","3","<b>מה יפו פעמיך בנעלים</b>: שה\"ש ז, ב."],["617","4","<b>ויעש כתנות עור וילבישם</b>: בראשית ג, כא. ראה סידור שחרית ס, ד. שער בהמ\"ז קטו, ב. ביאוה\"ז בלק קמט, ד. סה\"מ תקס\"ה ח\"ב ע' תתיד."],["618","5","<b>מל' דבריאה שנעשה עתיק ליצירה</b>: ראה ע\"ח שער (ו) העקודים פ\"ב."],["619","6","<b>י\"ג פרוכת היו במקדש</b>: כתובות קו, א."],["620","6","<b>בזוהר פ' לך לך שבהמ\"ק שלמטה הי' בדוגמא דלעילא</b>: ראה דרך מצותיך שם: ונודע בזוהר פ' שלח שכל פרטי [זוהר קסא, ב]."],["621","7","<b>מיד ה' עלי השכיל</b>: דברי הימים-א כח, יט."],["622","8","<b>שהראה לו ה' כזה תעשו</b>: ראה תרומה כה, ט — ככל אשר אני מראה אותך. . וכן תעשו."]]],[2100490174,"ודוגמות הבית שלמטה עם מזבח החיצון והפנימי ועם כל השערים שבבית ודביר וההיכל &lt;סב&gt;\nוק\"ק כו' ועם הפרוכת המבדילות בין קודש לקודש הקדשים ובכל שערי העזרה והיינו ביום כשהשערים פתוחי' שהפרוכת המבדילות לצניעותא עבידי כדפרש\"י<sup data-n=\"623\">9</sup> שם אבל בלילה<sup data-n=\"624\">10</sup> השערים בעצמן סגורין ומסוגרין אין יוצא ואין בא וכמ\"כ למעלה ממש כי השערים שבמקדש מלך דלעילא הם הכלי' והצנורות שבהם תעבור השפע דמל' דאצי' לבי\"ע להחיות את כולם דכמו השער החצר הוא הפתח שבו עוברים מחצר לחוץ ומחוץ לחצר כך עד\"מ הצנורו' שלמעלה שהם הפתחי' עליונים שתעבור בהם השפע עליונה ממל' דאצי' לבי\"ע להחיותם ולקיימם נקראו בשם שערי\"ם שיש ז' שערים שונים זמ\"ז באופן ירידת השפע בהן במקדש דלעילא (שכאופן שינויי השערים הם הכלי' והצנורות של השפע עליונה זמ\"ז כך אופן שינוי התחלקות אורו' של השפע עליונה שמתחלק בכל שער שפע פרטי המיוחד לו כנודע ע\"פ נודע<sup data-n=\"625\">11</sup> בשערים בעלה כו' כל חד וחד לפום שיעורי' דילי' כמ\"ש במ\"א ע\"ש)\nוהנה נז'<sup data-n=\"626\">12</sup> בזוהר בלילא תרעין דגן עדן סתימין שהמה הז' שערים שבמקדש עליון שבמל' דאצי' שהמה סגורים ומסוגרים בלילה להעצר השפע עליונה של מל' דאצי' בבי\"ע הגם שנאמר ותקם<sup data-n=\"627\">13</sup> בעוד לילה ותתן טרף לביתה וכמ\"ש בע\"ח<sup data-n=\"628\">14</sup> שבלילה הוא זמן הברורין דבי\"ע שמבררת מל' דאצי' רפ\"ח ניצוצין דתוהו שנפלו בשבירה לבי\"ע שז\"ס ותתן טר\"ף לביתה שרפ\"ח<sup data-n=\"629\">15</sup> עם הכולל גי' טרף וזהו עצמות החיות והקיום של הנפעלים דבי\"ע כנודע, אין זה סתירה כלל כי או\"א דא\"ח ושניהם לאמת וצדק, כי בלילה תרעין דג\"ע סתימין דהיינו בבחי' החיות והאורות פנימיים שלמעלה שנעלמי' ומסותרי' בבחי' הסתר והעלם בבחי' הפנימיות שלמעלה להיותם נעצרי' מלירד ולהתפשט למטה בלילה מצד שאז השערים הם הכלי' והצינורות של השפע פנימי' סתימין וכמ\"ש בע\"ח שבלילה הוא זמן השינה שהוא בחי' הסתלקות המוחין בבחי' ההעלם בבחי' הפנימיות וכן המדות נעלמים בבחי' ההעלם וההסתלקות בבחי' הפנימיות כנראה באדם הישן שכל הדם הנפש שבתוך הגוף מתקבץ ומתאסף לתוך הלב שהוא ההעלם בבחי' הפנימיות המקור שממנה מקבלין כל שייפין דגופא כנודע ולכך כשמניח ידו על הלב בשעת השינה הוא צועק בקול עצום משנתו כו' כמ\"ש בע\"ח ע\"ש כך עד\"מ למעלה ממש שבלילה זמן השינה שהוא בחי' הסתלקות המוחין שהם החיות פנימיי שלמעלה בהעלם והסתלקות וכן המדות",[["623","9","<b>כדפרש\"י שם</b>: כתובות קו, א."],["624","10","<b>בלילה השערים בעצמן סגורים</b>: ראה תמיד פ\"ג."],["625","11","<b>נודע בשערים בעלה. . כל חד. . כמ\"ש במ\"א ע\"ש</b>: משלי לא, כג. וראה זהר וירא קג, ב. לקו\"ת מסעי פה, ב."],["626","12","<b>נז' בזוהר בלילא תרעין דגן עדן סתימין</b>: ראה זהר שלח שם."],["627","13","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["628","14","<b>וכמ\"ש בע\"ח שלילה הוא זמן הבירורין דבי\"ע</b>: ראה גם אמרי בינה שער הק\"ש פרק כא. פיה\"מ לאדה\"א עג, א."],["629","15","<b>שרפ\"ח עם הכולל גי' טרף</b>: בד\"ה והוא עומד עליהם תרס\"ג ע' נא בהערת כ\"ק אדמו\"ר זי\"ע מציין: למק\"מ לזח\"ג ס, א. וראה לקו\"ת אמור לו, ב. (וראה ג\"כ טעמי המצות להרח\"ו פ' משפטים) הוספות לתו\"א קי, א. וראה ג\"כ לקו\"ת אמור לו, ב."]]],[2100490175,"נעלמי' במקורן כאדם הישן שאין המדות והשכל פועלים אז פעולתן בהם בבחי' גילוי כנ\"ל וזהו תרעין דג\"ע סתימין פי' שמעצרי' השפע פנימי' שלמעלה הם המוחי' והמדות שלא יתגלו למטה כ\"א יהיו נעלמים בבחי' העלם והסתלקות בשרש הפנימיות שלמעלה כנ\"ל וד\"ל. אך בבחי' חיצוניות ההשפעה שלמעלה בלילה דוקא שזהו מ\"ש ותקם בעוד לילה ותתן טר\"ף לביתה וגו' שזהו בחי' ההשפעה חיצוניות של מדת מל' דאצי' שמשפעת חיצוניות השפע שלה מחיצוניות הכחו' שבה שביררה בהם רפ\"ח ניצוצין בבי\"ע לחיצוניות עולמות בי\"ע שזהו &lt;סג&gt;\nהזמן בלילה דוקא מצד שהפנימיות שבה מסתלקים בסוד שינה למקורם להתעלם ולהסתתר בשרש הפנימיות כו' שלמעלה שהן המוחין והמדות שמסתלקין בזמן השינה בשרש הפנימיות כנ\"ל אז דוקא עת וזמן להתפשטו' בחי' החיצוניות שבה בחיצוניות עולמות בי\"ע לברר בירורי נוג\"ה דבי\"ע רפ\"ח ניצוצין המובלעים בהן שז\"ס ותתן טרף לביתה כנ\"ל משא\"כ כשבחי' הפנימיות שלה מתגלי' בבחי' גילוי אזי אין בבחי' החצוני' שבה כח ויכולת להתפשט בבחי' גילוי בבי\"ע מצד עוצם ביטולן בבחי' הפנימיות בהתכללות אמיתי עד שבלתי אפשר להם להתפשט אז בבחי' התפשטות וגילוי ולזאת עיקר ההתפשטות של בחי' חצוניות הוא בלילה דוקא שהמה מבררי' אז בירורי נוג\"ה דבי\"ע כנ\"ל אבל הפנימיות מסתתרי' ונעלמי' אז בבחי' העלם והסתלקות מצד דהא בהא תלי' כנ\"ל, וה\"ז כמו עד\"מ בנפש האדם כשהוא ע\"ר אזי הכחות פנימיות שלו מתגלי' בו בבחי' גילוי והתפשטות והמה המוחין והמדות שמתפשטי' ומתגלי' במוח ולב ובכל רמ\"ח אברי הגוף בבחי' גילוי כשהוא ער ולהשכיל כל מושכל ולאהוב כל דבר הנחמד ומתאוה לו משא\"כ כשהוא ישן אזי מסתלקין הכחות פנימיות שלו בהעלם והסתר מאד דהיינו שהמוחין מסתלקים למעלה בשרש הפנימיות שהוא אז בלא דעת נמשל כבהמה נדמה וכן המדות נעלמי' בבחי' העלם בלב עד שאין פועלי' פעולתן בבחי' גילוי זולתי נעלמי' בלב בבחי' העלם ולזאת מתקבץ ומתאסף כל דם הנפש שבכל אברי הגוף לתוך הלב ולכך כשמניח ידו אז על הלב יזעק בקול עצום כו' כנ\"ל, אך מעלה יתירה נודעת לנו אז כשישן מבהקיץ דהיינו שאז זמן העיכול של המזון דוקא שאז מתעכל המזון במעיו במהרה יותר מבהקיץ כנודע לחכמי הרפואה והיינו מצד שהכחו' פנימיי' שלו הם המוחין והמדות נסתלקו אזי יוצא הכח והיכולת בהכחו' חצוניות שלו המה כח הזמן<sup data-n=\"630\">16</sup> וכח הצומח וכח הדוחה וכח העיכול שבנפשו שהמה כחו' קטני' חיצוניים שבנפשו להתפשט בגופו ולפעול פעולתן בגוף בהתפשטות יותר מכשהי' ער מצד שבעת התגלות הכחות פנימי' אין בהם כח כ\"כ להתפשט מצד ביטולן בהם כנ\"ל משא\"כ כשהכחו' פנימיי' נסתלקו אזי יש בהם כח גדול יותר להתפשט בבחי' התפשטות וגילוי לפעול פעולתן בגוף ולכך מתעכל המזון במהירות יותר בזמן השינה דוקא כנ\"ל וד\"ל.\n<b>כך</b> עד\"מ למעלה ממש שביום הוא התגברות החסד עליון כדכתיב חסד<sup data-n=\"631\">*16</sup> אל כל היום וגו' להשפיע השפע פנימיות שבמל' דאצי' לבי\"ע אזי הכחו' חיצוניו' שבה",[["630","16","<b>הזמן וכח הצומח</b>: כ\"ה בהכת\"י. וצ\"ב."],["631","*16","<b>חסד אל כל היום</b>: תהלים נב, ג."]]],[2100490176,"נעלמי' ונכללי' בבחי' העלם ונכללות בבחי' הפנימיות עד שאין בהן כח ויכולת אז להתפשט אז בבחי' גילוי והתפשטות משא\"כ בלילה שהוא זמן השינה שמסתלקי' הכחו' פנימי' בבחי' העלם מצד התגברות מדת הגבורה השולטת בלילה שטבע הגבורו' להעציר השפע הפנימיו' כנודע אז הזמן דוקא להתפשטו' וגילוי הכחו' חיצוניות שבמל' דאצי' והיינו שבחי' כ\"ח המברר שבה לברר ברורי נוגה דבי\"ע בחי' רפ\"ח ניצוצין שנפלו בנוגה דבי\"ע הוא בחי' כח החיצוני שבה (כמו כח העיכול שבנפש שהוא כח חיצוני &lt;סד&gt;\nכנ\"ל שאין מתגלה ומתפשט זולתי בלילה דוקא שז\"ס ותקם בעוד לילה ותתן טרף לביתה וגו' והא בהא תלי' מצד דתרעי' דג\"ע סתימין להעלים ולהעצור השפע פנימי' שלא יתגלה בלילה ולכך אז יהי' באפשר לכח המברר שבמל' דאצי' לברר ברורי' כנ\"ל משא\"כ ביום כשהשערים דג\"ע נפתחי' שהמה הכלי' והצינורו' להעברת השפע פנימי' שלמעלה שאז אין הזמן של הבירורין כנודע וד\"ל.\n<b>והנה</b> ביום כשמתגבר מדת החסד שלמעלה כדכתיב חסד אל כל היום להשפיע הכחו' פנימי' שבמל' דאצי' בפנימיו' עולמו' דבי\"ע דרך השערי\"ם דג\"ע שהמה ז' שערים שבמקדש מלך דלעילא, אזי השערים נפתחים, להיות עובר השפע פנימיו' דרך השערים שהמה הצינורות שלה לבי\"ע וכמ\"כ למטה הי' בדוגמא דלעילא. שבלילה היו השערים שבמקדש דלמטה סגורי' ומסוגרי' וביום היו נפתחים אך לצניעותא עבדו הפרוכת ביום להבדיל בין קודש לקודש הקדשים כו' שלא יהיו השערים פתוחין להדי' בלי שום דבר חוצץ כו' וכמ\"כ ממש הוא למעלה שאף ביום כשהשערים דג\"ע פתוחי' לצורך העברת השפע פנימיו' שלמעלה אזי יבדילו הפרוכת המה הפרסו\"ת שלמעלה שבין כל עולם ועולם מעולם ועד עולם כמו מאצי' לבריאה ימצא פרסא המבדיל בינו לבריאה שהוא המנעול של עור שתחת רגליהם דזו\"ן דאצי' שנמשכה ונסתעפה מלבוש החשמ\"ל וכן מבריאה ליצירה ומיצירה לעשי'. ותחלה נבאר היטב ענין לבוש החשמ\"ל המלביש דו\"ן<sup data-n=\"632\">17</sup> מן הצדדין שלא ינקו מהם החצונים ששרשו מחצוניו' אימא ונעשה לבוש כתנות עו\"ר וילבישם לזו\"ן כו'.\n<b>והענין</b> הוא דהנה באמת אור אין סוף ב\"ה פשוט בתכלית הפשיטות המרומם לבדו א\"א לו לשרות בשום כלי הי\"ש ודב\"ר מ\"ה זולתי בכלי הביטול דוקא שהיא כלי החכמה כ\"ח מ\"ה דאצי' שמצד שהיא כלי הביטול בבחי' מ\"ה לכך ישרה בה דוקא אור אין סוף ב\"ה משא\"כ בכלי הי\"ש שא\"א לו לשרות בשום אופן כדרז\"ל אין<sup data-n=\"633\">18</sup> אני והוא יכולי' לדור בעולם א' כו'. ולזאת כשמצטרך אור אין סוף ב\"ה לשרות בתוך המדות עליונות דאצי' שנחשבי' ליש ודבר מה נגדו אא\"ל זולתי ע\"י אמצעות החכמה דאצי' שמתלבש בה והיא תתלבש בתוך המדות כו', אך בידוע שא\"א להיות מתלבש בתוך המדות בחי' מהו\"ת ועצמו' החכמה זולתי הארה חיצוניות שלה בלבד כי כאשר תתלבש בהן בחי' מהות עצמו' החכמה אזי יתבטלו המדות במציאותן ויתכללו בתכלית הביטול וההתכללות עד שבלתי אפשר יהי' להן להתפשט אז בבחי' גילוי והתפשטות לפעול פעולתן זולתי יתכללו בהעלם והתכללות בתכלית הביטול",[["632","17","<b>דו\"ן</b>: דכר ונוקבא."],["633","18","<b>אין אני והוא יכולי' לדור</b>: ראה סוטה ה, א."]]],[2100490177,"בבחי' החכמה עד שלא יעלו בשם דבר בפ\"ע כלל, לכך תתלבש בהן הארה חיצוניות רשימו בעלמא מבחי' החכמ\"ה כ\"ח מ\"ה בכדי שימצא בהן בחי' הביטול דחכמ\"ה שמלובש בה אור א\"ס והוא לבוש החשמ\"ל שנעשה לבוש אל המדו' ונמשך מחצוניות דחו\"ב כנ\"ל &lt;סה&gt;\nומבשרי אחזה דכאשר ישכיל המשכיל בגדולת אין סוף ב\"ה בהרחבת ההתבוננות אזי יוליד מזה בחי' המדו' אהוי\"ר לה' ית' אך בעודו טרוד בהרחבת ההתבוננות אזי המדו' נעלמי' ונכללי' בהשכל בהתכללו' וביטול עד שלא יורגשו בלב בהרגשה ויש ודבר בפ\"ע זולתי לאחר הסתלקות הרחבות ההתבוננו' שנתקצר ההשכלה אז יולידו המדו' דאהוי\"ר בהרגשה ממש בלב בבחי' התפעלות ממש רק רשימו מההתבוננו' נשאר בהם כך עד\"מ למעלה שהתלבשו' אור אין סוף בחכמה ומחכמה נשפע להמדו' הארת אור א\"ס ע\"י אמצעו' החכמה שנשאר רשימו בעלמא ממנה בתוכם וזהו לבוש החשמ\"ל ששרשו מחיצוניות בינה ומלביש בחי' זו\"ן דאצי' שנעשה כתנו' עו\"ר וילבישם. והיינו שימצא בלבוש החשמ\"ל ב' בחי' ומדרגות שונות הא' הוא מצד שרשו שנמשך מחיצוניו' אימא דאצי' שהיא למעלה מן המדות דאצי', והשנית מצד היותו מלבוש להמדו' שנשפל במורד למטה בהגשמה מן המדות להיותו מלבישם בבחי' לבוש עו\"ר שהוא בחי' צרופי אותיו' של המדו' שהמה הלבושי' שלהם המסתירי' ומכסי' על עצמו' המדו' מצד ההגשמה שלהן אך שרשו הגבוה למעלה מהם כנ\"ל, ולכן יש בכח לבוש החשמ\"ל המלביש זו\"ן להגין עליהם להיות להם למחסה ולמסתור מיניקות החצוני' מצדדיהם מצד ב' אופני' שונות שבו שמצד שרשו שנמשך מחיצונית בינה שימצא בו הארת החכמ\"ה כ\"ח מ\"ה אין בהחיצוני' כח ויכולת לשלוט ולאחוז כלל שעיקר יניקתם הוא מבחי' הי\"ש דוקא ולכך יכולי' לינק מהמדו' חו\"ג מצד שהם בחי' יש ודבר מה שאברהם<sup data-n=\"634\">19</sup> שהוא חסד דאצי' שיצא ממנו ישמעאל בחי' חסד דקליפה שיונק מהצפרניי' דיד ימין עליון הוא הפסולת דחסד עליון כנודע וכן יצחק שהוא מדת הגבורה דאצי' יצא מצפרניו דיד שמאל עליון בחי' עשו שהוא סוספיתא<sup data-n=\"635\">20</sup> דדהבא כמ\"ש בזוהר, ולזאת מגין עליהם לבוש החשמ\"ל מצד שרשו מחיצוניו' אימא שימצא בו רשימת החכמה כ\"ח מ\"ה שזה דוחה ומסמא החצוני' שלא יוכלו לינק כנ\"ל אך כשלא יתגשם בבחי' הגשמה למטה להיות מלביש המדו' אזי לא יוסתרו המדו' ויוכלו החצוני' לינק מהם לכך נתגשם למטה להיותו למחסה ולמסתור אל המדו' מן החצוני' שלא יוכלו לינק מהם מצד הסתרת הלבוש החשמ\"ל וממנו יריאי' לגשת מצד שרשו הנעלה כנ\"ל (וכמ\"ש<sup data-n=\"636\">21</sup> במ\"א בארוכה ע\"פ זוהר בוקר אערך לך ואצפה דדוד אתקין חופאה להאי בוקר דיוסף ע\"ש).\n<b>ובאור</b> הענין דהנה כמו למטה בנפש המשכלת שהחכם המופלא כשמצטרך להשפיל איזה מושכל נפלא ועמוק עמוק מאד לתלמידו הקטן אזי מלביש",[["634","19","<b>שאברהם שהוא חסד דאצילות שיצא ממנו ישמעאל</b>: ראה פסחים נו, א. וראה זהר בראשית מז, ב. מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תקפ ובהנסמן לשם. סה\"מ תר\"מ ח\"ב ע' תסא."],["635","20","<b>סוספיתא דדהבא כמ\"ש בזוהר</b>: ראה זהר פקודי רכד, ב. סה\"מ תקס\"ב ח\"א ע' לג."],["636","21","<b>כמ\"ש במ\"א בארוכה ע\"פ זוהר בוקר אערך לך ואצפה</b>: ראה סה\"מ תקס\"ב ע' תקז ואילך."]]],[2100490178,"המושכ\"ל ההוא במשל וחידה שמתוך המשל יבין התלמיד הנמשל, והנה אעפ\"י שהמשל אינו דומה לנמשל כלל שהוא מגושם מאד דמשתעי במילין דהדיוטא ממילין דעלמא ואין לו ערך ויחס אל המושכל כמו שהוא מופשט מהמשל כמו במוח הרב, אעפ\"כ שרש המשל נמשך ממקור נעלה &lt;סו&gt;\nשבשכל הרב מן המושכל ההוא שהמושכל נמשך ממקור נמוך שבשכל הרב מאחר שהוא יתלבש בהמשל והמשל ילבישנו ויסתירנו והיינו שההמצאה זו של הרב להמציא המשל ההוא שילביש בו המושכל ההוא הוא מעצמו' גדלות כח המשכיל של הרב שלמעלה מהשכל ההוא שחידש שיש בכח המשכיל שלו לחדש חדושי' רבים כהנה וכהנה משם נמשך המצאה זו למצוא איזה משל להלביש השכל, והראי' לזה שדוקא החכם מופלא יוכל למצוא משלי' וחידו' לההשכלו' שלו מצד מוחי' דגדלות שלו שנמשך מעצמו' כח המשכיל שלו המצאה זו של המשל להיות נרתיק להשכל וחידוש פרטי ההוא, כמו משלי שלמה בן דוד מלך ישראל בן<sup data-n=\"637\">22</sup> חכם ישמח אב וגו' או כמו משלי' דר\"מ שאמר תלתא<sup data-n=\"638\">23</sup> שמעתתא ותלתא מתלי' כו' ומשמת<sup data-n=\"639\">24</sup> ר\"מ בטלו מושלי משלים כדאמרי' בגמ' מפני שלאו כל מוחא סביל דא להיות ממשל משלי' לההשכלו' שלו כו' שאינו יכול לומר אלא כמו שהשכל הוא במוחו בלבד אבל להמציא משל לו אין בכח חכמתו זאת ואם הי' ממציא משל לו הי' שטות לגמרי כו', ולזאת ימצא בבחי' המשל<sup data-n=\"640\">25</sup> ב' בחי' שונות הא' מצד שרשו הוא ממקור נעלה מן השכל המלובש בו כנ\"ל והשנית כמו שנשפל למטה הוא למטה בהגשמה מן השכל ועד שהוא מלביש ומסתיר השכל המלובש בו כנ\"ל. וכמ\"כ עד\"מ למעלה בחי' לבוש החשמ\"ל ששרשו מחצוני' אימא שלמעלה מהמדו' דאצי' ונשפל במורד למטה מהם להיותו מלבוש לזו\"ן מצדדיהם להיות להם למחסה ולמסתור ולהגין מיניקות החצוני' כנ\"ל וד\"ל.\n<b>אך</b> למטה תחת רגליהם דזו\"ן נעשה מלבוש החשמ\"ל בחי' מנעו\"ל להיות בחי' פרסא ומסך להבדיל בין אצי' לבריאה שאין הכונה בזה מצד ירא' יניקת החצוני' זולתי בכדי שיתחדשו הנפעלי' דבי\"ע מאצי' שמתחדשי' מאין לי\"ש ממש מחודש ע\"י הסתרת הפרסא שאז נעשה האור המגיע אליהם בחי' אור התולדה כמ\"ש בע\"ח בסוף הספר ע\"ש.\n<b>והענין</b> הוא דהנה נאמר ובטובו<sup data-n=\"641\">26</sup> מחדש בכל יום מע\"ב שהוא בחי' התחדשו' הנבראי' המחודשי' מאין ליש ממש ולכאורה<sup data-n=\"642\">27</sup> פלא הלא ממך<sup data-n=\"643\">28</sup> הכל וכלא<sup data-n=\"644\">29</sup> קמי' כלא חשיבי לזאת למעלה הי\"ש האמתי ולמטה האי\"ן האמתי דכלא כלא חשיבי קמי' וכאין ואפס נחשבו, אך באמת אם הי' יורד השפע כמות שהיא למעלה",[["637","22","<b>בן חכם ישמח אב</b>: משלי י, א."],["638","23","<b>תלתא שמעתתא</b>: סנהדרין לח, ב."],["639","24","<b>ומשמת ר\"מ בטלו מושלי משלים</b>: ראה סוטה מט, א."],["640","25","<b>המשל. . שרשו הוא ממקור נעלה מן השכל</b>: ראה סה\"מ תקס\"ח ח\"א ע' שצג. וראה מאמרי אדה\"א ויקרא ע' כב ובהנסמן שם."],["641","26","<b>ובטובו מחדש בכל יום מע\"ב</b>: ברכת יוצר."],["642","27","<b>ולכאו' פלא</b>: ראה ג\"כ לקו\"ת פ' ראה כו, ד. שם יט, ג ובאגה\"ק סי' כ."],["643","28","<b>ממך הכל</b>: דברי הימים-א כט, יד."],["644","29","<b>וכלא קמי' כלא חשיבי</b>: ראה זח\"א יא, ב."]]],[2100490179,"באצי' למטה לבריאה אז הי' באמת כך אך מאחר שיש פרסא המבדיל בין<sup data-n=\"645\">30</sup> שהשפע עוברת דרך הפרסא אזי נשתנה לגריעותא למהות יש מחודש ממש מאין שקודם הפרסא שהי' מעולם באופן הזה מקדם העברתו דרך הפרסא שעיקר החדוש של היש נעשה לאחר הפרסא דוקא מצד שנתמעט האור ונתעלם בהגשמה מחודשת ממש שהוא בחי' אור התולדה המחודש ממש. וזה ענין ההתחדשו' מאין לי\"ש מחודש ממש כנ\"ל והיינו כמ\"ש בע\"ח שמל'<sup data-n=\"646\">31</sup> דאצי' נעשה עתיק לבריאה שבה עצמה הוא בחי' הפרסא המבדלת בין אצי' לבריאה דהיינו בחי' השתנות הצירופי אותיו' שבמל' דאצי' שהשפע העוברת מאצי' להיות עתיק לבריאה נשתנה ממהו' אין למהו' י\"ש &lt;סז&gt;\nמחודש ע\"י ההשתנו' שלה דרך הפרסא כנ\"ל (וכמו הבנת השכל של התלמיד המושכל של הרב מתוך המשל כנ\"ל), וזהו המנעו\"ל של עור שתחת רגליהם דזו\"ן דאצי' שנסתעף מלבוש החשמ\"ל להיות פרסא להבדיל בין אצי' לבריאה כנ\"ל וד\"ל.\n<b>וזהו</b> ענין לבוש החשמל דאצי' שיש בו ב' בחינות ומדריגות שונות כמו שהוא בשרשו שנמשך מחיצוניו' אימא דאצי' שלמעלה מזו\"ן דאצי' שנמצא בו הארת הביטול דחכמה<sup data-n=\"647\">32</sup> כ\"ח מ\"ה דאצי' ומצד זה נק' ח\"ש, כי סיג<sup data-n=\"648\">33</sup> לחכמה שתיקה שהוא תכלית הביטול האמתי דחכמ\"ה עילאה דאצי' וכן מרע\"ה<sup data-n=\"649\">34</sup> ששרשו הי' בחי' מה דאצי' שאמר ונחנו<sup data-n=\"650\">35</sup> מ\"ה ולזאת הי' כבד<sup data-n=\"651\">36</sup> פ\"ה וכבד לשון כבד פ\"ה<sup data-n=\"652\">37</sup> הוא תשבע\"פ וכבד לשון הוא תשב\"כ שלא הי' יכול להשפל בפ\"ה ולשון עליון מצד שרשו הנעלה שנמשך מח\"ע שסיג לחכמה שתיקה שהוא בחי' עלי' החכמה במקורה עצמו' החכמה הנעלמה בכתר שאז הוא בחי' שתיקה כנ\"ל ומ\"ל נק' מצד שנשפל למטה להיותו בחי' לבוש המלביש זו\"ן דאצי' מן הצדדי' ולמטה תחת רגליהם דזו\"ן נעשה בחי' מנעו\"ל של עו\"ר שהוא הפרסא שבמל' דאצי' שנעשה עתיק לבריאה שזהו מ\"ל שהוא בחי' הדבור עליון דמל' דאצי' שנעשה עתיק לבריאה שנקר' בחי' עלמא דאתגליי' שהוא כענין שנאמ' והוא יושב ממול\"י (וכמשנת\"ל בתורה) ולזאת מאחר שב' בחי' ומדריגות שונות אלו נמצאי' בלבוש החשמ\"ל לכך נק' בשם ח\"ש מ\"ל וכנ\"ל וד\"ל.\n<b>והנה</b> כמו שיש פרסא המבדלת בין אצי' לבריאה שהוא המנע\"ל של עו\"ר שתחת רגליהם דזו\"ן דאצי' שנסתעף מלבוש החשמ\"ל דאצי' שהוא כולו אלקות ממש כנודע. כך יש פרסא בין בריאה ליצירה דהיינו שמל' דבריאה נעשה עתיק ליצירה כו' ויש שם ג\"כ לבוש חשמ\"ל שממנו יסתעף הפרסא כנ\"ל והיינו כמארז\"ל במס' חגיגה מאי<sup data-n=\"653\">38</sup> חשמל תנא עתים חשות ועתי\"ם ממללות בשעה שהדיבור יוצא",[["645","30","<b>בין</b>: כ\"ה בהכת\"י. וניכר שחסר כמה תיבות."],["646","31","<b>שמל' דאצי' נעשה עתיק לבריאה</b>: נסמן לעיל הערה 2."],["647","32","<b>דחכמה כח מה</b>: זח\"ג לד, א."],["648","33","<b>סיג לחכמה שתיקה</b>: אבות פ\"ג מי\"ג."],["649","34","<b>מרע\"ה ששרשו הי' בחי' מה דאצי'</b>: ראה לקו\"ש ח\"ו ע' 244 ואילך."],["650","35","<b>ונחנו מה</b>: בשלח טז, ז-ח."],["651","36","<b>כבד פה וכבד לשון</b>: שמות ד, י."],["652","37","<b>פה הוא תשבע\"פ וכבד לשון הוא תשב\"כ</b>: זח\"ג כח, א. וראה לקו\"ת במדבר יז, ד. עקב יד, ד."],["653","38","<b>מאי חשמל תנא עתים</b>: חגיגה יג, ב."]]],[2100490180,"מפי הקב\"ה ממללו\"ת כו' יע\"ש, פי' הקדו\"ש ברוך הוא שנז' בכל דרז\"ל בגמ' באגדה הכונה על בחי' זו\"ן שלמעלה שהקב\"ה הוא בחי' המדות דאצי' המיוחדת במאצילן ב\"ה כדכתיב לך<sup data-n=\"654\">39</sup> ה' הגדולה והגבורה כו' וכנודע שז\"א כולל כל הע\"ס דאצי' שזהו נק' בלשון חמז\"ל קדו\"ש<sup data-n=\"655\">40</sup> לשון הבדלה והפרשה שמה שנק' חכים<sup data-n=\"656\">41</sup> ולא בחכמה ידיעא או חסדן רחמן אין זה שייכות אל הנפעלי' דבי\"ע כלל שהמה שמו' העצמיי' שלו ית' משא\"כ מדת מלכות\"ו ית' שהוא ש' הפעולה לזולתו כי אין<sup data-n=\"657\">42</sup> מלך בלא עם דוקא שכאשר ימצא הנפעלי' דבי\"ע אזי מלך שמו נקרא עליהם דוקא כנודע. וזהו ברו\"ך הו\"א שהוא בחי' מדת מל' ית' השכינה ב\"ה ולזאת נכללי' קב\"ה ושכינתי' כאחד במלת הקדו\"ש ברו\"ך הוא וד\"ל.\n<b>וזהו</b> כוונתם ז\"ל בשעה<sup data-n=\"658\">43</sup> שהדבור יוצא מפי הקב\"ה דהיינו בחי' השפעות הדבור עליון דמל' דבריאה להיות עתיק ליצירה שבוקע' המסך &lt;סח&gt;\nוהפרגוד המפסיק בין בריאה ליצירה להיות יוצא מפי הקב\"ה הם המדו' ומל' דבריאה להבקיע המסך ולהאיר ביצירה אזי המלאכים ורוחין דיצירה חשות שמתבטלים במציאותן לגמרי בבחי' שתיק\"ה מצד שנבקע המסך דיצירה המבדיל בינו לבריאה ונתגלה עליהם שורשו של לבוש החשמל שנמשך מחיצוני' דחו\"ב דאצי' לכך הם חשו\"ת בבחי' הביטול דחכמה כ\"ח מ\"ה דסי\"ג לחכמה שתיק\"ה תכלית הביטול האמתי עד שאין בכחן להרים ראש אף לומר שירה קדוש וברוך כ\"א מתבטלים לגמרי במציאותן כנ\"ל ובשעה שאין הדבור יוצא מפי הקב\"ה מצד הבדלת המסך דיצירה המבדיל בינו לבריאה שהוא המנעול שתחת רגליהם דזו\"ן דבריאה שנסתעף מלבוש החשמ\"ל אזי ממללות כאופן בחי' השפלת לבוש החשמ\"ל למטה להיות נסתעף הפרסא ממנו להבדיל בין בריאה ליצירה שהוא בחי' הדבור עליון דבריאה כי מל' דבריאה נעשה עתי\"ק ליצירה ולכך אז ממללות לומר שירה ותישבחו' קדוש וברוך כו' וכמ\"ש וצבא<sup data-n=\"659\">44</sup> השמים לך משתחוים שהביטול שלהם הוא בבחי' יש שהיש נפרד מבטל א\"ע ומשתחוה כנודע וזהו ענין חשמל דיצירה וד\"ל.\n<b>והנה</b> כ\"ז הוא בחי' הפרוכת המבדילות בין קודש לקדש הקדשים שהיה הפרסות דאב\"י כנ\"ל שכולם הם בקדושה ממש רק הם מבדילים בין קדושה יתירה הוא עולם העליון ובין התחתון ממנו כנ\"ל. אבל עולם העשי' שהוא עולם השפל שאין למטה הימנו במדרגה כלל שהוא תכלית המדרי' דקדושה דסדרי ההשתלשלות כולן לכך הפרסא שבו היא להבדיל בין הקדש ובין החו\"ל דהיינו בין ע\"ס דקדושה דעשי' ובין ע\"ס שבנוג\"ה דעשי' (שהסתעפו' קליפת נוג\"ה הוא מעשי') כנודע שלזאת",[["654","39","<b>לך ה' הגדולה והגבורה</b>: דברי הימים-א כט, יא."],["655","40","<b>קדוש לשון הבדלה</b>: ראה פרש\"י ר\"פ קדושים. אגה\"ת פ\"י. וראה תניא פמ\"ו."],["656","41","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה (פתח אלי')."],["657","42","<b>אין מלך בלא עם</b>: ס' החיים פ' גאולה פ\"ה. בחיי וישב לח, ל. עמה\"מ שער שעשועי המלך רפ\"א."],["658","43","<b>בשעה שהדיבור יוצא מפי הקב\"ה</b>: ראה חגיגה יג, ב."],["659","44","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."]]],[2100490181,"הוצרך להיות פרוכ\"ת שהיא פרסא המבדיל בין הקדש ובין החו\"ל שעי\"ז נעשה בחי' חול הוא בחי' קליפות נוג\"ה שזה עיקר כונת הכתוב דכתיב ויעש<sup data-n=\"660\">45</sup> כתנות עו\"ר וילבישם שהוא הפרסא דעשי' המבדיל בין הקדש ובין החו\"ל שהוא לבוש החשמ\"ל דעשי' שנק' כתנות עו\"ר לבוש עב גשמי שמכונה מצד זה בשם עור דוקא שמאחורי הפרגוד ומסך של עור שהוא בחי' נוג\"ה דעשי' וכן מנוג\"ה דעשי' נסתעפי' ג' קליפו' הטמאו' לגמרי דע' שרים דקליפה ג\"כ ע\"י פרסא אחרת גשמיית יותר המבדלת בין נוג\"ה לג' קליפות הטמאו' לגמרי מפני שנוג\"ה מעורב טו\"ר ופעמי' מתעלה ונכלל בקדושה לגמרי משא\"כ ג' קליפו' הטמאו' לגמרי כנודע שכל תאוות היתר של עה\"ז ממאכלות המותרות ודומיהן הוא מבחי' נוג\"ה דעשי' שלגבי קדושה הם תאוות זרות המגשמי' אותו אך לפעמים כשיתפלל אח\"כ בכונה מכח האכילה ההיא אזי יתעלה כולו בקדושה כמ\"ש<sup data-n=\"661\">46</sup> בלק\"א. משא\"כ מאכלות האסורות שהם מג' קליפו' הטמאו' כו'.\n<b>והנה</b> ממך<sup data-n=\"662\">47</sup> הכל שאין לך דבר חוץ שחוץ ממנו ית' שהכח המתאוה הזה נמשך אליו מלמעלה מכח המחי' ית' אך עפ\"י רבוי ההשתלשלות ומסכי' הרבים ההם שעובר השפע דקדושה דרך הפרסא דעשי' המבדיל בין קדש לחול שאז נתגשמה ונשתנה למהו' אחר גשמיי להיות בחי' כח המתאוה &lt;סט&gt;\nלדבר היתר גשמיי דנוג\"ה דעשי' וכן כשעוברת השפע למטה יותר אחורי הפרגוד שבין נוג\"ה לג' קליפות הטמאו\"ת לגמרי אזי נתגשמו יותר להיות נסתעף ממנה בחי' ר\"ע גמור כו'.\n<b>ולזאת</b> על ברצון המאציל ית' להיות פרוכת הללו מבדלת בין קדש לק\"ק ובין הקדש לחו\"ל עד שיהי' באפשר להתהוות בחי' היכלות הקליפה נוג\"ה ומהם יסתעף אחורי הפרגוד המפסיק ומבדיל בין נוגה לשלוש קליפו' הטמאות בחי' ע' שרים דקליפה ממש, שכל כונתו ית' הי' בזה בכדי שיוכל להסתתר אורו ית' ויתראה העה\"ז לי\"ש ודבר בפ\"ע והאדם עובד אדמתו לשבע לחם בכל ל\"ט מלאכות הנוהגות ומותרות בחו\"ל ואסורו' בשבת, והמה זריעה וחרישה וקצירה כו' שנראה כאלו מקבל חיותו מדברים אחרים נפרדים דעה\"ז בעסקו בפרנסה ומרויח ומפרנס א\"ע הגם שממך הכל מוסתר האור והשפע עליונה בלבושי נוג\"ה דעשי' המה כל העבודת ומלאכות שבחול שע\"י מרויח וממציא פרנסתו כו' וכדכתיב ששת<sup data-n=\"663\">48</sup> ימים תעבוד ועשית כל מלאכתך שעיקר הכונה בזה בכדי שיברר רפ\"ח ניצוצין דתוה\"ו שנפלו לנוג\"ה דבי\"ע וכן מנוג\"ה דבי\"ע בכל ששת ימי המעשה דחול לאהפכא<sup data-n=\"664\">49</sup> מחשוכא לנהורא וממרירו למיתקא שיתכללו אח\"כ בקדושה ממש וזהו ענין השב\"ת להוי' אלקי\"ך לא תעשה כל מלאכה מצד שבשבת נתגלה השפע עליונה דאצי' בבריאה בלי לבוש ומסך כלל הגם שיש מסך בין אצי' לבריאה הוא בקדושה ממש",[["660","45","<b>ויעש כתנות עור וילבישם</b>: בראשית ג, כא."],["661","46","<b>כמ\"ש בלק\"א</b>: ראה אגה\"ק פכ\"ו."],["662","47","<b>ממך הכל</b>: ל' הפסוק — דברי הימים-א כט, יד."],["663","48","<b>ששת ימים תעבוד</b>: יתרו כ, ט."],["664","49","<b>לאהפכא מחשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."]]],[2100490182,"להבדיל בין הקדש לק\"ק אבל אין יורד השפע להתלבש במסך דעשי' המבדיל בין קודש לחול (וכנודע שזהו החילוק<sup data-n=\"665\">50</sup> בין א\"י לחוץ לארץ שבא\"י מתגלה השפע דאצי' בבריאה פי' ע\"י ההתלבשות בכס\"א דבריאה כמ\"ש ביום השביעי נתעלה וישב על כסא כבודו וי\"ע נכללים בו שהשפע עוברים בהן דרך מעביר בעלמא משא\"כ בחו\"ל שמתלבשת ביצירה אך לא בעשי' שזהו הכל בקדושה ממש אבל הפרסא שבין עשי' לנוג\"ה אתפריעת כו') ולכך אסורים בכל מלאכה מל\"ט מלאכות דחול מפני שאין צריך האדם לקבל חיות מדבר אחר זר ונפרד זולתי ישב במנוחה והשקט ויתגלה עליו השפע עליונה דאצי' שאף המאכל' דשבת מוכרחים להיות מוכנים מע\"ש.\n<b>וזהו</b> ענין התגלות השפע דאצי' בבריאה שהאדם הוא היש הנפרד הנברא ומחודש שמקבל חיות מאלקות שיושב במנוחה וינפש מכל מלאכה שלא יקבל חיות משום דבר נברא זולתי מעצמו' אלקות דאצי' והוא בתכלית הביטול כאלו עומד לפני המלך שלא יוכל להרים ידו בשום דבר בעולם זולתי בתורה כנ\"ל מצד שנקרע המסך דנוג\"ה דעשי' המבדיל בין קד\"ש לחול שלא יוסתר אורו ית' כנ\"ל אך כ\"ז נעשה ע\"י עבודת האדם בו' יומין דחול במלאכת הברורין לאהפכא מחשוכא לנהורא לברר בירורי נוג\"ה דעשי' שאחורי הפרגוד המבדיל בין קדש לחול שזהו כונת מארז\"ל מי<sup data-n=\"666\">51</sup> שטרח בע\"ש יאכל בשבת פי' שטרח בע\"ש בכל ששת ימי המעשה במלאכת הברורי נוג\"ה לאהפכא מחשוכא לנהורא וממרירו למיתקא הוא יאכ\"ל בשבת אח\"כ מירידת השפע עליונה דאצי' המתגלה בבריאה שלא ע\"י הסתרת המסך דעשי' המבדיל בין קדש לחו\"ל כנ\"ל. ולזאת מבדילין על הכוס במוצאי שבת ברוך אתה הוי' כו' המבדיל בין קד\"ש לחול שמצטרכים להמשיך הבדלת הפרסא דעשי' מחדש להבדיל בין קודש הם ע\"ס דקדושה דעשי' ובין החו\"ל הם ע\"ס דנוג\"ה דעשי' שהמבדי\"ל הוא נמשך מבחי' לבוש החשמ\"ל דעשי' שלמעלה משניהם ששרשו מחיצוני' אימא כנ\"ל ולכך או' ברוך הוא המשכה ממקורו בחי' חיצוני' אימא להיות מבדי\"ל בין קדש לחו\"ל כנ\"ל וד\"ל.\n<b>וזהו</b> ענין הערלה החופה על הברית קדישא שהוא בחי' כתנות עו\"ר לבוש החשמ\"ל דעשי' המבדיל בין הקדש ובין החו\"ל כנ\"ל שזהו התשובה לההיא מטרוניתא כהאי תורמסא דצריכת מיתוק כו' פי' כי הערלה המכסה על הברית הוא בחי' הפרסא המבדיל בין קדש ע\"ס דקדושה דעשי' לנוגה דעשי' שלכך נברא האדם בצלם ודמות העליון בערל\"ה בכדי שיוכל להתהוות עולם העשיה בהסתרת אלקות שיתראה בבחי' י\"ש ודבר בפ\"ע. אך אין זה השלימות עד שיתק\"ן מלאכת הברורי' דנוג\"ה לאהפכא מחשוכא לנהורא וממרירו למיתקא וזהו המשל של המילה לתורמסא דצריכא מיתו\"ק שהוא בחי' ההתהפכו' ממריר\"ו למיתקא כך ע\"י המיל\"ה שמעביר הערל\"ה הוא הפרס\"א המבדיל בין הקדש ובין החו\"ל מברר בירורי נוג\"ה לאהפכא מחשוכא לנהורא וממרירו למיתקא שיוכלל בקדושה ואלקות ממש כנ\"ל.",[["665","50","<b>וכנודע שזהו החילוק בין א\"י לחוץ לארץ</b>: ראה ג\"כ לקו\"ת מסעי פט, ב."],["666","51","<b>מי שטרח בע\"ש יאכל בשבת</b>: ע\"ז ג, א."]]],[2100490183,"<b>והיינו</b> כמארז\"ל מי שטרח בע\"ש &lt;ע&gt;\nיאכל בשבת שבחו\"ל הוא זמן הברורי' לאהפכא מחשוכא לנהורא וממרירו למיתקא בכדי שעי\"ז יאכ\"ל אח\"כ מהשפע עליונה המתגלה בשבת בלי מסך ופרסא כלל שכבר העביר אותו בעובדי' דחו\"ל במלאכת הברורי\"ן וזהו ענין המילה וכלא חד כנ\"ל וד\"ל.\n<b>וזהו</b> אני הנה בריתי אתך והיית לאב המון גויים ולא יקרא עוד שמך א\"ב ר\"ם וגו' פי' כי אברם הי' קודם שנמול בשר ערלתו שא\"ב הוא הרמ\"ז על שרשו שהוא בחי' חכמ\"ה דאצי' שמאי\"ן תימצא המחדש בטובו בכל יום תמיד מע\"ב מאי\"ן ליש שהוא בחי' היחוד תמידי דאו\"א<sup data-n=\"667\">52</sup> דאצי' שהם תרין ריעין דלא מתפרשין כנודע, ר\"ם הוא שנקרא מצד הערלה המכסה על הברי\"ת והוא בחי' יסוד ז\"א דאצי' שעפ\"י רבוי ההשתלשלות נסתעף מזה בחי' הפרסו' דעשי' המבדלת בין הקדש ובין החול הוא נוגה דעשי' וכן בין נוג\"ה לג' קליפות הטמאו' לגמרי שנסתעף מזה בחי' ע' שרים דקליפה דכתיב רם<sup data-n=\"668\">53</sup> על כל גוים ה' וגו' וכמשנ\"ת בתורה ובאמת בלתי אפשר היה אז שיתגיירו גרים מאו\"ה כי מאחר ששרשם מאחורי הפרגוד דעשי' איך ישובו ויתכללו בקדושה שקודם הפרגוד דעשי'.\n<b>אך</b> לאחר שנמול אברהם שנקרע המסך והפרגוד שלמטה דעשי\"ה אז נאמר לא יקרא עוד שמך א\"ב ר\"ם והי' שמ\"ך אברהם כי אב המון גוים &lt;עא&gt;\nנתתי\"ך שאז באפשר שיתגיירו גרים מאו\"ה מאחר שנקרע הפרסא והמסך הנ\"ל ואז נקרא אברה\"ם אב\"ר מ\"ה. וזהו ענין המילה כי מילה<sup data-n=\"669\">54</sup> הוא אותיו' מ\"ל י\"ה דהיינו לאחר שנכרתה הערלה אזי נתגלה שרש שרשה שנמשכה מלבוש הח\"ש מ\"ל ששרשו הוא מחיצוני' דחו\"ב כנ\"ל שזהו מ\"ל י\"ה שנתגלה בחי' י\"ה והפריע\"ה היא בחי' התגלות יותר דאתפריעו כל נהורין וכענין ופרע<sup data-n=\"670\">55</sup> את ראש האשה או בית השחיטה<sup data-n=\"671\">56</sup> מפורעת כו' כנ\"ל.\n<b>וביאור</b> הענין דהנה ברי\"ת קדישא העליון הוא בחי' יסוד בכ\"מ שיסוד הוא בחי' האבר המשפיע השפע של המשפיע אל המקבל ומקשר השפעת המשפיע והמקבל יחד כמו עד\"מ בנפש האדם שכאשר יתאווה תאוה לאיזה דבר באהבה בלב ואח\"כ יחשוב הדבר ההוא במחשבתו נק' זה ההתחברות וההתקשרו' של המידה בהמחשבה בחי' יסוד ז\"א שהוא בחי' כלי ההשפעה של המדות אל המחשבה והוא המקשרן שניהם יחדיו וכן מהשכל אל המדו' נק' ההשפעה בחי' יסוד אימא וכן מלמעלה מהשכל אל השכל נק' יסוד של הרצון והכת\"ר כך ממש עד\"מ למעלה וד\"ל. אך הערלה היתה חופה עליו שהוא בחי' הסתרת הפרסא שנסתעפה מלבוש החשמ\"ל כנ\"ל וכיון שנימול אזי נתגלה השפע דיסו\"ד צדי\"ק העליון בחי' סוכ\"ע בלי לבוש והסתרה כלל ולכך נק' אברה\"ם כי אב המו\"ן גויי\"ם נתתי\"ך כנ\"ל וד\"ל.",[["667","52","<b>דאו\"א דאצי' שהן תרין רעין</b>: ראה זהר ויקרא ד, א."],["668","53","<b>רם על כל גוים ה'</b>: תהלים קיג, ד."],["669","54","<b>מילה הוא אותיות מ\"ל י\"ה</b>: נסמן לעיל ע' קב הערה 45."],["670","55","<b>ופרע את ראש האשה</b>: נשא ה, יח."],["671","56","<b>בית השחיטה מפורעת</b>: ראה חולין יט, ב. ל, א."]]],[2100490184,"<b>וזהו</b> אנ\"י הנה ברית\"י אתך וגו' דטעמ\"א דאנ\"י הוא זקף גדול כו' בהיות ידוע שהחכמ\"ה מאין תימצא הוא בחי' הכתר פרצוף או\"א דאצי' שנק' בשם אי\"ן, ואנ\"י<sup data-n=\"672\">57</sup> הוא התהפכות צרופי אותיו' אי\"ן שהוא בחי' השפעת הכת\"ר מקור החכמה המלובש בחכמ\"ה דאצי' שהחכמה מאי\"ן תימצא אבל כיון שנתלבש בה השפע דכ\"ע א\"ז נתהפך הצירוף דאי\"ן לאנ\"י. וזהו הכלל גדול בכ\"מ שנאמר אנ\"י, אך כאן נרמז בנגינה דזקף<sup data-n=\"673\">58</sup> גדו\"ל שעל תיבת אנ\"י לרמז על למעלה מעלה על בחי' החכמה בעודה נעלמה בכ\"ע וזהו הנגינה דזקף גדו\"ל דטעמא לעילא כו' ומשם נמשך בחי' ברית\"י אתך דהיינו כמארז\"ל גדול\"ה מילה שנכרתו עלי' י\"ג בריתות<sup data-n=\"674\">59</sup> שהמה י\"ג ת\"ד דאו\"א דאצי' שלכך<sup data-n=\"675\">60</sup> נקראת גדול\"ה מיל\"ה כמ\"ש במ\"א שבא\"א שם כחשיכה כאורה שוי' ולזאת כאשר נתגלו הי\"ג ת\"ד דא\"א שהמה י\"ג בריתות שנכרתו כו' אזי והיית לאב המון גוים שיתגירו גרים מאו\"ה דגם חשך לא יחשיך כו' וכחשיכה כאורה כו' וזהו אנ\"י הנה ברית\"י דייקא אתך שע\"י אתערותא דלתתא במיל\"ה שלמטה נתעורר אתערותא דלעילא להעביר הפרסא דא\"א (שיתגלה בחי' יסו\"ד דארי\"ך) שזהו גדולה מילה שנכרתו עליה י\"ג בריתות הם י\"ג ת\"ד שנתגלו אז והיית לאב המון גוי\"ם וכנ\"ל וד\"ל.",[["672","57","<b>ואני. . צרופי אותיו' אין</b>: ראה מאו\"א אות א' סס\"ד."],["673","58","<b>דזקף גדול. . לרמז על למעלה מעלה</b>: ראה באוה\"ת מטות ע' א'שכז שמציין לזח\"ג קצא, ב. וראה פרדס שכ\"ט, פ\"ג. וראה לקו\"ת מטות פג, ג."],["674","59","<b>גדולה מילה שנכרתו עלי' י\"ג בריתות</b>: נדרים לא, ב (במשנה)."],["675","60","<b>שלכך נקראת גדולה מילה</b>: ראה תו\"א יג, ג-ד. תו\"ח לך צד, ג."]]],[2100490185,"<h3>להבין מאמר הזוהר פ' ויצא ע\"פ ויקח מאבני המקום</h3>\n<b>להבין</b> מאמר הזוהר<sup data-n=\"676\">1</sup> פ' ויצא (דף קמ\"ח ע\"א וע\"ב) ע\"פ ויקח מאבני המקום כו'. פתח ההוא ב\"נ קומה<sup data-n=\"677\">2</sup> ה' למנוחתיך כו' כמאן דאמר יקום מלכא לבי נייחא דמשכניה כו' כהניך ילבשו צדק וחסידיך ירננו מכאן אוליפנא דמאן דמזמין למלכא דחדאן ליה בדיחי הדיוטא יסדר קמיה בדיחי רופינס ופרדשכי ואי לאו לאו איהו בדיחותא דמלכא, ת\"ח דוד שני בדיחי דמלכא בגין רופינס הה\"ד כהניך ילבשו צדק וחסידיך ירננו. ולוויך ירננו מבעי ליה דהא ליואי אינון בדיחי דמלכא. אלא השתא בגין דזמין ליה לנייחא עביד כהני וחסידי דליהוי אינון בדיחי כו' אינון דחשיבי יתיר אע\"ג דלאו אורחייהו בהאי ע\"כ דברי המאמר.",[["676","1","<b>להבין מאמר הזוהר פ' ויצא. . ע\"פ ויקח מאבני המקום</b>: הנחת כ\"ק אדמו\"ר האמצעי, נעתק מכת\"י 1156 עב, ב עם הגהות כ\"ק אדמו\"ר הצ\"צ. נמצא ג\"כ בכת\"י 68 יב, ב.\nנדפס ג\"כ (בלי הגהות כ\"ק אדמו\"ר הצ\"צ) בביאוה\"ז קלב, א. ובביאוה\"ז מכ\"ק אדמו\"ר הצ\"צ ח\"א ע' קמ נדפס קיצור והגהות על מאמר זה. וכן נדפס באוה\"ת בראשית כרך א קעז א (באריכות יותר).\nהנחת ר' משה בן אדה\"ז נדפס לקמן ע' קלא."],["677","2","<b>קומה ה' למנוחתיך</b>: תהלים קלב, ח."]]],[2100490186,"<b>והנה</b> להבין תוכן כוונת כללות הענין במה דשינה בדיחי דמלכא השתא דזמין ליה לנייחא דווקא וכמ\"ש קומה ה' למנוחתיך כו' ולא בתחלה וגם לא לאחר שיכנס לנייחא במקדש שבנה שלמה דהלוים הן בדיחי דמלכא כמו קודם כו'. הנה צריך תחלה להבין פי' וענין נייחא זה שהוא מ\"ש קומה ה' למנוחתיך כו'. דהנה כתיב כי<sup data-n=\"678\">3</sup> לא באתם עד עתה אל המנוחה. וידוע דרז\"ל המנוחה<sup data-n=\"679\">4</sup> זו שילה ואל הנחלה זו ירושלים כו'. והענין ידוע דבהמ\"ק שבנה שלמה הנק' בית עולמים הוא הנק' נחלה. אבל כל ימי היותו עם בנ\"י במשכן בגילגל בנוב וגבעון וגם במשכן שהי' במדבר לא נק' מנוחה וגם שילה לא נק' נחלה ועל כן אמר כי לא באתם עד עתה אל המנוחה ואל הנחלה וכו' וכמ\"ש לדוד ואהיה<sup data-n=\"680\">5</sup> מתהלך באוהל ובמשכן (ולפ\"ד רשב\"י בפי\"ד דזבחים גם שילה לא נק' אפי' מנוחה אלא מנוחה ונחלה זו וזו קאי על ירושלים) וכו'. ויש להבין הטעם לזה דהאיך יתכן דמשום בנין בית מאבני' וסיד יהי' נק' בשם מנוחה לאלקים חיים שלא נערוך אליו קדושתו ואין לו<sup data-n=\"681\">6</sup> גוף ולא דמות הגוף כו'. וכמ\"ש השמים<sup data-n=\"682\">7</sup> כסאי כו' איזה בית אשר תבנו לי כו'.\n<b>אך</b> הענין יובן בהקדים טעם הילוך משה ובנ\"י במדבר עם הארון והמשכן כו'. דהנה ידוע דהמדבר הוא מקום שבו ישכון מקור יניקת החיצונים כולן. וכמ\"ש במדבר<sup data-n=\"683\">8</sup> הגדול והנורא הזה נחש שרף ועקרב שהן ג' מיני קליפות הטמאות כו' כמ\"ש בספרי הקבלה. והנה בשעה שעמדו ישראל על הר סיני פסקה<sup data-n=\"684\">9</sup> זוהמתן מזוהמא של נחש הקדמוני. אך עדיין לא נפסק לגמרי מכל וכל מפני החטא שחטאו מיד כידוע. וע\"כ לא נשלמה מעלתם עדיין בשלימות ונשאר מן הרע שלהם שרש ומקור למטה שצריך בירור ותיקון בתחילה. וזה היה הטעם שהוליכם ה' לבנ\"י עם הארון ומשה בראשם במדבר דווקא כדי להכניע בזה ההילוך את שרש ומקור יניקת החיצוני' ששוכן במדבר דווקא כנ\"ל. והוא מפני עוצם בחי' גילוי אלקות שהי' ע\"י הילוכם זה כידוע בשרש<sup data-n=\"685\">10</sup> ענין מ\"ב מסעות שלהם וכמ\"ש במ\"א וד\"ל. ואמנם הנה זה ההילוך לאכפיי' לסט\"א ולאהפכא חשוכא לנהורא כנ\"ל הי' כעין מלחמה ממש. ועד\"מ מלך בו\"ד שהלך למרחקים במקום וארץ של השונא שלו המנגדו לכבוש מקומו ממשלת שונאו בהילוכו שם עם חייליו הרבים וכו'. שיש בזה ב' דברים. הא' מה שעקר המלך משכן כבודו בעיר ממלכתו והלך בארץ נכריה אשר לא היה כדאי",[["678","3","<b>כי לא באתם עד עתה אל המנוחה</b>: דברים יב, ט."],["679","4","<b>המנוחה זו שילה</b>: ראה מגילה י, א."],["680","5","<b>ואהיה מתהלך באוהל ובמשכן</b>: שמואל-ב ז, ו."],["681","6","<b>ואין לו גוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם סנהדרין פ\"י היסוד הג'. לקו\"ת ברכה צט, ד. ספר מאמרי אדה\"ז הנחות הר\"פ דף פא."],["682","7","<b>השמים כסאי. . איזה בית אשר תבנו לי</b>: ישעי' סו, א."],["683","8","<b>במדבר הגדול. . נחש שרף ועקרב. . ג'. . קליפות הטמאות</b>: עקב ח, טו. וראה תו\"א קט, ד. לקו\"ת נשא כ, א (ובהנסמן בהמ\"מ לשם). מסעי פח, ג. תו\"ח בשלח קלז, ד. מאמרי אדה\"ז תקע\"א ע' רכז. שע\"ת ד, ב והערה 19."],["684","9","<b>פסקה זוהמתן</b>: שבת קמו, רע\"א. וש\"נ."],["685","10","<b>בשרש ענין מ\"ב מסעות. . וכמ\"ש במ\"א</b>: ראה לקו\"ת חקת נח, ד. מסעי פט, ב ואילך. אוה\"ת חקת (הוצאת תשנ\"ח) ע' תשס ואילך. ובכ\"מ."]]],[2100490187,"בזיון שילך לשם מאיזה טעם שיהיה. אך מפני נצחון שלו לכבוש את מדינת שונאו כו'. והב' מה שהולך במדינת שונאו לכבוש בהילוכו זה שהוא כענין מלחמה ממש כי בהיותו צריך לכבוש המקום של השונא בהכרח שילך עם ריבוי חיילות ועם עושר גדול מכל כלי חמדה ולהראות דווקא כבוד גדלו במסעותיו כו'. וכך הנמשל יובן למעלה שהי' הילוך בנ\"י במדבר כענין ניצוח מלחמה. כי בהגלות נגלות שם את יקר תפארת גדולת ה' ע\"י המסעות ושכינה עמהם בארון ומשה ואהרן כו' ממילא נתהפך חשוכא לנהורא. וכמ\"ש קול<sup data-n=\"686\">11</sup> ה' יחיל מדבר כו', ואמנם הי' זה כענין מלחמה וכמ\"ש ה'<sup data-n=\"687\">12</sup> איש מלחמה כו' וד\"ל. וזהו שאמר כי לא באתם עד עתה אל המנוחה כו' מפני ב' דברים הנ\"ל הא' מה שעוקר דירתו ממקום ממלכתו כו'. והב' מה שעוסק במלחמת ניצוח כו'. אבל בבהמ\"ק שבנה שלמה הוא הנק' מנוחה מב' דברים הנ\"ל דהיינו מה שהמלך דר בהיכלו וגם אינו עוסק במלחמה כלל כו'. אך הנה דבר זה צריך ביאור עדיין דהלא מציאות הרע גם בימי בנין בהמ\"ק הי' עדיין כי לא הי' בחי' שלימות עדיין מכל וכל אלא עד ימות המשיח דכתיב ואת<sup data-n=\"688\">13</sup> רוח הטומאה אעביר כו' וא\"כ גם בהיות הבנין דבית המקדש הי' צריך למלחמה ולמה נק' בשם מנוחה כו'.\n<b>אך</b> הענין הוא משום דכל עיקר ענין השראת השכינה בהיכל ק\"ק שבבהמ\"ק היינו שהי' בחי' גילי אור א\"ס למטה בהיכל ק\"ק דעשי' כמו שאוא\"ס מאיר בעולם האצי' בהשוואה אחת כו'. ובזה הדבר הוא יתרון מעלת השראת השכינה בהיכל ק\"ק שבבהמ\"ק יותר מבמשכן שילה ונוב כו'. כי לא היה שם ענין ההשראה בדרך כזה. ויובן ההפרש ביניהם עד\"מ ודוגמא למטה דהנה כאשר ידליקו אור אבוקה גדול להיות כי שלהבת המדורה והאבוקה מתפשטת בהתפשטות גדולה מאד אזי כאשר יש בסמוך לה אורות ניצוצי' קטני' המה נמשכי' ממילא ונדעכים ממקומם ונכללים באור שלהבת האבוקה הגדולה ומתקבצים כולם ונכללים בה. וזהו\"ע ביטול נר בפני האבוקה כידוע. והנמשל מזה יובן למשכיל למעלה כי בהיות גילוי אור א\"ס כמו שהוא באצי' מתפשטת ההארה בתכלית גם בעולמות הנפרדים עד העשי'. היינו בהתגברות אור האבוקה ואז ממילא כל מה שיש בהשתלשלות בחי' אורות וניצוצות קטנים עד\"מ מתבטלים כולם ונכללים בעצמות גילוי אור האלקי כו' וע\"כ ממילא נתבטל גם החושך ונתהפך לאור כו'. וכמ\"ש כהמס<sup data-n=\"689\">14</sup> דונג מפני אש כו'. וזה הדרך אינו ענין מלחמה כלל כי הרי מתבטלים גם כל החיצונים ממילא. מפני עוצם הגילוי שנכללים כולם במקור האמיתי כו'. וע\"ד זה הי' ענין השראת השכינה בהיכל ק\"ק שבבהמ\"ק שהי' שם גילוי אור א\"ס כמו שהוא למעלה באצי' וע\"כ נק' מנוחה. והענין הוא דהארון כשהיה במשכן בשילה ונוב וגבעון לא היה שם בדרך מנוחה כזו לפי שלא הי' שם גילוי אוא\"ס כמו שהוא במקומו העצמי. אלא היה הולך ומתהלך בדרך עד\"מ והוא ע\"ד המלך שהולך למרחקים לכבוש שונאו כנ\"ל שבזאת הכניעם. אבל כשדוד ע\"ה הביא הארון מנוב וגבעון שהי' שם בדרך הגלות בענין ניצוח מלחמה למרחוק כו'. וקבעו בירושלים שהוא במקומו העצמי דהיינו עיקר מקום ממלכתו של",[["686","11","<b>קול ה' יחיל מדבר</b>: תהלים כט, ח."],["687","12","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["688","13","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["689","14","<b>כהמס דונג מפני אש</b>: תהלים סח, ג."]]],[2100490188,"מלך עד\"מ. והוא שיתגלה בהיכל ק\"ק ויכניע החיצונים ע\"ד הביטול ממילא כנ\"ל אזי אמר דוד הפסוק הזה קומה ה' למנוחתיך כו' מפני שנק' בהמ\"ק בית מנוחתו של הקב\"ה שלא יצטרך לצאת עוד למלחמה למרחוק. כי במקומו יכניע שונאו ע\"י גילוי אורו העצמי בהיכל ק\"ק עד\"מ ביטול הנר בפני האבוקה כנ\"ל וד\"ל.\nב. <b>והנה</b> בחי' ההמשכה הנ\"ל שהיה בהיכל ק\"ק בבהמ\"ק שנתגלה שם אוא\"ס כמו שהוא למעלה זהו הנק' בחי' יחוד דהיינו שנעשה בחי' המשכת יחוד עליון למטה כו'. וביאור ענין היחוד דא\"ס יובן ע\"פ דוגמא ממה שמצינו יחוד כיוצא בזה למטה בעולמו' הנפרדים כמו מחנה<sup data-n=\"690\">15</sup> מיכאל ומחנה גבריאל שהן למטה מטה בעשי' ממש ענין שר של אש ושר של מים כידוע. וכתיב בהם עושה<sup data-n=\"691\">16</sup> השלום במרומיו שאין מכבין זא\"ז כידוע. והוא מטעם שנתגלה עליהם תוס' אור האלקי מבחי' האצי' יתר מכפי המדה שנמדד להם שפע אור וחיות. ואזי ממילא מתבטלים ממציאות התפשטות הראשונה ואינם בגדר מציאות דבר מה עד שיהי' הפכיים להיות מכבים זא\"ז וכיוצא. וה\"ז כמשל העומדים לפני המלך ממש שאע\"פ שיהיו מחולקים בתכלית מפני בחי' ביטול העצום שיש בהם אז בעמדם לפני המלך ישכחו על עצמותם לגמרי מכל וכל ואין להם מציאות כלל. וא\"כ איך יהיו מנגדי' זה לזה. אלא אדרבה מתייחדים בתכלית היחוד כי המה יחד מתכללים ובטילים לפני המלך. כך עד\"ז ענין ביטול העצום דמיכאל וגבריאל למעלה והוא מפני תוס' גילוי אור האלקי עליהם עד אשר מתכללים יחד ובטילים באור האלקי וזהו ממש כביטול הנר בפני האבוקה כנ\"ל וד\"ל. והדוגמא מכ\"ז ממש יובן למשכיל למעלה מן המאציל עצמו לנאצלים ממנו באורות וכלים כו'. דידוע שיש בחי' ג' קווין בי\"ס דאצי' בדרך כלל חח\"נ מימין ובג\"ה משמאל כו'. והנה אור החכ' דאצי' הוא בחי' הראשית בכל מקום. וכמאמר אנת<sup data-n=\"692\">17</sup> חכים כו' והוא מקו הימין ובחי' בינה דאצי' מקו השמאל כו'.\n<b>ואמנם</b> הנה באמת לגבי עצמות המאציל הרי כל ההשתלשלות בי\"ס בג' קוין הללו הם רק כמו דוגמת אור וזיו השמש לגבי עצמות מאור השמש ולכך נק' בשם אורות כידוע כדוגמת התהוות הנבראים יש מאין למטה כמו ד'<sup data-n=\"693\">18</sup> מחנות שכינה מחנה מיכאל לימין כו'. כך למעלה לגבי עצמות המאציל הרי נאצלו בבחי' יש מאין גם כן. וכמ\"ש והחכמה<sup data-n=\"694\">19</sup> מאין תמצא כו'. וכמא' אנת הוא דאפקית עשר תקונין וקרינן לון יו\"ד ספירין כו'. אבל מצד עצמותו הרי אמר בסוף המא' לאו דאית לך צדק ידיעא כו' ולאו מכל אינון מדות כלל. וא\"כ כל הנאצלים בכלל אינם נחשבים רק כדוגמת בחי' עשי' באדם התחתון שכח הפועל בלבד יש בנפעל בבחי' איזה רשימו והארה קטנה מאד כו' וזהו שאמר כולם<sup data-n=\"695\">20</sup> בחכמה עשית וקאי גם על כלל",[["690","15","<b>מחנה מיכאל ומחנה גבריאל. . שר של אש ושר של מים</b>: ראה במדב\"ר פי\"ב, ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה ובהנסמן לשם."],["691","16","<b>עושה השלום במרומיו</b>: איוב כה, ב."],["692","17","<b>אנת חכים</b>: תקו\"ז בהקדמה (יז, א)."],["693","18","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב. ובביאורי הזוהר לשם."],["694","19","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["695","20","<b>כולם בחכמה עשית</b>: תהלים קד, כד."]]],[2100490189,"ההשתלשלות דעולם האצי' בכלל נק' חכמה. וכידוע המאמר דאור<sup data-n=\"696\">21</sup> אבא באצי' ואימא בבריאה וז\"א ביצירה כו' ואמר עשית שאינו אלא בחי' עשי' בלבד והוא מטעם הנ\"ל וד\"ל. ולהיות כן כאשר ניתוסף איזה תוס' אור ושפע עליהם מעצמות המאציל אזי בודאי גם בהם יתכן לומר ממש כדוגמא כנ\"ל במחנה מיכאל וגבריאל למטה דהיינו שמחמת זה שמתבטלים ממציאות אצילותם ונכללים יחד ובטילים באור המאציל המאיר עליהם כמו ע\"ד ביטול הנר בפני האבוקה ממש וכנ\"ל וזהו הנק' בחי' יחוד עליון דאור א\"ס בנאצלים דהיינו מה שמתייחדים ג' הקוין חב\"ד וחג\"ת כו' ומתכללים יחד בבחי' קו\"ח דאוא\"ס כאשר מאיר בהם קצת בתוס' ההמשכה והשפע מכפי המדה הראשונה שנמדד בהם ע\"י בחי' קו המדה כידוע וד\"ל. ואמנם הנה זהו הנק' בשם בחי' המשכת יחוד דאוא\"ס בנאצלים אחר שהוא בא ונמשך בהם להאיר בהם בתוספות ההארה כנ\"ל אבל עדיין י\"ל מהיכן יהא סיבת ירידת והמשכת בחי' יחוד עליון זה למטה באבי\"ע כו'.\n<b>הענין</b> הוא כידוע דנגד ג' קווין הללו למעלה יש למטה בכנ\"י כדוגמא זו למטה ג' קווין. והן כהנים לוים וישראלים. כהנים<sup data-n=\"697\">22</sup> שהם מסט' דימינא כידוע הם ממשיכים בקו<sup data-n=\"698\">23</sup> הימין דחח\"נ כו' לוים שהם מסט' דשמאלא ממשיכי' בקו השמאל בג\"ה כו' וישראל<sup data-n=\"699\">24</sup> הן בבחי' קו האמצעי דת\"י<sup data-n=\"700\">25</sup> עמודא דאמצעית' כידוע. והנה תחלה יש לבאר ענין הכהנים איך הן ממשיכים יחוד עליון בקו הימין כו' בהיות יודע דג' מדריגות יש בכהנים נגד ג' מדריגות שיש בקו הימין חח\"נ. והיינו המדריגה העליונה השרשי' לכולם הוא בחי' כהן<sup data-n=\"701\">26</sup> גדול שהוא בבחי' חכ' עצמה כידוע ולכך נק' כהן גדול כו' וכמ\"ש בסה\"ק<sup data-n=\"702\">27</sup>. והב' למטה הימנו והוא הנק' איש כהן וגם נק' סגן הכהנים והוא בחי' החסד<sup data-n=\"703\">28</sup> ענף החכמה ונק' ג\"כ איש החסד ולהיות שהוא רק בחי' ענף החכמה ע\"כ נק' איש כהן ולהיותו גדול עדיין מבחי' נצח שהרי הנצח אינו אלא ענף מן החסד כידוע ע\"כ נק' בשם סגן הכהנים וגם פי' איש כהן יתפרש שהוא איש לגבי כהן הדיוט וכהן סתם הוא כהן הדיוט והוא מדריגת השלישית שהוא רק בבחי' נצח ענף החסד. והכהנים בכלל הם רק בבחי' נצח. ואמנם בהיותם מברכים ברכת כהנים אז הם בבחי' נצח דאור אבא כו' וד\"ל. ועכ\"פ בכלל הנה כל הכהנים הם מבחי' קו הימין דחח\"נ כו' וע\"כ היה ענין עבודתם העיקרי' רק להמשיך אור חסד עליון מעצמות המאציל לקו הימין חח\"נ",[["696","21","<b>דאור אבא באצילות</b>: ראה ת\"ז ת\"ו (כג, א)."],["697","22","<b>כהנים שהם מסט' דימינא</b>: ראה זהר נשא קמה, ב."],["698","23","<b>בקו הימין דחח\"נ</b>: ראה זהר (רעיא מהימנא) בהעלותך קנג, ב. פרדס שער (ו) סדר עמידתן פ\"א."],["699","24","<b>וישראל הן בבחי' קו האמצעי</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנב."],["700","25","<b>דת\"י עמודא דאמצעית'</b>: ראה זהר (רעיא מהימנא) תשא קפז, ב. ביאוה\"ז שם נד, ב. וראה זהר (רעיא מהימנא) פינחס רמג רע\"ב."],["701","26","<b>כהן גדול</b>: ראה מגיד מישרים פ' נצבים ד\"ה אבל רזא דמלתא דזרוע (קמג, א). פרדס (שער עה\"כ) שכ\"ג מערכת כהן גדול."],["702","27","<b>בסה\"ק</b>: בספרי הקבלה."],["703","28","<b>החסד ענף החכמה</b>: ראה זהר ואתחנן רסב, סע\"א. לך צד, א. תרומה קעה, ב. במדבר קיח, ב."]]],[2100490190,"כו'. והמשכה זאת היתה ביכולת בהם ע\"י ב'<sup data-n=\"704\">29</sup> דברים המבוארים בזוהר בכמה דוכתי בעובדא וברעותא דליבא.\n<b>ותחלה</b> יש לבאר ענין רעו\"ד בכהנים מה הוא. להיות ידוע<sup data-n=\"705\">30</sup> בלק\"א דיש ב' מיני אהבה כו'. והא' היא אהבה הנמשכת כמים והיא מסט' דחסד. והענין ע\"ד דוגמא בבני אדם שאוהבין זה לזה הנה באהבת הא' לחבירו ימשוך את לבב חבירו אליו כי כמים הפנים כו'. וזאת ההמשכה שנמשך לב חבירו אליו ע\"י אהבתו אליו נק' אהבה הנמשכת כמים להיותה מסט' דחסד שהוא כמו מים<sup data-n=\"706\">31</sup> שיורדים ונמשכים מגבוה לנמוך כו'. והדוגמא מכ\"ז יובן למשכיל למעלה דגם עד\"ז הי' בכהנים ברעותא דלבא באהבה שהיא מושכת למעלה כמים הפנים כו' וכמ\"ש אהבת<sup data-n=\"707\">32</sup> עולם אהבתיך ע\"כ משכתיך חסד כו' פי' כמו שנתעוררו באהבה ודביקות מלמטה למעלה. והיינו שנמשכו לבם ברעותא מלמטה למעלה כך עד\"ז ממש המשיכו אור אהבה וחסד מלמעלה למטה כמים הפנים וזהו ע\"כ משכתיך כו' וכידוע ג\"כ בדרך הזה בפי' ואהבת<sup data-n=\"708\">33</sup> את ה' אלקיך. ועי\"ז המשיכו למעלה בשרשם בבחי' קו הימין חח\"נ דאצילות ג\"כ מבחי' אור חסד עליון שבעצמות המאציל מאחר שהי' שורש נשמתם משם הרי הרוח<sup data-n=\"709\">34</sup> אייתי רוח ואמשיך כו' וכנודע וד\"ל. וזה הי' בהם בבחי' רעותא דליבא. והב' הי' בעובדא והיינו בעבודת הקרבנות בפ\"מ כמו בזריקת דמים ע\"ג המזבח וכיוצא בזה בכל פרטי העבודות שהיו במקדש כו'. והנה תחלה י\"ל שורש ענין הקרבנות ומה ענינם עד שנאמר שמחמת זאת העובדא המשיכו ג\"כ מאור עצמות המאציל בנאצלי' וכו'.\n<b>דהנה</b> ידוע שיש ג'<sup data-n=\"710\">35</sup> מדריגות עקודים נקודים וברודים כו' ובחינת ברודים הוא בחי' התיקון ונקודים הוא מבחי' התוהו שלפני התיקון. וכמ\"ש ואלה<sup data-n=\"711\">36</sup> המלכים אשר מלכו כו' לפני מלך מלך לבנ\"י כו'. וידוע ג\"כ דלזה הטעם שבחי' התהו קדם לתיקון ע\"כ נאמר כי<sup data-n=\"712\">37</sup> על כל מוצא פי ה' יחיה האדם. והענין הוא משום דהאדם<sup data-n=\"713\">38</sup> הוא מבחי' התיקון ומוצא פי ה' שבמאכל הוא מבחי' התהו שקדם לתיקון ע\"כ ממנו יחיה האדם. ואע\"פ שהמדבר<sup data-n=\"714\">39</sup> גבוה מן הצומח ביו\"ד מאמרות כו'. מ\"מ",[["704","29","<b>ב' דברים. . וברעותא דליבא</b>: ראה ג\"כ לקו\"ת ויקרא ג, ד."],["705","30","<b>ידוע בלק\"א דיש ב' מיני אהבה</b>: ראה תניא פמ\"ג."],["706","31","<b>מים שיורדים</b>: ראה תענית ז, א."],["707","32","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב."],["708","33","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה."],["709","34","<b>הרוח אייתי רוח</b>: ראה זהר תרומה קסב ריש ע\"ב."],["710","35","<b>ג' מדריגות עקודים נקודים וברודים</b>: ראה ע\"ח שער ו (שער העקודים) פ\"א, ובכ\"מ."],["711","36","<b>ואלה המלכים אשר מלכו</b>: וישלח לו, לא-ג. ראה זהר (אדרא רבא) נשא קכח, א. ע\"ח שער הכללים פ\"א. שם (שער דרושי הנקודות) ש\"ח, פ\"ד."],["712","37","<b>כי על כל מוצא פי ה' יחיה האדם</b>: עקב ח, ג."],["713","38","<b>דהאדם הוא מבחי' התיקון</b>: ראה ג\"כ מאמרי אדה\"א קונטרסים ע' רטז. ובכ\"מ."],["714","39","<b>שהמדבר גבוה מן הצומח</b>: ראה ג\"כ תו\"א בשלח סה, א. יתרו עד, א. לקו\"ת שלח מג, ד. עקב ח, ג. מטות פא, ב. ובכ\"מ."]]],[2100490191,"מוצא פי ה' שבמאכל שרשו למעלה מבחי' האדם כו' וזהו שנק' בלשון מוצא פי ה'. כי פי' מוצא הוא לשון מקור ושורש כמו מוצא מים כו'. כי התהו הוא בחי' מקור ושורש לפי ה' שבתיקון כו' וד\"ל. וזהו כי על כל מוצא פי ה' יחיה, על כל מוצא פי ה' דוקא כנ\"ל. ובזה יובן מה שאנו רואים שדברים תחתונים כמו מאכל ומשקה יחזקו ויתוספו שכל ומדות באדם. וכמאמר ר\"נ<sup data-n=\"715\">40</sup> עד דלא אכילנא בשרא דתורא כו' ולא שתינא רביעי' יין כו' וכענין חמרא<sup data-n=\"716\">41</sup> וריחני פקחין כו' וכמ\"ש דבר זה באריכו' במ\"א. ומכ\"ז יובן גם שרש וטעם לקרבנות דהנה בחי' הבהמות כמו פרים ושעירים וכבשים שרשם מעולם התוהו שלפני התיקון וכאשר הזו מדם הפר והשעיר ע\"ג המזבח וכיוצא הנה בזאת ההזאה העלו אותו הדם הזה שמנוגה דעשיה עד שרשו בעולם התוהו בבחי' נקודים כו' ומחמת זה נמשך אור יחוד עליון בתוס' ההארה גם בבחי' התיקון דאדם העליון כנ\"ל להיותו מבחי' מקור מוצא פי ה' כמו המאכל שיחיה את האדם כנ\"ל וע\"כ נמשל אכילת מזבח לאכילת אדם כמ\"ש האכל<sup data-n=\"717\">42</sup> יאכל בב' אכילות הכתוב מדבר כו' וכמ\"ש במ\"א ע\"פ כי הוא יברך הזבח כו' וד\"ל.\n<b>וזהו</b> דרך כלל. ובדרך פרט על יסוד זה הוסדו כל פרטי עניני הקרבנות בכל פרטי דיניהם כמו בקרבן<sup data-n=\"718\">43</sup> עולה שטעונה ב' מתנות שהן ד' ובקרבן חטאת ד' מתנות על ד' קרנות שבוודאי יש סוד וטעם לכ\"א כפי מה שהוא כמו שיש כוונות<sup data-n=\"719\">44</sup> פרטיות במצות הנוהגות גם עכשיו וכמו תפילין וסוכה וכיוצא הנודעים בפע\"ח. כך יש בודאי לפרטי מצות הקרבנות כוונות וסודות עליונים ע\"ד המבואר בפע\"ח במצות שנוהגות בזמן הזה. וע\"ד כלל הנה נודע בכוונת ההזאות לפני ולפנים ביוהכ\"פ אחת למעלה וז' למטה כו'. וכך הי' מונה אחת ואחת אחת ושתים כו' שמבואר בזה ענין כוונה לי\"ס דאצי' בכלל. אחת היא בחינת הכתר שכוללת הכל ואח\"כ מסתעפי' ממנה הפרטים ולכן אומר אחת ואחת הכוונה על החכ' שהיא ג\"כ כוללת הכל מפני שנק' ראשית כידוע אבל כבר יש אחת ועוד אחת אמנם כשאומר אחת ושתים הכוונה על הכתר וחו\"ב שנק' שתיים שנכללי' בה כו' ועד\"ז כשמפרש עוד ואומר אחת ושלש הכוונה על הכתר וג\"ר חב\"ד וכן מה שאמר עוד אחת וד' מפני שהדעת מתחלק לחו\"ג ונעשה ד' מוחין חו\"ב חו\"ג בז\"א כידוע והכתר כוללם יחד כידוע. וזהו יותר פרטי' בהתחלקות. ועד\"ז יתפרש עוד פרטי התחלקות יותר במ\"ש אחת וחמש אחת ושש כו' וד\"ל<sup data-n=\"e27\">*</sup>. וכיוצא בזה הי' ג\"כ כל פרטי הכוונות שבכל",[["715","40","<b>ר\"נ. . עד דלא אכילנא בישרא דתורא</b>: ראה ב\"ק עב, רע\"א. וראה סה\"מ תקס\"ג ע' תשכו. ולהעיר שבאוה\"ת שה\"ש כרך א ע' קיג מביאו בשם ר\"ש."],["716","41","<b>חמרא וריחני פקחין</b>: ראה יומא עו, ב. תניא פ\"ז."],["717","42","<b>האכל יאכל. . במ\"א ע\"פ כי הוא יברך הזבח</b>: צו ז, ח. זבחים יג, ב. וראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קסג ואילך."],["718","43","<b>קרבן עולה. . ב' מתנות</b>: ראה זבחים פה, ב."],["719","44","<b>כוונות פרטיות. . הנודעים בפע\"ח</b>: ראה לקו\"ת שלח לט, א-ב."],["e27","*","<b>וד\"ל</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק אדמו\"ר הצ\"צ: וע' בסדר עבודת יה\"כ להרמ\"ק ובפע\"ח יש כמה פי' בזה."]]],[2100490192,"פרטי הקרבנות במנחה וחטאת ואשם ועולה ושלמים וכו'. אך כללות הענין הוא דדוקא כהני משום דברעותא דליבא שלהם באהבה שנמשכת כמים כנ\"ל המשיכו מלמעלה גם כן ע\"ד האהבה כזאת דוקא והוא שיהא יורד מגבוה לנמוך כמים כו' וכנ\"ל. ע\"כ גם בעובדא שלהם במעשה הקרבנות יכול להמשיך בחי' תוספות גילוי אוא\"ס בי\"ס דאצי' רק שהי' גם הקרבן עצמו סיבה לפי שרשם מבחי' התוהו ומטעם הנ\"ל וד\"ל.\nג. <b>ועתה</b> י\"ל שורש ענין עבודת הלוים שהן לנגד בחי' קו השמאל בג\"ה כנ\"ל. הנה ידוע בזוהר שהלוים נק' בדיחי דמלכא. והעטם יובן בהקדים ענין א' המבואר בזוהר<sup data-n=\"720\">45</sup> ע\"פ ועבד הלוי הוא שכל עבודת הלוים הוא לעבוד ולתקן בחינת הוא שהוא בחינת עלמא דאתכסייא בכלל שנק' הו\"א כידוע. וביאור הדברים הנה תחילה י\"ל שרש עבודת הלוים ברעו\"ד שלהם איך שהוא בהיפוך ממדריגת הכהנים. כי הנה ידוע דיש ב' מיני אהבה. הא' אהבה הנמשך כמים והוא בחי' הכהנים כנ\"ל. והב' מדריגת אהבה שהיא ברשפי אש התלהבות מלמטה למעלה כשלהבת העולה כו'. שהיא הפכי' ממש מאהבה של כהנים כמו שהאש היפוך המים שהאש עולה והמים יורדים. כך אהבת הלוים היה בבחי' הרצוא וההסתלקות כענין כלה שארי ולבבי כו'. וזהו מעלת<sup data-n=\"721\">46</sup> הזהב על הכסף במה שעולה ברום המעלות עד אין שיעור למעלה וכו'. וכמ\"ש אלקים<sup data-n=\"722\">47</sup> אל דמי לך כו'. ומפרש בזוהר<sup data-n=\"723\">48</sup> דקארי תדיר ולא שכיך כו'. מפני שאור אהבה זו עולה למעלה בבחי' הגבורות. ולזה אין שיעור כלל. וכמ\"ש אל<sup data-n=\"724\">49</sup> תחרש ואל תשקוט כו'.\n<b>ועיקר</b> הטעם לסיבת עלי' זו עד אין שיעור למעלה הוא לפי שגם ההתבוננות שממנה נתפעל באהבה כרשפי אש הזאת הוא ההתבוננות בענין רוממות אוא\"ס איך כמו שהוא בעצמו ומהותו שהוא נבדל בערך מכל ההשתלשלות בעילוי אחר עילוי עד אין שיעור למעלה. וע\"ז היסוד הוסדה עיקר ההתבוננות וה\"ז ג\"כ בחי' גבורות דהיינו איך שאוא\"ס הוא בבחי' הסתלקות והתכללות בעצמותו היפך ענין הירידה וההמשכה למטה. אלא אדרבה מפני שלא יוכל להתצמצם מעוצם הרוממות כו', עד שגם כל היותר עליון בהשתלשלות כמו עגולי א\"ק וכיוצא ג\"כ לא יכילוהו וכמ\"ש השמים<sup data-n=\"725\">50</sup> ושמי השמים לא יכלכלוך אפי' להיות רק בחי' כלי כו'. כי בחי' הכלי היא בחי' גבול. ובאמת לעצמות אוא\"ס כתי' לגדולתו<sup data-n=\"726\">51</sup> אין חקר ובחי' הכלי כבר יש לה חקר כו'. ולהיות כן גם מה שמבחי' גבורות הללו ישאר אינו אלא",[["720","45","<b>בזוהר ע\"פ ועבד הלוי</b>: קרח יח, כג. ראה זהר שם קעח, ב."],["721","46","<b>מעלת הזהב על הכסף</b>: ראה תניא פ\"נ. וראה ג\"כ תו\"א כי תשא פו, ב. לקו\"ת שה\"ש י, א."],["722","47","<b>אלקים אל דמי לך</b>: תהלים פג, ב."],["723","48","<b>בזוהר דקארי תדיר ולא שכיך</b>: ראה זהר פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. ועוד."],["724","49","<b>אל תחרש ואל תשקוט</b>: סוף הכתוב תהלים שם."],["725","50","<b>השמים ושמי השמים לא יכלכלוך</b>: מלכים-א ח, כז."],["726","51","<b>לגדולתו אין חקר</b>: תהלים קמה, ג."]]],[2100490193,"איזו רשימה בעלמא מבחי' החיצונית בלבד מפני שעולה בעילוי אחר עילוי כ\"כ עד שלא ירד למטה רק מבחי' החיצוני' דחיצוני' בלבד וד\"ל. ולזאת הוא כל עיקר עבודת הלוים בענין השיר שלהם על הקרבן הוא רק להביא ולהמשיך מבחי' עוצם ההעלם הזה שיבא לידי גילוי אור יותר. וזהו פי' ועבד הלוי הו\"א שעבודתו העיקרית הוא להמשיך מבחי' ההעלם של העצמות הנ\"ל וההעלם הזה נקרא הו\"א לשון נסתר. כי נסתר הוא בהעלם בבחי' העצמות מפני שעלה בעילוי אחר עילוי כו' וכנ\"ל וד\"ל. וזהו ג\"כ פי' לתבונתו<sup data-n=\"727\">52</sup> אין מספר. והוא להיות כי כתיב לגדולתו אין חקר כנ\"ל למעלה מבחי' ירידה וצמצום בכלי כו'. וצריך להיות בחי' התגלות אור בריבוי כלים מכלים שונים עד אין מספר לפי ערך עוצם הרוממות עד\"מ החכם המופלג שלפ\"ע רוממות שכלו כך ירבה כלים לחכמתו בכמה מיני שכליים וסברות רבות כו'. וכמו\"כ הוא שנעשה מאין חקר לתבונתו אין מספר כו' וד\"ל.\n<b>אך</b> עדיין י\"ל איך יפעלו הלוים ענין גילוי ההעלם הזה אחר שעבודת התפעלותם בהיפוך היא. שהרי הוא בבחי' הסתלקות אור כנ\"ל שאהבתם בבחי' רשפי אש היא כו'. אמנם הענין יובן בהקדים הפסוק החדלתי<sup data-n=\"728\">53</sup> את תירושי המשמח אלקים כו'. ופי' אלקים<sup data-n=\"729\">54</sup> ידוע שהוא בחי' הצמצום והן בחי' ה\"ג דשם אלקים המצמצם כו' כידוע, ויין ותירוש המשמח אלקים הוא ענין בחי' המתקת הגבורות דשם אלקים ע\"י היין שהיו מנסכים ע\"ג המזבח בשיר הלוים כו'.\n<b>וביאור</b> הדברים הנה תחילה י\"ל שורש ענין השמחה. כי הנה בחי' השמחה הוא בחי' התגלות ההעלם. כי הרי המלך כל כבודו בהיכל פנימה ואינו יוצא לחוץ לעולם. ובעת שמחתו יתגלה בחוץ לעין כל כי השמחה מביאה את הנפש מן בחי' ההעלם שלה לידי גילוי כידוע. והנה אין<sup data-n=\"730\">55</sup> שמחה אלא ביין שע\"י היין תשמח נפש האדם ויבא לידי גילוי מן ההעלם וכידוע בענין נכנס<sup data-n=\"731\">56</sup> יין יצא סוד כו'. וכמ\"ש ותירוש<sup data-n=\"732\">57</sup> ינובב כו'. וביין הוא דכתיב החדלתי את תירושי המשמח אלקים ואנשים כו'. פי' שהוא הממתיק בחי' הגבורות דשם אלקים. והיינו דוקא על ידי השיר שאומרים הלוים על היין שמנסכים על גבי המזבח וכידוע דאין<sup data-n=\"733\">58</sup> אומרים שירה אלא על היין כו'. ובסיבת שני אלה היין<sup data-n=\"734\">59</sup> והשיר נמתקו בחי' הגבורות דשם אלקים והוא מטעם דהגם שבחי' גבורות דשם אלקים הוא הצמצום וההסתלקות אור וכנ\"ל עד שלא נשאר רק בחי' התחתונה בלבד. אמנם היין והשיר הן המשמחים את אלקים זה כלומר שממתיקים אותו עד שבא מההעלם לגילוי. והוא ע\"י בחי' השמחה שמביאה מן ההעלם לגילוי כנ\"ל. וזהו המשמח אלקים כו'. אך אין זה בא רק ע\"י סיבת השיר",[["727","52","<b>לתבונתו אין מספר</b>: לשון הכתוב תהלים קמז, ה."],["728","53","<b>החדלתי את תירושי המשמח אלקים</b>: ס' שופטים ט, יג."],["729","54","<b>אלקים. . הצמצום</b>: נסמן לקמן ע' קלה."],["730","55","<b>אין שמחה אלא ביין</b>: פסחים קט, א."],["731","56","<b>נכנס יין יצא סוד</b>: עירובין סה, א."],["732","57","<b>ותירוש ינובב</b>: זכרי' ט, יז."],["733","58","<b>דאין אומרים שירה אלא על היין</b>: ברכות לה, א. וש\"נ."],["734","59","<b>היין והשיר. . בחי' הגבורות</b>: ראה ג\"כ תו\"א כה, ב. ויחי מו, ג. ועוד."]]],[2100490194,"דוקא. כי הנה השיר ענינו הוא בבחי' רו\"ש דוקא כמו הניגון שאין עיקר מתיקות ועריבות לנפש מהניגון אלא כשהוא כלול מב' תנועות הפכיי' בחי' רצוא ובחי' שוב והו\"ע החדוה והמרירות יחד ממוזג במזג נכון. אמנם אם הוא אינו ממוזג כ\"כ אלא הוא בתנועה א' של חדוה או בהיפוך אינו ערב לנפש כ\"כ ומכש\"כ אם אינו אלא קול א' פשוט שאין בו עריבות כלל. אך כשמזוג בקולות ותנועות דבחי' רו\"ש בכמה מיני אופנים שונים מזה תבא העריבות לנפש ותוכל לבוא מן ההעלם לגילוי אורה ושמחה כנראה בחוש וד\"ל.\n<b>והנמשל</b> מובן למעלה בכיוצא בדוגמא זו שכך הי' עיקר ענין שיר הלוים על היין כדי לעורר למעלה בקולות דרו\"ש שלהם בחי' עריבות ומתיקות שבזה יצא אור מבחי' ההעלם לגילוי עד שישמח אלקים וימתקו לגמרי בחי' הגבורות שלו. וכענין ועבד<sup data-n=\"735\">60</sup> הלוי הוא כו' וזאת הי' עיקר עבודתם תחילה ברצוא והתלהבות ואח\"כ בבחי' שוב. וע\"י כלי השיר והוא בעובדא ורעו\"ד ג\"כ שניהם יחד. כמו שמבואר למעלה בכהנים. וזהו שהיו צריכים הלוים ללמוד פרקי סדרי ניגוני השיר ע\"פ רוח הקודש שניתן לראשי אבות הלוים כבר כמו הימן וד' בניו כמבואר בדברי הימים כדי שידעו לכוון בשיר על פי רוח הקודש איך למתק הגבורות בכמה מיני אופנים שונים באופני מזגי הקולות בכדי שיהי' בו עריבות כו' וד\"ל. וזהו הטעם שנק' הלוים בדיחי דמלכא משום שמביאים למעלה מן בחי' ההעלם של עצמות לידי גילוי ועד\"מ הבדחן שמביא את המלך לידי גילוי וחדוה כו'. וע\"כ שורש יסודם הוא בבחי' קו השמאל בג\"ה כי בחי' רצוא הוא מבחי' בינה וזהו בינה גבורה. אמנם עבודתם העיקרית הוא להמשיך תוס' הגילוי מן ההעלם בקו זה השמאל. והו\"ע המתקת הגבורות בכלל וע\"ד שמבואר עבודת הכהנים בקו הימין כנ\"ל וד\"ל.\nד. <b>ובכ\"ז</b> יובן כללות ענין המאמר הנ\"ל במה ששינה דוד בדיחי דמלכא שהמה הלוים לכהנים וכמ\"ש וחסידיך ירננו כו' בשעה שאמר דוד קומה ה' למנוחתיך כו' והשתא דוקא משום דזמין לי' לנייחא כו' כנ\"ל. דהנה ענין המנוחה מבואר למעלה להיות שבבהמ\"ק לא הי' ענין מלחמה כלל אלא מפני הגילוי אור ממילא נתבטלו כו' והנה במשכן היה יתרון מעלה מצד אחר שהרי גופו של משכן הי' עשוי מיריעות תכלת וארגמן כו' והמקדש הי' בנוי מאבנים ועפר. ויש הפרש מדריגות הרבה בין בחי' דומם כאבנים לבחי' צומח כיריעות תכלת כו' כידוע. ומלבד זאת הנה ענין היריעות היו בדוגמא עליונה דוקא בכל מיני גוונין הראוים להיות דוקא והיינו כדוגמא של מעלה בגוונין העליונים דבחי' מדות העליונות דאצי'. שהוא תכלת וארגמן שש משזר כו' וכמבואר ענינם בזוהר. משא\"כ במקדש לא הי' כל אלה והכל הוא מטעם הנ\"ל דבמדבר הי' צריך למלחמה הי' צריך להמשכות עליונות ע\"י גוונין כדוגמא עליונה כו' משא\"כ במקדש שא\"צ למלחמה כלל א\"צ לכל אלה כו'.",[["735","60","<b>ועבד הלוי</b>: קרח יח, כג."]]],[2100490195,"<b>אך</b> עדיין י\"ל דמ\"מ למה נבנה המקדש מבחי' היותר תחתונה והוא בחי' הדומם כאבנים ועפר כו' אלא הענין יובן ע\"פ טעם הנ\"ל דבמקדש הי' הגילוי אור ממקום ומדריגה גבוה מאד מאד שלא הי' במשכן. והוא מבחי' העלם העצמות שלמעלה מעלה מבחי' סדר ההשתלשלות דאבי\"ע אשר ע\"כ בהגלות נגלות האור משם יתבטלו ויתייחדו כו' וכנ\"ל. לכך יכול להשפיל עצמו כ\"כ עד שיהי' משכנו בבחי' הדומם כעפר וכאבנים ג\"כ וכידוע הכלל שכל<sup data-n=\"736\">61</sup> הגבוה גבוה יותר יותר יוכל להשפיל א\"ע למטה מטה. וכענין ועברתי<sup data-n=\"737\">62</sup> בארץ מצרים אני ולא מלאך כו'. מפני שלעוצם רוממות אור העצמות גם מ\"ט<sup data-n=\"738\">63</sup> שע\"ט דמצרים כלא חשיבי וכמ\"ש כחשיכה<sup data-n=\"739\">64</sup> כאורה וגם חושך לא יחשיך כו' ודוקא קמיה ממש כחשיכה כאורה כו'. מטעם שהוא מובדל מבחי' ההשתלשלות לגמרי כנ\"ל. ומזה הטעם עצמו היינו שמשכנו היה בבחי' דומם כאבנים. הגם שהיא בחי' התחתונה. כי בחינת הדומם ובחי' המדבר שוין קמיה כו' וד\"ל. וזהו הטעם שנק' בנין בהמ\"ק מנוחה וכמ\"ש קומה ה' למנוחתיך כו' כי ההארה שהיא באה גם בבחי' היותר תחתונה הוא מטעם דקמי' כחשיכה כאורה כו' א\"כ אין כאן בחי' מלחמה כלל לאהפכא חשוכא לנהורא. אלא ממילא הוא כחשיכה כאורה וד\"ל.\n<b>וזהו</b> כללות כוונת המאמר השתא דוקא דזמין ליה לנייחא שני בדיחא דמלכא מלוים לכהנים וכמ\"ש וחסידיך ירננו כו', דהנה הגם שהלוים הן משוררים לדורות הבאים זהו מצוה הנוהגת לדורות. אבל דהע\"ה לפי שעה בלבד שהכין מקום מנוחה וכמ\"ש קומה ה' למנוחתיך דהכוונה היה על בנין שלמה כידוע אמר וחסידך ירננו לפי שהיה צריך שיומשך לבנין שלמה שהי' מאבנים ממקום ומדריגה גבוה מאד כנ\"ל דהיינו מבחי' העצמות דאוא\"ס. וידוע שבשביל המשכה שהיא יותר גבוה ויותר עליון צריך שתהא בחי' העלאה לשם ג\"כ ממדריגה היותר גבוה כי רוח אייתי רוח כו' הוא לפ\"ע כו' וע\"כ הגם שבחי' גילוי ההעלם במשכן הי' ע\"י הלוים כנ\"ל בפי' ועבד הלוי הוא ומטעם הנ\"ל אבל בכאן שבחי' ההעלם הוא יותר עליון כנ\"ל צריך הי' שימשיכו אותו אותם שהן גבוהים מן הלוים והן הכהנים. כי קו הימין חח\"נ כו' הוא יותר גבוה מקו השמאל בג\"ה כידוע דהחכ' נק' אין והבינה נק' יש כו'. והכהנים הם מבחי' חכ' כנ\"ל לכך שינה בדיחי דמלכא שכאשר הכהנים יהיו בדיחי דמלכא בעבודת הלוים ימשיכו אור מבחי' העלם היותר גבוה כו' וד\"ל. אך הנה עדיין י\"ל בעיקר הדבר למה הכהנים שרשם בחכ' דוקא. וגם איך יתכן שיחליפו עבודתם בעבודה ההפכית של הלוים כנ\"ל שעבודת הכהנים אינה אלא מלמעלה למטה ועבודת הלוים מלמטה למעלה. וגם איך יהיה בכהנים ענין המתקת הגבורות מאחר ששרשם רק מבחינת החסד כנ\"ל.\n<b>אך</b> הענין יובן בהקדים מ\"ש בע\"ח דע\"י היחוד דאו\"א נעשה מבחי' גבורות דאבא חסדים דאימא כו' ותחילה י\"ל פי' וענין חסדים דאימא. דהנה מבואר למעלה",[["736","61","<b>שכל הגבוה יותר</b>: ראה שערי אורה שער הפורים ע' נח וע' סה."],["737","62","<b>ועברתי בארץ מצרים אני ולא מלאך</b>: נסמן לקמן ע' קלז."],["738","63","<b>מ\"ט שע\"ט דמצרים</b>: ראה אוה\"ת שה\"ש ע' רס ואילך. ובכ\"מ."],["739","64","<b>כחשיכה כאורה</b>: תהלים קלט, יב."]]],[2100490196,"שבחי' הרצוא בתשוקה ברשפי אש הנה היא באה דוקא ע\"י בחי' בינה שהוא ההתבוננות כו'. וזהו ענין ואהבת<sup data-n=\"740\">65</sup> בכל נפשך אחר ההתבוננות בפסוק ראשון דק\"ש כידוע. והנה ידוע דיש בחי' רצוא ובחי' שוב. וכמאמר הס\"י<sup data-n=\"741\">66</sup> אם רץ לבך שוב כו' פי' אחרי שרץ לבך בתשוקה לצאת מגדרי בחי' הכלים שבמוחו ולבו וכמ\"ש כלה<sup data-n=\"742\">67</sup> שארי ולבבי כו' אח\"כ מיד שוב כו' ובמה ישוב לאחור להיות חפץ בחיים הנה זה ידוע שאין בחי' שוב אחר הרצוא אלא בתורה והוא במה שידבר דבר<sup data-n=\"743\">68</sup> ה' זו הלכה כמ\"ש ודברי<sup data-n=\"744\">69</sup> אשר שמתי בפיך דברי ממש. ובפיך הוא שורה וא\"צ רק שיהי' בחי' כלי לדבור זה. וכמ\"ש אשר שמתי בפיך. וכידוע ע\"ד ענין לימוד משניות שלמד הרב הב\"י באמרו לו המגיד אני<sup data-n=\"745\">70</sup> המשנה המדברת בפיך כו'. שזהו מפני בחי' ביטול עצמותו מכל וכל אינו מסך מבדיל להסתיר אור אלקי שבדבר ה' זו הלכה והמשנה שמדברת בפיו כו' ואינו אלא רק בחי' כלי לדבר ה' כו' וכידוע. והוא עיקר בחי' השוב. והנה עד\"מ העומד לפני המלך שנסוג אחור מפני האימה ומתבטל ממציאותו לגמרי זהו בחי' בטול אמיתי כידוע והוא משל להבין בחי' גבורות דאבא. דהנה בחי' אור אבא הוא בחי' כח מה וכמ\"ש משה ונחנו<sup data-n=\"746\">71</sup> מה, מה ממש כו' וזהו מצד בחי' הקירוב שהוא בחי' הראיה כידוע והיינו הטעם שאמרו<sup data-n=\"747\">72</sup> במדרש והאיש משה עניו מכל האדם כו' יכול אפי' ממלאכי השרת ת\"ל מכל האדם כו' ולא ממלאכים כו'. לפי שהמלאכים אין להם חומר גופני כ\"כ והם בבחי' הראיה מקרוב יותר ע\"כ בחי' ביטולם יותר אמיתי עד שמשתחוים ממש. וכמ\"ש וצבא<sup data-n=\"748\">73</sup> השמים לך משתחוים משא\"כ בנשמות גם נשמת צדיק כמשה כאשר הי' בגופו לא הגיע מצד גופו לבחי' הביטול של המלאכים עד שאמרו שהמלאכים הם ענוים יותר ממנו ואע\"פ שבמשה נאמר עניו מכל האדם כו' וכ\"ז מפני בחי' הראיה שהוא מקרוב ע\"כ מזה באה סיבת הענוה כי הוא נסוג אחור מחמת זה מרחוק ועומד בשפלות גדולה כו'. וא\"כ בנשמת משה מצד עצמה שהי' בבחי' מ\"ה שבחכמה וכמ\"ש ונחנו מה. והוא בחי' הראיה שבחכמה. וכמ\"ש וירא<sup data-n=\"749\">74</sup> ראשית לו זה משה כו'. בודאי בחי' הענוה שלו גדולה מהכל. כי כל העומד יותר מקרוב יותר יהיה בו בחי' הביטול האמיתי וזהו\"ע בחי' גבורות דאבא פי' גבורות הוא בחי' קו השמאל שיש באור אבא וידוע דבחי' שמאל דוחה כו' והיינו שע\"י הראי' דחכ' מקרוב יתעורר בחי' קו השמאל להיות דוחה ומשפיל א\"ע למטה מטה בענוה ושפלות גדולה. וכל שהוא בבחי' ראיה דחכ' יותר ידחה א\"ע בשמאל דוחה למטה כנ\"ל וד\"ל.\n<b>והנה</b> מבחי' גבורות דאבא הנ\"ל שנעשה בחי' חסדים דאימא הענין הוא דעיקר הטעם ששמאל דוחה א\"ע בענוה גדולה מאד עד שנסוג אחור ועומד מרחוק",[["740","65","<b>ואהבת בכל נפשך</b>: ואתחנן ו, ה."],["741","66","<b>הס\"י אם רץ לבך שוב</b>: ס\"י פ\"א, מ\"ח."],["742","67","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["743","68","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["744","69","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["745","70","<b>אני המשנה המדברת בפיך</b>: ראה מגיד משרים פ' ויחי, בא, תשא, ועוד [ירושלים תש\"ך מה, ב. נג, ב. סט, ב]. שע\"ת פ, ג. ובהערה 26."],["746","71","<b>ונחנו מה</b>: בשלח טז, ז. ח."],["747","72","<b>שאמרו במדרש והאיש משה עניו מכל האדם יכול אפי' ממלאכי השרת</b>: בהעלותך יב, ג. נסמן לקמן ע' קצד."],["748","73","<b>וצבא השמים לך משתחווים</b>: נחמי' ט, ו. וראה תו\"ח בראשית א, ג."],["749","74","<b>וירא ראשית לו זה משה</b>: ברכה לג, כא. וראה מאמרי אדה\"ז תקס\"ח ע' תרמז."]]],[2100490197,"כו' וזהו שנא' בחכ' דוקא ובפרט במשה דכתיב ותתצב<sup data-n=\"750\">75</sup> אחותו מרחוק וידוע דאחותו בחי' חכמה כמ\"ש אמור לחכמה אחותי כו'. וכן שלמה ע\"ה אמר אמרתי<sup data-n=\"751\">76</sup> אחכמה והיא רחוקה ממני. והיינו מפני שהחכ' להיותה בבחי' הקירוב יותר לעצמות אור א\"ס כידוע דאין<sup data-n=\"752\">77</sup> התלבשות אוא\"ס אלא בחכ' דייקא ע\"כ אמר והיא רחוקה ממני להיות כי בחינת השמאל דוחה ונעשה רחוק ממנה וכמ\"ש מרחוק<sup data-n=\"753\">78</sup> ה' נראה לי כו' וד\"ל. ולהיות כן הרי אחר כשנסוג אחור ועומד מרחוק דוקא אזי נהפך הוא שמתיישב עליו דעתו ויוכל לבוא לבחי' שוב הנ\"ל בדבר ה' זה הלכה כו' וכנ\"ל שהוא בחי' חסדים דאימא כנ\"ל. והרי מזה יובן שמבחי' גבורות דאבא דוקא שעמד מרחוק כנ\"ל הוא שנעשה מזה בחי' חסדים דאימא בבחי' המשכות האורות בריבוי הכלים מכלים שונים כידוע וד\"ל.\n<b>ועם</b> כל זה יובן גם כאן בענין המאמר הנ\"ל דשינה דוד בדיחי דמלכא מלוים לכהנים כו' דהנה הכהנים שרשם האמיתי הוא בבחי' נצח דאבא כמ\"ש למעלה ובחי' קו השמאל דאבא הוא בהוד דאבא ומשם הוא בחי' שמאל דוחה הנ\"ל לעמוד מרחוק וכמ\"ש מרחוק ה' נראה לי וכנ\"ל ואמנם לכל בחי' גבורות יש ענין המתקה גם לבחי' גבורות דאבא. ע\"כ זאת היתה עבודת הכהנים באותה השעה שימתיקו גבורות דאבא להיות מזה בחי' חסדים דאימא בבחי' גילוי האור בכלים רבים כנ\"ל. וענין ההמתקה שלהם הי' בדרך העבודה של הלוים דוקא דהיינו בניגון ושיר על היין וכיוצא כדי שיהי' עי\"ז בחי' גילוי מן ההעלם כנ\"ל שבדרך זה דוקא יהי' גילוי מן ההעלם. אך בחי' גילוי אור שע\"י שיר הכהנים הי' מבחי' ההעלם היותר עליון מטעם שהמשיכו מבחי' אוא\"ס שבאור אבא שהוא יותר גבוה מטעם שאין גילוי אור א\"ס אלא בחכמה והמתקת הגבורות שלהם הי' שלא יהי' בחי' שמאל דוחה מלמעלה כו' אלא יעמדו מקרוב בבחי' הראיה. וכמ\"ש עין<sup data-n=\"754\">79</sup> בעין נראה אתה ה' כו'. ולמטה נעשה מזה ריבוי הכלים כו' וד\"ל. ובכ\"ז מתורצי' כל הקושיות הנ\"ל איך יהיה מיתוק הגבורות בכהנים כו' ולמה יחליפו עבודתם כו' כי צריך הי' דוד דוקא באותה השעה בשביל המשכת גילוי אוא\"ס כמו שהוא ואינו שורה אלא בחכ' דוקא וע\"כ אמר וחסידיך<sup data-n=\"755\">80</sup> ירננו להביא מן ההעלם לגילוי ולהמתיק בחי' גבורות דאבא וכנ\"ל וד\"ל.\n<b>ואמנם</b> בזאת עוד היה יתרון מעלת שיר הכהנים משיר הלוי' באותה שעה במה שהי' הניגונים שלהם בקול בלבד בלא צירופי אותיות הדיבור משא\"כ הלוים שמצותם בסדרי שיר במזמורי תהלים דוקא כידוע. ומ\"ש וחסידיך ירננו ר\"ל בקולות ניגונים בלא מזמורי תהלים כלל. ולהבין שורש טעם הדברים הללו הנה גם במשה כתיב והאלקים<sup data-n=\"756\">81</sup> יעננו בקול וארז\"ל בקולו<sup data-n=\"757\">82</sup> של משה כו' הענין הי' ג\"כ בקול",[["750","75","<b>ותתצב אחותו מרחוק</b>: שמות ב, ד."],["751","76","<b>אמרתי אחכמה והיא רחוקה ממנו</b>: קהלת ז, כג."],["752","77","<b>דאין התלבשות אוא\"ס אלא בחכ'</b>: ראה תניא פל\"ה בהגה\"ה."],["753","78","<b>מרחוק ה' נראה לי</b>: ירמי' לא, ב."],["754","79","<b>עין בעין נראה</b>: במדבר יד, יד."],["755","80","<b>וחסידיך ירננו</b>: תהלים קלב, ט."],["756","81","<b>והאלקים יעננו בקול</b>: יתרו יט, יט."],["757","82","<b>בקולו של משה</b>: ברכות מה, א."]]],[2100490198,"ניגון פשוט מבלתי דיבור בצירופי אותיות כלל וזהו בקולו של משה בלא דיבור כו'. והטעם לכל זה הנה יובן בהקדים כלל א' שבבחי' פנימי' החכ' הוא למעלה מבחי' הדיבור וכמו במשה דמשום שהי' מבחי' מ\"ה שבחכ' כנ\"ל ע\"כ היה כבד<sup data-n=\"758\">83</sup> פה כו' מפני שלא הי' יכול להתצמצם אורו בבחי' כלי כמו כלי הדיבור וכמ\"ש<sup data-n=\"759\">84</sup> במ\"א. משא\"כ בחי' בינה שהוא כבר בחי' השגה במח' הוא באה דוקא לבחי' צירופי אותיות גם בדיבור וכמ\"ש<sup data-n=\"760\">85</sup> במ\"א בענין פתוחי חותם דאימא כו'. ולזה הטעם הנה גם בענין הניגון שהוא בבחי' רו\"ש כנ\"ל דלכך הוא ממתיק הגבורות להיות הגילוי מן ההעלם כנ\"ל ג\"כ יש הפרש זה בין חכמה לבינה שניגון הממתיק בחי' גבורות דאבא הוא למעלה מצירופי אותיות בדבור אלא הענין של הניגון הוא רק בכוונה במחשבה כמו שיחשוב אדם איזה ניגון במחשבה בלבד שאינו אלא מכוון לכוונות תנועות הניגון להיכן הוא רומז כו' וכן גם בהיותו מרנן בקול אם אינו בצרופי אותיות אלא בקולות ותנועות הניגון בלבד הכל הוא עדיין רק בבחי' הכוונה שבמחשבה בלבד. והוא כענין הכוונה הפנימי' שמושג לחכם בעמקות החכמה עד שלא יוכל להביאה בדיבור רק ברמז וכמאמר די<sup data-n=\"761\">86</sup> לחכימא ברמיזא כו' והוא מפני שפנימי' השכל לא יוכל להתצמצם בדיבור כנ\"ל במשה שהי' כבד פה כו'. וכך היה ענין הניגון והשיר שהיו הכהנים מרננים בשעה שאמר דוד קומה ה' למנוחתיך כו' וכמ\"ש וחסידיך ירננו כו' דהיינו בקולות בלתי צירופי אותיות הדיבור במזמורים. אבל שיר שהלוים מנגנים אומרים מזמורים דוקא כידוע במשנה בשיר שהלוים היו אומרים בכל יום כו'. לפי ששרשם רק מבחי' בינה כנ\"ל ומיתוק הגבורות שלהם בניגון הי' להמתיק גבורות דאימא כנ\"ל באריכות ולכך היה השיר שלהם דוקא בדיבור כי שורש אותיות הדיבור הוא נמשך מצירופי אותיות שבהתבוננות ההשגה המורגשת משא\"כ בחכמה שלמעלה מן צירופי אותיות וכמ\"ש במ\"א וד\"ל.\n<b>ועתה</b> אחר כל הנ\"ל יתבארו פרטי דברי המאמר הנ\"ל. אי אורחי' דמלכא דחדאן ליה בדיחי הדיוטא יסדר קמיה בדיחי רופינוס ופרדשכי כו'. פי' בדיחי הדיוטא הן מדרגת הלוים משום דשרשם מבינה כנ\"ל. ורופינוס כו' הן השרים. כי החכמה בחי' שר לבינה. וכמ\"ש ר\"ג<sup data-n=\"762\">87</sup> אני כשר לפני המלך מפני ששורש<sup data-n=\"763\">88</sup> נשמתו היה בחכמה שבתורה כו' וכמ\"ש במ\"א ושינוי הסדר הוא משום מאן דמזמין למלכא ישנה עובדוהי בגין למיהב חדוה למלכא כו' ר\"ל משום דההזמנה לבית עבד המלך מבית המלך עצמו זה ירידה גדולה וצריך שיעוררו לו חדוה עד שיתגלה חוץ לגדר",[["758","83","<b>כבד פה</b>: שמות ד, י."],["759","84","<b>וכמ\"ש במ\"א</b>: ראה תו\"א ויחי נ, ב. נב, ב. ובכ\"מ."],["760","85","<b>וכמ\"ש במ\"א בענין פתוחי חותם דאימא</b>: ראה מאו\"א מערכת חותם אות סח. פע\"ח (שער ספה\"ע) שכ\"ב פ\"ג. לקו\"ת אמור לו, א. תו\"ח תצוה [הוצאת קה\"ת — תשס\"ג] שנט, ג."],["761","86","<b>די לחכימא ברמיזא</b>: ראה רשב\"ם בראשית כג, טז. מדרש משלי כב, טו. זהר בראשית כו, ב."],["762","87","<b>ר\"ג אני כשר לפני המלך</b>: ראה ברכות לד, סע\"ב."],["763","88","<b>ששורש נשמתו היה בחכמה שבתורה כו' וכמ\"ש במ\"א</b>: וראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשטו ואילך. תקס\"ה ח\"א ע' קלא. תו\"ח וישב רב, ב. שמות יא, ב. ובכ\"מ."]]],[2100490199,"מדריגת רוממותו כנ\"ל. ולעצם גילוי כזה צריך שיהא שינו סדר בדיחי דמלכא שיהיו מן השרים החשובים יותר ומטעם הנ\"ל וד\"ל.\n<b>וכך</b> הוא מבאר הנמשל: ת\"ח דוד שינה בגין רופינוס כמ\"ש וחסידיך ירננו לוויך מיבעי' ליה אלא השתא בגין דזמין לנייחא עביד כהני וחסידי אינון דחשיבי יתיר אע\"ג דלאו אורחייהו בהאי ע\"כ.\n<b>פי'</b> השתא דוקא משום דזמין לנייחא כו' וכמ\"ש בתחלת המאמר קומה ה' כו' כמאן דאמר יקום מלכא לבי נייחא דמשכני' כו' ופי' נייחא מבואר למעלה. אך עיקר הענין הוא בכלל שיהא גילוי אוא\"ס בחכמה דוקא וזהו שאמר קומה ה' למנוחתיך כו' שאז ממילא נמשך בחי' הביטול בכל ההשתלשלות ולא בדרך מלחמה כלל כנ\"ל. ומשום דזמין ליה לנייחא לכך בנה הבית מאבנים שהוא בחי' דומם בלבד. לפי שידוע דארמ\"ע<sup data-n=\"764\">89</sup> שהן דצח\"ם יש בכל עולם ועולם וגם באצי' יש דצח\"מ. ובחי' הדומם דאצי' נק' עשיה שבאצי'. ולפ\"ע גם מה שבעולם הבריאה נחשב בחי' מדבר לגבי עולם האצי' אינו אלא בחי' דומם כי בחי' מל'<sup data-n=\"765\">90</sup> שבעליון נעשה כתר לתחתון. וזהו שאמר בפ' זו ויקח<sup data-n=\"766\">91</sup> מאבני המקום שהוא בחי' אבן שבאצי' שנק' מקום וישם מראשותיו שנעשה לו לבחי' עטרה וכתר (לבוא לבחי' התחלקות המוחין מאחורי ראשו כו') וכידוע דגם בחי' הארה אלקי' שמאיר בבריאה נק' בשם עפר בלבד. וכמ\"ש מקימי<sup data-n=\"767\">92</sup> מעפר דל כו' ונקרא עפר<sup data-n=\"768\">93</sup> אשר בקרקע המשכן כו'. והנה ידוע דאבא<sup data-n=\"769\">94</sup> יסד ברתא דוקא ופי' יסד הוא שהדיבור יהי' בבחי' קביעות יסוד ולא באקראי בעלמא שהוא הנק' מנוחה ג\"כ והיינו דזמין ליה לנייחא כו' משום דאוא\"ס שורה בחכמה ואבא יסד ברתא היינו בחי' אותיות שנק' אבנים בס\"י. וכתיב ה'<sup data-n=\"770\">95</sup> בחכמה יסד ארץ, ארץ דוקא דהיינו בחי' אותיות וכמ\"ש ויקח מאבני המקום כו' וכדי שיהי' בחינת היסוד של האותיות הוא מאור אבא דוקא משא\"כ גוף האותיות שרשם מבינה כנ\"ל וכמ\"ש במ\"א. ולכך שינה ועביד כהני וחסידי אינון דחשיבי יתיר דהיינו מאור אבא מטעם שהי' צריך להמשיך מא\"ס להיות בבחי' היסוד של בנין אבנים ועפר. וזהו שאמר השתא בגין דזמין לנייחא עבד כהני וכו' וד\"ל.\n<b>והשיב</b> לו הקב\"ה לדוד חייך אפי' במאנין דילי לא אשתמש אלא במאנין דילך כו'. הנה פי' מאנין הם בחי' הכלים לאורות. ופי' מאנין דילי היינו בחי' הכלים דאצי' שנק' מאנין דילי. ומשום דאיהו וחיוהי וגרמוהי חד בבחי' אצי' כידוע. וביאור הדברים הנה ענין ובחי' הכלי ידוע שהוא בחי' גבול וצמצום להגביל ולצמצם את האור. עד\"מ בחי' הכלי באדם כמו כלי המוח לאור כח השכל שהמוח מגביל ומצמצם כח ואור השכלי עד שאינו מתפשט רק בהגבלה בכל חד וחד לפום שיעורא",[["764","89","<b>ארמ\"ע שהן דצח\"מ</b>: נסמן לקמן ע' קלו, קנט."],["765","90","<b>מל' שבעליון נעשה כתר לתחתון</b>: ראה ע\"ח (שער כסא הכבוד) שמ\"ו פ\"ב. פ\"ה. שעה\"י קטז, ב הערה 25."],["766","91","<b>ויקח מאבני המקום</b>: ויצא כח, יא."],["767","92","<b>מקימי מעפר דל</b>: תהלים קיג, ז."],["768","93","<b>עפר אשר בקרקע המשכן</b>: נשא ה, יז."],["769","94","<b>דאבא יסד ברתא</b>: ראה זהר (רעיא מהימנא) פינחס רנו, ב. רמח, א. רנח, א."],["770","95","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."]]],[2100490200,"דילי' כו' ואמנם למעלה בבחי' האצי' א\"א לומר ע\"ד משל זה ממש שהכלי יגביל ממש את האור שהרי הכל שם בבחי' אלקות חיוהי וגרמוהי שהן האורות והכלים וכמאמר הנ\"ל דאיהו וחיוהי וגרמוהי חד כו' אלא הענין שם כך הוא דאותו כח המגביל האור אינו בבחי' גבול ממש שאלו הוא בבחי' גבול ממש הרי אינו בבחי' אלקות שהוא בלתי בע\"ג כידוע. אלא אותו הכח הוא ג\"כ בחי' כח אלקי ממש והוא שמגביל האור. ואמנם לכאורה יפלא איך ימצא מציאת כח זה להגביל מאוא\"ס שהוא בבע\"ג בעצם כו'. אבל הענין הוא משום דבאמת מאחר שנק' אוא\"ס הרי הוא כל יכול שביכולתו כל מה שיכול להיות וגם מציאות כח הגבול ממנו ימצא ואם לא הי' באפשרי להימצא אינו כל יכול ח\"ו. ואמנם אחר שביכולתו הוא להמציא היפוכו אין זה המציאות ענין נפרד ח\"ו מעצמותו דהרי מ\"מ אוא\"ס הוא אלא שהוא כל יכול להמציא גם בחי' הגבול והכל ממנו. וע\"כ נק' בחי' הכח הזה שבבחי' אצי' להגביל האור ג\"כ בבחי' אלקות ממש עד שאמר דאיהו וחיוהי וגרמוהי חד כו' מטעם זה וד\"ל. ולזה הטעם ימצא ג\"כ מאתו הרבה הפכיים יחד כמו חו\"ג חסד התפשטות וגבורה צמצום מפני שהוא כל יכול וכוללם יחד ואינם תרתי דסתרי כלל לגביו כו' וכמ\"ש במ\"א. והנה כ\"ז הוא בבחי' האצי' דוקא. אבל בעולם הבריאה דכתיב ומשם<sup data-n=\"771\">96</sup> יפרד כו' הרי שם נמצאו ושם נתהוו הנבראי' יש מאין בבחי' הפירוד דהיינו בבחי' הגבול ממש כמו מלאכים דבריאה ודיצירה שיש להם קצבה ומדידה בבחי' חומר שלהם עד שהוא רק מהלך<sup data-n=\"772\">97</sup> ת\"ק שנה וכדומה. וגם בבחי' הצורה שלהם אף שהוא רוחני וכמ\"ש הרמב\"ן<sup data-n=\"773\">98</sup> שכל מלאך יש לו חומר וצורה החומר מן יסוד האש הרוחני וכמ\"ש משרתיו אש לוהט והצורה מבחי' הרוח כמ\"ש עושה<sup data-n=\"774\">99</sup> מלאכיו רוחות כו' גם לצורה שלו יש גבול ממש כידוע. ויש לו נר\"נ ג\"כ. אך הנה דרך כלל ידוע בספרי הקבלה דגם בי\"ס דעולם הבריאה יש מבחי' אלקות עדיין ולא מבחי' נברא והוא להיות כי יש ה' מדריגות בי\"ס דבריאה דהן נרנח\"י שבכל עולם כו'. ובחי' נשמה חי' יחידה עדיין נחשב מבחי' האלקות אבל בחי' נפש ורוח הן מבחי' נברא ממש ודרך כלל נק' בחי' הכלים די\"ס דבי\"ע בבחי' נברא להיותם נפש ורוח בלבד. אבל בחי' האורות שבהם הוא מבחי' נשמה חי' יחידה ונחשבי' עדיין מבחי' אלקות כמו בבחי' האצי' כו'. וכמו שמבואר למעלה גם בעולם האצי' יש עד\"ז בחי' אורות ובחי' הכלים. אלא שבחי' הכלים דאצי' הם מיוחדים בתכלית בבחי' היחוד כנ\"ל מטעם דאיהו וגרמוהי חד כו'. ונק' מאנין דילי. וגם הארה האלקי' שבבריאה שהוא נח\"י בכלל כנ\"ל ג\"כ עדיין מאנין דילי אבל בחי' נפש ורוח שבבריאה רק מאנין דילך כלומר להיותם בחי' הכלים די\"ס דבריאה בלבד שמהן מציאת הגבול ממש כנ\"ל.\n<b>והיינו</b> ג\"כ פי' ויקח מאבני המקום בדרך אחר שהן י\"ב בקר הנק' י\"ב אבנים שהן לד' סטרי עלמא כו' כמ\"ש בפ' זו בהתחלת המאמר הנ\"ל והן י\"ב גבולי",[["771","96","<b>ומשם יפרד</b>: בראשית ב, י."],["772","97","<b>מהלך ת\"ק שנה</b>: חגיגה יג, א."],["773","98","<b>וכמ\"ש הרמב\"ן שכל מלאך יש לו חומר וצורה</b>: ראה סידור שער החנוכה ערה, ד בשם ספר הגמול להרמב\"ן והנסמן במאמרי אדה\"א בראשית ע' קיב."],["774","99","<b>עושה מלאכיו רוחות</b>: תהלים קד, ז."]]],[2100490201,"אלכסון כו'. והים עומד עליהם מלמעלה היינו בחי' מל' דאצילות שנק' ים כידוע ונק' ג\"כ בשם אבן ועפר כמ\"ש עפר אשר בקרקע המשכן כו' וכמו שמבואר למעלה ע\"פ זה שהוא אבן בבחי' אצילות כך יתפרש ענין אבני המקום בבחי' נפש ורוח שהן בחי' המרכבה דפני<sup data-n=\"775\">100</sup> ארי' ופני נשר כו' שבעולם הבריאה הנושאת את כסא הכבוד כידוע שהן נבראים ממש וד\"ל. וזהו שהבטיחו לו חייך אפי' במאנין דילי לא אשתמש שהן בחי' אבן. והוא רק בחי' הדומם דאצי' אלא רק במאנין דילך הן בחי' הדומם והוא בחי' האבן שבעולם הבריאה כנ\"ל. ואע\"פ שהן בבחי' הפירוד ממש אבל להיות שכבר המשיך דוד בשיר של הכהנים שיהא גילוי אוא\"ס בבחי' מנוחה כו' וכנ\"ל דהיינו עד שלא יהא מסתיר שום הסתר וכמ\"ש גם חושך לא יחשיך כו' משום דקמי' כחשיכה כאורה כו' וא\"כ גם בבחי' מאנין דילך אין שם בחי' פירוד כלל וכלל כנ\"ל. ואדרבה הבטיח לו עוד שיניח מלהשתמש במאנין שלו וישתמש במאנין דילי' דוקא והוא מטעם הנ\"ל שכל היותר גבוה יותר ישפיל א\"ע וכענין אבא יסד ברתא דוקא כו'. וא\"כ צריך להיות עיקר בחי' הגילוי אור בירידת המדריגה דוקא עד שגם באותו מאנין דבחי' האצי' לא ישתמש בהם כי אין שם גילוי אור א\"ס כ\"כ כו' וד\"ל. ולפ\"ז יובן מה שאנו מוצאים בבנין בהמ\"ק הגם שהי' שם גילוי אוא\"ס כ\"כ כנ\"ל ובאכילת הקרבנות ע\"ג המזבח הי' יורד רק מבחי' מלאך נברא בלבד כמו בחי' ארי'<sup data-n=\"776\">101</sup> דאכיל קורבנין שהוא מבחי' פני ארי' להימין וכמ\"ש בזוהר. וכן גם בכל פרטי הקרבנות כמו בתורים ובני יונה הי' יורד מבחי' פני נשר כו' ובבהמות וכבשים הי' יורד מבחי' פני שור כו'. לפי שהבטיחו לו שלא ישתמש אלא במאנין דילי' כו' כנ\"ל דהיינו בחי' פני ארי' פני שור פני נשר שלמעלה בבחי' מרכבה שתחת כסא הכבוד כנ\"ל וד\"ל.\n&lt;עב&gt;",[["775","100","<b>דפני ארי' ופני נשר</b>: יחזקאל פי\"א."],["776","101","<b>ארי' דאכיל קורבנין</b>: ראה יומא כא, ב. זח\"א ו, ב. זח\"ב רעח, א. זח\"ג יז, א. לב, ב. ועוד."]]],[2100490202,"<h3>נוסח שני: בזוהר פ' ויצא ע\"פ ויקח מאבני המקום</h3>\n<b></b><b>בעזה\"י, ליל ש\"ק פ' ויצא (ביאור מאמר הזהר הזה)</b>\n<b>בזוהר</b><sup data-n=\"777\">1</sup> (פ' ויצא ד' קמ\"ז ע\"ב עד ד' קמ\"ח ע\"ב ע\"ש) ויפגע במקום ההוא וגו' ויקח מאבני המקום כו' עד פתח ההוא בר נש קומה ה' למנוחתיך אתה וארון עוזך כו' תרין אינון דאמרו קומה ה' משה ודוד משה אמר קומה ה' ויפוצו אויביך כו' משה פקיד לי' לאגחא קרבא לקבל שנאוי ודוד זמין לי' לנייחא כמאן דמזמין למארי' כו' כהניך ילבשו צדק וחסידיך ירננו מכאן אוליפנאן דמאן דמזמן למלכא ישנה עובדוי בגין למיהב חדוה למלכא אי אורחא דמלכא דחדאן לי' בדיחא הדיוטי יסדר קמי' בדיחי רופינוס ופרדשכי, ת\"ח דוד זמין לי' למלכא ומטרוניתא שני בדיחי דמלכא כו' ומאן נינהו דכתי' כהניך ילבשו צדק וחסידיך ירננו ולויך ירננו מבעי' לי'",[["777","1","<b>בזוהר (פ' ויצא ד' קמ\"ז. . ויפגע במקום</b>: הנחות ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (רד, ב). הנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נדפס לעיל ע' קטו. ובביאוה\"ז מכ\"ק אדמו\"ר הצ\"צ ח\"א ע' קא נדפס קיצור והגהות על מאמר זה."]]],[2100490203,"דהא לואי אינון בדיחי מלכא והשתא דוד עביד כהני וחסידי דלהוי אינון בדיחי מלכא א\"ל קוב\"ה דוד לאו הכי א\"ל דוד מארי כד אנת בהיכלך אנת עביד רעותך השתא דזמיננא לך ברעותי קיימא מלה לאקרבא אינון דחשיבי יתיר אע\"ג דלאו ארחייהו בהאי כו' אמר דוד בעבור דוד עבדך אל תשב פני משיחך סדורא דקא סדרנא לא יתוב לאחורא א\"ל קב\"ה דוד חייך אפי' במאנין דילי לא אשתמש אלא במאנין דילך ולא זז קב\"ה מתמן עד דיהיב לי' נבזבזן ומתנן כו' ע\"ש בארוכה. עכ\"ל הזה\"ק.\n<b>וביאור</b> הענין כתי' כי<sup data-n=\"778\">2</sup> לא באתם עד עתה אל המנוחה ואל הנחלה ודרשו רז\"ל מנוחה<sup data-n=\"779\">3</sup> זו ביהמ\"ק ונחלה זו בית עולמים כו', וכדכתי' ואתהלך<sup data-n=\"780\">4</sup> באהל ובמשכן כו' והיינו שכל משך הזמן דמסעו' בני ישראל ארבעים שנה במדבר לא הי' עדיין בחי' מנוחה ושלימות כ\"א הי' אז עיקר זמן המלחמה באויבי ה' המה החצוני' והקליפות להכניעם שלכך הסב ה' אותם דרך המדב\"ר ששם מדור הקליפות והחצוני' בכדי שיכניעו בני ישראל אותם שיתגבר סטרא דקדושה על הסט\"א והיינו ע\"י מ\"ב מסעו' שנסעו במדבר נלחמו בהם ונצחום להכניעם תחת סט' דקדושה וז\"ש משה קומה<sup data-n=\"781\">5</sup> ה' ויפוצו אויביך וגו' כי ה'<sup data-n=\"782\">6</sup> איש מלחמה כתיב לאגחא קרבא לקביל שנאוי כנ\"ל בזוהר, שכ\"ז הי' בזמן המסעו' במדב\"ר ששם מדור הקליפו' שאז הי' עת מלחמה לאגחא קרבא בהון ולהכניעם. והגם שלגבי המאציל ית' כלא<sup data-n=\"783\">7</sup> קמיה כלא חשיבי וכאין ואפס נחשבו בלי תפיסת מקום כלל ואיך יתכן לגבי' ב\"ה בחי' המלחמה באויבי ה' שמי יעמוד נגדו ית'. אך באמת לגבי' ית' כלא חשיבי אך מי פעל ועשה כל זאת בחי' התגברו' הסט\"א והחצוני' הוא ע\"י מעשה ישראל כשאין<sup data-n=\"784\">8</sup> עושים רש\"מ שאז ממשיכין עי\"ז לתת כח יתירה בהחיצונים שינקו מצד הקדושה יותר מכדי צרכם ולזאת מצטרכים ישראל לתקן המעוות להמשיך תוספ' גילוי מאור א\"ס ב\"ה ללחום מלחמות כו' ויפוצו אויביו מפניו ית' ולהכניעם מצד הקדושה כדכתיב ולאום<sup data-n=\"785\">9</sup> מלאום יאמץ &lt;עג&gt;\nוגו' כנודע וז\"ש משה רבע\"ה קומה ה' ויפוצו אויביך וינוסו משנאיך מפניך להמשיך בחי' גילוי כבודו ית' עליהם להכניעם כנ\"ל, ולזאת לא באתם עד עתה אל המנוחה שאין זה בחי' מנוח\"ה ושלימות כאשר עדיין שעת קרב\"א להנקם מאויביהם וללחום בהם כנ\"ל וכן אף במשכן שילה לא הי' עדיין בחי' מנוחה ושלימות כ\"א שעת קרב\"א כנ\"ל ולכך נאמר ואתהלך באה\"ל ובמשכן שאז לא הי' עדיין בחי' מנוחה ושלימות, זולתי ביומי דשלמה מלכא קיימא<sup data-n=\"786\">10</sup> סיהרא באשלמותא ואז הי' עיקר המנוחה כאשר נעשה מכון לשבתו ית' לשבת בית וכדכתיב האתה<sup data-n=\"787\">11</sup> תבנה לי",[["778","2","<b>כי לא באתם עד עתה אל המנורה</b>: פ' ראה יב, ט."],["779","3","<b>מנוחה זו ביהמ\"ק</b>: ראה מגילה י, א."],["780","4","<b>ואתהלך באהל ובמשכן</b>: ראה שמואל-ב ז, ו ”ואהיה מתהלך באהל ובמשכן\"."],["781","5","<b>קומה ה'</b>: נשא י, לה."],["782","6","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["783","7","<b>כלא קמיה כלא חשיבי</b>: ראה זח\"א יא, ב."],["784","8","<b>כשאין עושים רש\"מ</b>: ראה ברכות לה, ב."],["785","9","<b>ולאום מלאום יאמץ</b>: תולדות כה, כג."],["786","10","<b>קיימא סיהרא באשלמותא</b>: ראה זהר ויצא קנ, א. וראה הנסמן במאמרי אדה\"ז פרשיות התורה ע' תקפט."],["787","11","<b>האתה תבנה לי בית לשמי</b>: שמואל-ב ז, ה (לשבתי)."]]],[2100490204,"בית לשמי כי לא ישבתי בבית וגו' וכתיב ויהי<sup data-n=\"788\">12</sup> עלי דבר ה' לאמר דם לרוב שפכת וגו' הנה<sup data-n=\"789\">13</sup> בן נולד לך הוא יהי' איש מנוחה והניחותי לו מכל אויביו מסביב כי שלמה יהי' שמו ושלום ושקט אתן על ישראל הוא יבנה בית לשמי וגו' וזהו כי לא באתם עד עתה אל המנוחה כדרש רז\"ל זו בהמ\"ק ואל הנחלה זו בית עולמים כי באמת אף ביומי דשלמה מלכא לא הי' עיקר תכלית השלימות (כמ\"ש על<sup data-n=\"790\">14</sup> אפי ועל חמתי על העיר הזאת מיום כו') זולתי לע\"ל כשיבא משיח בן דוד ב\"ב אז יהי' עיקר תכלית השלימות של המנוחה שיבולע<sup data-n=\"791\">15</sup> המות לנצח ואת<sup data-n=\"792\">16</sup> רוח הטומאה יעבור מן הארץ וגו' לכך ארז\"ל נחלה זו בית עולמי' אך לגבי האהל ומשכן שהי' במדבר ובשילה נק' בנין בהמ\"ק של שלמה בחי' מנוח\"ה ושלימות כמ\"ש ושלום ושקט אתן לו וגו' כנ\"ל.\n<b>והענין</b> שבחי' המנוחה והשלו\"ם הוא כשנתייחדו הע\"ס דתיקון דאצי' ע\"י המשכת תוספ' גילוי מאור אין סוף ב\"ה עד שנתבטלו ונתכללו כאחד, אז ממילא נכנעי' כל החצוני' אויבי ה' בלי שום התגרו' מלחמה זולתי מצד תוספ' גילוי של אור א\"ס ב\"ה שמתבטלי' מפניו ית' כביטול הנר בפני האבוקה ממש והיינו בחי' השלום בפמליא שלמעלה ששלו\"ם הוא בחי' התחברות ב' הפכים ביחד והיינו ע\"י תוספ' גילוי מעצמו' אור א\"ס שלמעלה משניהם שע\"י נעשה שלום ביניהם להתבטל ולהכלל שניהם כא' כמארז\"ל ע\"פ<sup data-n=\"793\">17</sup> עושה שלום במרומיו בין מיכאל וגבריאל שמיכאל הוא בחי' מי\"ם שנמשך ממדת החסד דאצי' דכמו שהמים<sup data-n=\"794\">18</sup> יורדין ממקום גבוה למקום נמוך כך טבע החסד להטיב ולהשפיע השפע ממקום גבוה למקום נמוך למטה וגבריאל הוא בחי' אש שנמשך ממדת הגבורה דאצי' שהוא בחי' רצוא והסתלקותו מלמטה למעלה והקב\"ה עושה שלום ביניהם מצד התגלות אור א\"ס ב\"ה בתוספ' ורבוי מאד מעצמותו ית' דלאו בי' מאינון מדות כלל עד שמתבטלי' שניהם שני מדות חו\"ג ההפכיי' ונכללים כאחד לכך אין מים מכבי' אש כו' כמשנ\"ת במ\"א, וזהו ענין המנוחה והשקט שהי' ביומי דשלמה כשהוכן בנין בהמ\"ק שאזי נמשך תוספ' גילוי מעצמו' אור א\"ס ב\"ה עד שנתייחדו כל ע\"ס דתיקון דאצי' כאחד בהתכללות אחת שאזי ממילא נתבטלו החצוני' ונכנעו תחת סט' דקדושה בלי שום התגרו' מלחמה, זולתי כביטול הנר בפני האבוק\"ה הוא האור הגדול דעצמו' אור א\"ס ב\"ה שנתגלה בתוס' גילוי ורבוי מאד וזהו ושלו\"ם ושקט לו כנ\"ל וד\"ל.\n&lt;עד&gt;\n<b>ב)</b> אך הנה התגלות והשראת האבוקה הוא אור הגדול דאור אין סוף ב\"ה היה על בחי' המזבח החיצון והפנימי שבמקדש דהיינו שע\"י עבודת הקרבנות הי' ממשיכי' גילוי האבוקה הזה לגרום יחוד גדול בהע\"ס דתיקון דאצי' וזהו ע\"י ג' בחי'",[["788","12","<b>ויהי עלי דבר ה' לאמר</b>: דברי הימים-א כב, ח."],["789","13","<b>הנה בן נולד לך. . הוא יבנה בית לשמי</b>: שם, ט-י."],["790","14","<b>על אפי ועל חמתי</b>: ירמי' לב, לא."],["791","15","<b>שיבולע המות לנצח</b>: ישעי' כה, ח."],["792","16","<b>ואת רוח הטומאה יעבור מן הארץ</b>: זכרי' יג, ב (אעביר)."],["793","17","<b>ע\"פ עושה שלום במרומיו</b>: איוב כה, ב. וראה במדבר רבא פי\"ב, ח. מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תרמה ובהנסמן שם."],["794","18","<b>שהמים יורדין ממקום גבוה</b>: ראה תענית ז, א."]]],[2100490205,"ומדרגו' אלו דכהנים לוים וישראלי' שהם ג' קווים דאצי' כהנים נמשכי' מקו ימין דחח\"ן דאצי' שבחי' כהן גדול הוא מבחי' חכמה דאצי' וכהן סתם שהוא כהן הדיוט הוא בחי' חסד ענף החכמה דאצי' ואיש כהן שנ' במקרא הוא בחי' נצח ענף החסד שנסתעף מהחכמה כנ\"ל, ולוים נמשכים מקו שמאל דבג\"ה וישראלים מקו האמצעי דדעת\"י כו' כנודע שע\"י ג' בחי' אלו נעשה היחוד עליון והיינו שעבודת הכהן ברעותא דלבא ובכונה ובעובדא כמ\"ש<sup data-n=\"795\">19</sup> בזהר פי' שעבודת הכהן הוא במעשה הקרבנות להקריב בהמות על המזבח שעי\"ז נמשך תוספת גילוי מעצמו' אור א\"ס שלמעלה מאצי' לעולם האצי' ליחד הספירו' ביחוד אמתי והיינו כי שרש הבהמו' הוא מבחי' עולם התהו שהוא עולם הנקודים שלמעלה מעולם הברודים שהוא עולם האצי' רק שנפלו הניצוצין דתהו דרך שבירה לבי\"ע להתלבש בנוגה דבי\"ע הם כל הבהמות המותרי' ודומיהן ולכך כיון שמתבררי' ע\"י מעשה הקרבנות שנעשה מהן בחי' העלאו' מ\"ן לשרשם בחי' עולם התהו שלמעלה מאצי' להמשיך משם מ\"ד לעולם האצי' לייחד הספירו' דתיקון דאצי', וזהו ענין הזאת הדם של הקרבנות על הפרוכת ועל המזבח כו' או ד' מתנות על ד' קרנו' המזבח כמו שנתפרש חילוקיהן במתניתין שע\"י הזאת הדם של הבהמות ששרשן מתהו שלפני האצי' ימשיכו מ\"ד משרשם לצורך יחוד הספי' דאצי' כנ\"ל וכמ\"ש בכ' אריז\"ל בהזאת פנים דיוה\"כ וכך היה מונה אחת ואחת אח\"ת הוא כת\"ר דאצי' ואחת הוא מל' דאצי' אחת ושתים כו' ע\"ש שנתפרש להדיא ענין מנין הע\"ס דאצי' והיחוד שלהן שנעשה ע\"י הזאה זו כך הוא בכל ההזאות של המזבח ד' מתנות על ד' קרנות כו' שנרמז בזה ענין היחוד דע\"ס דאצי' רק שלא נתפרש להדיא והוא ממילא מובן וד\"ל. וזהו העבודה של הכהן שע\"ז נאמר בזוהר בעובדא וברעותא דלבא ובכוונה הוא כי רוח<sup data-n=\"796\">20</sup> אייתי רוח ואמשיך רוח וכדכתיב אם<sup data-n=\"797\">21</sup> ישים אליו לבו רוחו ונשמתו אליו יאסף וגו' דהיינו שמצטרך להתעורר באתערותא דלתתא ברעותא דלבא באהבה להיות נמשך אחריו כמים שעי\"ז דוקא יעורר למעלה להמשיך מ\"ד כיוצא בו כמ\"ש כמים<sup data-n=\"798\">22</sup> הפנים לפנים כו' וזהו בחי' האהבה שנמשל לכסף נדמה שהיא בקרירות ונחת והיא נמשלה למים ג\"כ נדמה כמו שהמים קרים ונמשכין והולכין בקרירו' ונחת כך האהבה זו של בחי' הכהן שנמשך מקו ימין דחח\"ן דאצי' שנמשך אחריו כמים ברעותא דלבא בקרירו' ונחת, ועי\"ז ימשיך מ\"ד כיוצא מבחי' חסדי' שלמעלה ליחד היחוד דע\"ס דתיקון דאצי', וז\"ש בזוהר בעובדא ובכונה ורעותא דלבא שהעיקר הוא העבודה במעשה הקרבנות ששרש הבהמות הוא מתהו שלפני האצי' ולכך יגיע ההעלא' מ\"ן לשרשם הנעלה להמשיך עצמו' אור א\"ס דתהו לאצי' התיקון ליחד הע\"ס דאצי', רק שזאת מצטרך להיות בכונה ורעותא דלבא הוא בחי' האהבה הנמשלה למים וכסף נדמה של הכהן וכנראה בעליל ששרש<sup data-n=\"799\">23</sup> הבהמות הוא למעלה משרש האדם כי &lt;עה&gt;\nהאדם נמשך מאד\"ם העליון דתיקון דאצי' משא\"כ הבהמו' ששרשן מתהו, ולכך אין<sup data-n=\"800\">24</sup> האדם יוכל",[["795","19","<b>כמ\"ש בזהר</b>: ראה זח\"ג לט, א. וראה אגה\"ק פי\"ח. לקו\"ת ואתחנן ח, ב."],["796","20","<b>רוח אייתי רוח</b>: זח\"ב קסב, ב."],["797","21","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["798","22","<b>כמים הפנים לפנים</b>: משלי כז, יט."],["799","23","<b>ששרש הבהמה הוא למעלה</b>: ראה ג\"כ לקו\"ת אמור לז, ג."],["800","24","<b>אין האדם יכול להתקיים בלעדי אכילת דצ\"ח</b>: ראה לקו\"ת שם — וכמ\"ש באדרא (דקל\"ה סע\"א וע\"ב) בענין עולם התוהו ובגין דתיקונא דא דאדם לא אשתכח לא יכילו למיקם כו' ע\"ש."]]],[2100490206,"להתקיים בלעדי אכילת דצ\"ח כו' הגם שנאמ' כי<sup data-n=\"801\">25</sup> לא על הלחם לבדו יחי' האדם כ\"א על כל מוצא פי ה' יחי' האדם אעפ\"כ שרש<sup data-n=\"802\">26</sup> המוצא והמקור דפי הוי\"ה הוא המאמרות שבהן נבראו דצ\"ח הוא הגב\"ה למעלה משרש פי הוי' הוא המאמר דנעשה<sup data-n=\"803\">27</sup> אדם שזה בתיקון וזה בתהו כנ\"ל וכמ\"ש במ\"א.\nג) <b>והנה</b> עבודת הלוים שנמשכי' מקו שמאל בג\"ה דאצי' הוא לשורר ולזמר בכלי שיר על הקרבן שהם נק' בזוהר בדיחי מלכא, והיינו שבחי' האהבה של בחי' הלוי הוא מבחי' הגבורו' דאצי' שהיא בהתלהבות בגבורו' רשפי אש שלהבת י\"ה (שהיא האהבה כמעלת הזהב על הכסף שנז' בסש\"ב פ' נ' ע\"ש) והיינו דכאשר יתבונן המשכיל בגדולתו ית' אשר אין לה חקר ותכלית כלל שכשמו כן הוא אין<sup data-n=\"804\">28</sup> לו תחילה ואין לו תכלה כלל אזי תתפעל לבבו ג\"כ באהבה רבה בגבורו' רשפי ושלהבת עזה שאין לה תכלה וגבול כלל שמאחר שנולדה מן ההתבוננו' דעצמו' אור אין סוף ב\"ה אזי יהי' האהבה ג\"כ בלי גבול ותכלי' כלל. וזהו בחי' הלוי<sup data-n=\"805\">29</sup> שנמשך מגבורו' עליונו' שלמעלה כו' בחי' אהבה רבה ברצוא והסתלקות שאין לה גבול ותכלה כלל אך מאחר שטבע הגבורו' שלמעלה הוא בחי' רצוא והסתלקות שאין קץ וגבול להעליו' וההסתלקו' דגבורו' עליונו' כדכתיב אלקים<sup data-n=\"806\">30</sup> אל דמי לך אל תחרש ואל תשקוט אל וכתיב למען<sup data-n=\"807\">31</sup> יזמרך כבוד ולא ידום וגו' כנודע ולזאת א\"א להיות נמשך מהם זולתי בחי' תחתונה שבהם בצמצום גדול ועצום מאד, שמצד בחי' ההסתלקות שלהם למעלה נתמעט השפע ונתצמצם בצימצום גדול ועצום מאד עד שאין יורד מהם רק בחי' התחתונה שבהם שנק' בחי' אלקי\"ם<sup data-n=\"808\">32</sup> מדת הצמצום וההסתר כנודע עד שנסתעף למטה מבחי' אלקים שהוא מדת הצמצום שהיא בחי' התחתונה דגבורו' עליונות בחי' גבורו' קשות ממש ולכך מצטרך להמתיק הגבורו' ואין<sup data-n=\"809\">33</sup> הגבורו' נמתקין אלא בשרשן והיינו ע\"י השיר של הלוים דהנה ארז\"ל אין<sup data-n=\"810\">34</sup> אומרים שירה אלא על היין דהיינו בחי' יין<sup data-n=\"811\">35</sup> המשמח אלקים ואנשים כו' שהיין הוא שרש הלוים (שהוא בבינה דאצי') דכאשר נכנס<sup data-n=\"812\">36</sup> יין יצא סוד שהוא המגלה הנעלם שיתגלה בבחי' גילוי שהוא משמח את בחי' ש' אלקים המסתיר ומצמצם השפע עליונה שלא יסתיר ויצמצם כ\"א יתגלה השפע עליונה למטה כי שמחה הוא בחי' התגלות כמשל במלך",[["801","25","<b>כי לא על הלחם לבדו</b>: עקב ח, ג."],["802","26","<b>שרש המוצא והמקור</b>: ראה ג\"כ לקו\"ת צו יג, ב. במדבר יא, ג. שלח לו, ג. עקב יד, ב."],["803","27","<b>דנעשה אדם</b>: בראשית א, כו."],["804","28","<b>אין לו תחלה ואין לו תכלה</b>: ראה חובת הלבבות שער היחוד פ\"ה. המשך תרס\"ו ע' כ."],["805","29","<b>הלוי. . מגבורות</b>: ראה לקו\"ת נשא כב, ב — וכמ\"ש בפרדס שם בערך לוי. ובמא\"א אות למ\"ד סי\"ד."],["806","30","<b>אלקים אל דמי לך</b>: תהלים פג, ב."],["807","31","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["808","32","<b>אלקים מדת הצמצום</b>: ראה ב\"ר רפי\"ד."],["809","33","<b>ואין הגבורו' נמתקין אלא בשרשן</b>: ראה פע\"ח שער השופר פ\"א. לקו\"ת להאריז\"ל וישב לט, א. תניא פל\"א."],["810","34","<b>אין אומרים שירה אלא על היין</b>: ברכות לה, א."],["811","35","<b>יין המשמח אלקים ואנשים</b>: שופטים ט, יג."],["812","36","<b>נכנס יין יצא סוד</b>: סנהדרין לח, א."]]],[2100490207,"ב\"ו שיושב במסתרים בהיכלי מלך חדר בחדר להחבא ובשעת השמחה הוא מתגלה לעיני עבדיו במשתה היין כו' כך עד\"מ למעלה ע\"י נסוך היין והשיר של הלוים נמשכים בחי' גילוי אור א\"ס ב\"ה למטה לשמח את בחי' אלקי\"ם שלא יסתיר ויצמצם עוד השפע עליונה (שהשיר של הלוים ונסוך היין הכל אחד כנ\"ל) והיינו כמ\"ש לגדולתו<sup data-n=\"813\">37</sup> אין חקר וכתיב<sup data-n=\"814\">38</sup> לתבונתו אין מספ\"ר הא כיצד כשהשפע נעלמה במקורה ושרשה בבחי' סתימו<sup data-n=\"815\">39</sup> דכל סתימן אזי נק' בחי' לגדולתו אין חקר החקר<sup data-n=\"816\">40</sup> אלוה תמצא דלית<sup data-n=\"817\">41</sup> מחשבה תפיסא בי' כלל וכשנמשכת ומתגלה למטה ע\"י השיר של הלוים ונסוך היין המשמח &lt;עו&gt;\nאלקים ואנשים אזי לתבונתו אין מספר דהיינו שנתהוה ממנה רבוא רבבו' מלאכי' ונשמות אשר אין להם מספר כלל כדכתיב היש<sup data-n=\"818\">42</sup> מספר לגדודיו כו' אבל יש לה חקר שהיא בבחי' גילוי רק שמתפשט' בבחי' אין סוף שאי\"ן מספר משא\"כ בעודה נעלמה במקורה אזי אין לה חקר כלל כנ\"ל, וזהו עבודת הלוי\"ם להמשיך מבחי' לגדולתו אין חק\"ר בחי' לתבונתו אין מספר וכדכתיב ועבד<sup data-n=\"819\">43</sup> הלוי הו\"א פי' הוא בחי' עלמא דאתכסי' בחי' בינה דאצי' שעבודת הלוי להמשי\"ך בחי' הוא שהוא בחי' עלמא דאתכסי' מההעלם אל הגילוי והיינו ע\"י השיר של הלוים ואין שירה אלא על היין המשמח אלקים כו', ולכך נקראו בחי' בדיח\"י דמלכא דכמו הבדח\"ן של המלך ב\"ו משמח אותו שמתגלה לעיני כל עבדיו כך עד\"מ הלוי עבודתו לנצח בכל כלי שיר שיתגלה השפע עליונה הנעלמה דאור א\"ס ב\"ה מהעלם לגילוי כו' וזהו בחי' המתיקות הגבורות עליוני' דבחי' אלקי' מדת הצמצום וההסתר שנמתקין בשרשן ע\"י עבודת הלוים לשורר על היין המשמח כו' וד\"ל.\nד) <b>והנה</b> כ\"ז הי' במקדש לאחר שהוקם הבית המקדש ביומוי דשלמה מלכא אך דוד המלך ע\"ה כשעשה הכנה לזה שישרה אור אין סוף ב\"ה בבית המקדש שיקים ויבנה שלמה בנו לכך בתחלת ההכנה אמר קומה<sup data-n=\"820\">44</sup> ה' למנוחתך וגו' כהניך<sup data-n=\"821\">45</sup> ילבשו צדק וחסידיך ירננו ולא לוייך ירננו והיינו בהיות ידוע שיש בחי' אבי\"ע בכל עולם פרטיי שאף בעשי' ימצא בחי' אבי\"ע והיינו שבחי' דצח\"ם<sup data-n=\"822\">46</sup> דעשי' הוא נגד בחי' אבי\"ע שהדומ\"ם הוא בחי' עשי' שבעשי' שאין למטה הימנו שהוא תכלית השפלות שבמדריגות ולכך כשמצטרך דוד המלך ע\"ה להמשיך רצון העליון ב\"ה מהמאציל שירצה בהשראת השכינה ב\"ה בבית המקדש שנבנה מאבני' שהוא בחי' הדומ\"ם דעשי' שאין למטה במדרגה ולא הי' כמוהו לפניו שהי' השראת השכינה ב\"ה במשכן של משה רע\"ה העשוי מיריעות מגוונין ארגמן<sup data-n=\"823\">47</sup> ותכלת כו'",[["813","37","<b>לגדולתו אין חקר</b>: תהלים קמה, ג."],["814","38","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["815","39","<b>סתימו דכל סתימן</b>: ראה זהר בהקדמה ב, א ועוד. תניא פנ\"א."],["816","40","<b>החקר אלוה תמצא</b>: איוב יא, ז."],["817","41","<b>דלית מחשבה תפיסא בי'</b>: ראה ת\"ז בהקדמה (יז, א)."],["818","42","<b>היש מספר לגדודין</b>: איוב כה, ג."],["819","43","<b>ועבד הלוי הוא</b>: קרח יח, כג."],["820","44","<b>קומה ה' למנוחתך</b>: בהעלותך י, לה."],["821","45","<b>כהניך ילבשו צדק</b>: תהלים קלב, ט."],["822","46","<b>דצח\"ם. . אבי\"ע</b>: ראה מאו\"א אות צ סכ\"ד. אמרי בינה שער הק\"ש עח, ב. לקו\"ת במדבר ה, ריש ע\"ב. וראה ס' השיחות תשנ\"ב ע' 139 הערה 54."],["823","47","<b>ארגמן ותכלת</b>: ראה תרומה כה, ד. כו, לא."]]],[2100490208,"שהוא הגבה למעלה מאד נעלה מבחי' אבני\"ם של בהמ\"ק שהם בחי' דומ\"ם דעשי' ולכך אמר דוד וחסידיך ירננו שיהי' בחי' המתקת הגבורו' ע\"י הכהנים שהם נמשכים מבחי' החסדי' עליוני', אך שרש שרשם הוא ג\"כ בחי' הגבורו' עליוני' דהיינו שמגבורו'<sup data-n=\"824\">48</sup> דאבא נעשה בחי' חסדי' דאימא והכהנים הם מבחי' חסדי' דאימא ששרשן הוא בחי' גבורו' דאבא והלוים הם מבחי' גבורו' דאימא ולכך אמר דוד וחסידיך ירננ\"ו שהמתקת הגבורות יהי' ע\"י הכהנים שלמעלה מהלוים שימתיקו בשרשן בגבורו' דאבא, והכונה בזה בכדי שימשוך בחי' אור א\"ס ב\"ה במורד כ\"כ למטה שיהי' מנוחתו כבוד בבהמ\"ק של אבני\"ם שלמטה שבו ישרה בחי' האבוקה הוא האור הגדול דאור א\"ס ב\"ה עד שיתבטלו כל החצוני' כנר בפני האבוקה ויהי' שלום על ישראל כנ\"ל שזה הכלל כל מה שגבוה יותר בשרשו יוכל לישפל במורד למטה במורד יותר כמשנ\"ת<sup data-n=\"825\">49</sup> במ\"א ע\"פ ועברתי<sup data-n=\"826\">50</sup> בארץ מצרים אני ולא מלאך כו' ע\"ש לכך סדר דוד כהני וחסידי דלהוי אינון בדיח\"י דמלכא אע\"ג דלאו ארחייהו בהאי בכדי להמתיק הגבורות למעלה מעלה בשרש שרשן באבא דאצי' שעי\"ז יומשך מ\"ד ממקום &lt;עז&gt;\nגבוה מאד נעלה להיות נשפל במורד למטה יותר לשרות בבית אבנים דהא בהא תליא מה דלא סגי בלא\"ה כנ\"ל וד\"ל.\nה) <b>ובאור</b> הענין דהנה בחי' גבורו' דאימא הוא שרש הלוים שהוא בחי' האהבה רבה בגבורת רשפי אש ושלהבת עזה הנולדה מן ההתבוננות בעצמו' אור אין סוף ב\"ה שנסתעף מזה האה\"ר ברצוא והסתלקות ממש בכלות הנפש ממש וזהו עבודת הלוים בקול זמרה מבחי' חסדי' דאימא הוא בחי' שרש הכהני\"ם שעבודתן בלחישא ברעותא דליבא ובכונה כו' דהיינו מ\"ש בס\"י ואם<sup data-n=\"827\">51</sup> רץ לבך שוב לאחד שהוא בחי' עסק התורה שלאחר התפלה שזהו שוב לאחד שהוא תכלית הביטול האמתי בקרירות ונחת לבטל רצונו מפני רצון העליון ב\"ה ולבטל א\"ע מכל וכל לעסוק בחכמתו ורצונו ית' ודבר ה' בפיו כמ\"ש ואשים<sup data-n=\"828\">52</sup> דברי בפיך וגו' (וכמ\"ש המגיד לב\"י אני<sup data-n=\"829\">53</sup> המשנה המדברת בפיך) כמ\"ש<sup data-n=\"830\">54</sup> במ\"א שזהו תכלית הביטל האמיתי בקרירות ונחת שלמעלה מבחי' הרצוא דרשפי אש של הלוים.\n<b>אך</b> שרש החסדים דאימא בחי' הכהני\"ם שהוא בחי' השוב לאחד הוא בחי' גבורו' דאבא שמגבורו' דאבא נעשה החסדי' דאימא והיינו כנודע שאבא דאצי' הוא",[["824","48","<b>שמגבורות דאבא. . חסדים דאימא</b>: ראה ע\"ח שער הכללים פ\"י."],["825","49","<b>כמשנ\"ת במ\"א. . ע\"ש</b>: ראה לקו\"ת אמור לד, ג. בחוקותי מז, ד. נשא כא, א. מטות פא, ב. ראה כא, ג. שה\"ש ג, ג."],["826","50","<b>ועברתי בארץ מצרים. . אני ולא מלאך</b>: בא יב, ב. ספרי תבוא כו, ח. זהר (מדרש הנעלם) וירא קיז, א. הגש\"פ. סידור סדר הגדה רצט, א. ומקבילו בלקו\"ת צו יב, ג. מאמרי אדה\"א נ\"ך ע' עט."],["827","51","<b>ואם רץ לבך</b>: ס' יצירה פ\"א, מ\"ח."],["828","52","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["829","53","<b>אני המשנה המדברת בפיך</b>: ראה מגיד מישרים פ' ויחי, בא, תשא, ועוד [ירושלים תש\"ך מה, ב. נג, ב. סט, ב]."],["830","54","<b>כמ\"ש במ\"א</b>: ראה תו\"א וישב ל, א. וארא נח, א. נט, ב. לקו\"ת פקודי ח, ב. אמור לו, א. בהר מב, ב. במדבר ז, ג. יט, א. ואתחנן י, א."]]],[2100490209,"כלי הביטול האמתי בבחי' מ\"ה שהוא בחשאי ולחש בחי' קול<sup data-n=\"831\">55</sup> דממה דקה מצד דתמן<sup data-n=\"832\">56</sup> קאתי מלכא ששם עיקר השראת אור אין סוף ב\"ה לכך הוא בתכלית הביטול בבחי' דממה ושתיקה כמארז\"ל סיג<sup data-n=\"833\">57</sup> לחכמה שתיקה וזה הי' שרשו של משה רע\"ה שהי' כבד<sup data-n=\"834\">58</sup> פ\"ה וכבד לשון והי' עניו<sup data-n=\"835\">59</sup> מאד מכל האדם אשר ע\"פ האדמה בתכלית הביטול והשפלות אמיתי עד שאמר ואנחנו<sup data-n=\"836\">60</sup> מ\"ה כו'.\n<b>אך</b> מאחר שמחמת הביטול הגדול דחכמ\"ה גורם ריחוק ושפלות גדולה עליו כמשל העומד לפני מלך ב\"ו ורואה פני המלך שמתבטל ממהותו ואובד מיחוש הרגשת עצמו מחמת גודל היראה והביטול כו' לכך נק' בחי' גבורו' דאבא פי' שמחמת הביטול הגדול יגרום לו בחי' ריחוק ושפלות מאד שהוא בחי' שמאל דוחה שבאבא דאצי' שיסתעף מחמת הביטול בחי' ריחוק ושפלות גדולה עד שיהא בבחי' דממה ושתיקה בלי הרגשת עצמו כו' ולכך נקרא החכמ\"ה בשם רחוק כמ\"ש אמרתי<sup data-n=\"837\">61</sup> אחכמה והיא רחוקה ממני וכתיב ותתצב<sup data-n=\"838\">62</sup> אחותו מרחוק וכתיב מרחוק<sup data-n=\"839\">63</sup> ה' נראה לי וגו' והרבה מקראות כאלו שמכנים החכמה בשם רחו\"ק מצד בחי' הגבורו' שבה הוא בחי' שמאל דוחה שבה לרחקו ולהשפילו בתכלית השפלות והביטול בבחי' יראה עלאה בבחי' מ\"ה ולכך היה משה עניו מאד מכל האדם אשר ע\"פ האדמה ודרשו רז\"ל יכול<sup data-n=\"840\">64</sup> אפי' ממה\"ש ת\"ל אשר ע\"פ האדמה דייקא שבהמלאכי' ימצא בחי' השפלות והביטול יותר מצד שכל הקרוב קרוב הוא יותר רחוק בבחי' שמאל דוחה שבחכמה כ\"ח<sup data-n=\"841\">65</sup> מ\"ה תכלית הביטול האמיתי כנ\"ל וד\"ל, ולזאת מבחי' הגבורו' דאבא הוא בחי' השמאל דוחה שבו לגרום הרחוק והשפלות אמיתי בבחי' מ\"ה &lt;עח&gt;\nתכלית הביטול דבחי' קול דממה דקה כנ\"ל יסתעף בחי' החסדי' דאימא הוא העסק בתורה בתכלית הביטול בקרירו' ונח\"ת שיהי' רק דבר ה' מדבר בפיו והוא מתבטל במציאו' מכל וכל שזהו בחי' שוב לאחד שזה נסתעף מגבורו' דאבא דוקא כנ\"ל (והיינו כמו עד\"מ כשיעמיק החכם באיזה שכל עמוק שלמעלה מערך שכלו שאינו יכול לתפוס אותו ברוח בינתו ממש זולתי מתבטל ונשתומם מהמראה ומשתאה בבחי' שיאוי ושממה שגורם ריחוק ושפלו' לעצמו בלבד וזהו עד\"מ למעלה בחי' השגת הביטול דחכמ\"ה כ\"ח מ\"ה שנק' בחי' ריחו\"ק כמ\"ש אמרתי אחכמה והיא רחוקה ממני כנ\"ל שזהו בחי' גבורו' דאבא וד\"ל).\n<b>וז\"ש</b> דוד קומה ה' למנוחתיך דהיינו בחי' המשכת השפע דאור אין סוף ב\"ה שישרה בבהמ\"ק של אבני\"ם שאז יהי' בחי' מנוחה והשקט שיתבטלו כל",[["831","55","<b>קול דממה דקה</b>: לשון הכתוב — מלכים-א יט, יב."],["832","56","<b>דתמן קאתי מלכא</b>: ברכות נח, א. ראה זהר (רע\"מ) פנחס רכג, ב. תקו\"ז בהקדמה (ג, ב)."],["833","57","<b>סיג לחכמה שתיקה</b>: אבות פ\"ג מי\"ג."],["834","58","<b>כבד פה</b>: שמות ד, י."],["835","59","<b>עניו מכל האדם</b>: בהעלותך יב, ג."],["836","60","<b>ואנחנו מה</b>: ראה בשלח טז, ז. ח."],["837","61","<b>אמרתי אחכמה והיא רחוקה ממני</b>: קהלת ז, כג."],["838","62","<b>ותתצב אחותו מרחוק</b>: שמות ב, ד."],["839","63","<b>מרחוק ה' נראה לי</b>: ירמי' לא, ב."],["840","64","<b>יכול אפי' ממה\"ש</b>: ראה ספרי בהעלותך יב, ג."],["841","65","<b>כח מה</b>: זח\"ג לד, א."]]],[2100490210,"החצוני' כנר בפני האבוקה כהניך ילבשו צדק וחסידיך ירננו שיהי' הכהני' וחסידי ירננו להמתיק הגבורו' בשרשן בחי' גבורו' דאבא דאצי' שמהם נסתעף בחי' חסדי' דאימא שמצד ששרש הכהנים הגבה למעלה מהלוי' שממתיקי' הגבורו' דאבא (משא\"כ הלוי' ממתיקי' גבורו' דאימא כנ\"ל) יומשך מ\"ד ממקום גבוה מאד נעלה במורד למטה מטה להתלבש ולשרות בבהמ\"ק של אבנים שכל הגבוה גבוה יותר יורד למטה מטה יותר כנ\"ל.\n<b>אך</b> בחי' הרננה של כהני וחסידי אינו כאופן השיר של הלוים, שהשיר של הלוי\"ם הי' אומרים שירות ותשבחות בפה למנצח<sup data-n=\"842\">66</sup> לבני קרח מזמור כו' (והימן<sup data-n=\"843\">67</sup> ואיתן וכלכל ודרדע בני מחו\"ל היו המשוררי' ברוח הקודש ששרתה עליהם וגם משה רע\"ה הי' משורר כנודע) אבל הרננה של הכהנים הוא בבחי' המחשבה בכונה ורעותא דלבא מצד שרשם הנעלה דכל עובדוי דכהנא בלחישא כו' והיינו כמו שמחשב ומצייר במחשבתו הקולות מהניגון והזמר כו' משא\"כ כשמשורר בקו\"ל והבל הלב היוצא מפה כו' כך ממש עד\"מ הרננה של הכהנים הי' בדקות יותר בבחי' רעותא דלבא בלחישא שאף ששרשם מגבורו' עליונות דאבא אעפי\"כ לגבי אימא דאצי' נק' בחי' חסדי' שהוא בקרירות ונח\"ת בחי' קול דממה דקה משא\"כ הלוים ששרשם מגבו' דאימא לארמא קלא כו' שהי' נרגש השיר שלהם בפה ולשון ובכלי זמרה ממש כו' וד\"ל.\n<b>ובזה</b> יובן בפשיטות לשון הזהר הנ\"ל, מכאן אוליפנא דמאן דמזמן למלכא ישני עובדוי אי אורחא דמלכא דחדאן לי' בדיחי הדיוטי יסדר קמי' בדיחי רופינוס ופרדשכי כו' והיינו שלאחר זמן כשהוקם הביהמ\"ק ושרתה השכינה עליו הי' הבדיחי דמלכא בחי' הלוי\"ם שהי' אז מתנהג בהדרגה אך כאשר יצטרך דוד לאזמין למלכא שישרה בביהמ\"ק אזי שני עובדוי להיות הבדיחי דמלכא בחי' כהני וחסידי דאינון חשיבי יתיר כו' וכנ\"ל. א\"ל קב\"ה דוד לאו הכי, א\"ל דוד מארי כד אנת בהיכלך כו' ע\"ש עד אמר דוד בעבור &lt;עט&gt;\nדוד עבדך אל תשב פני משיחך סדורא דקא סדרנא לא יתוב לאחורא א\"ל קב\"ה דוד חייך דאפי' במאנין דילי לא אשתמש אלא במאנין דילך כו'.\n<b>והענין</b> דהנה ידוע שיש בחי' כלי' דאצי' המגבילי' האור והשפע של אור א\"ס ב\"ה שלא יתפשט יותר מדאי בבחי' אין סוף ממש כדי שיכלו להתהוות הנבראים בערך ותכלית, והיינו שאף הם בעצמן בחי' אין סוף ממש פי' שבכחן הוא להפעיל נפעלין אין קץ ולהתפשט בלי גבול ותכלית כלל רק שהם בחי' גבו\"ל בפועל שלא יעפילו בחי' א\"ס זולתי בגבול ותכלית לעצור הכח הגדול דא\"ס שלא תתפשט בפעולתו בבחי' א\"ס זולתי בבחי' גבול ותכלית, וכנודע שאף הכלי' דאצי' הם בחי' אלקות ממש דאיהו וחיוהי פי' האורו' דאצי' וגרמוהי פי' הכלי' דאצי' חד ממש דכמו שאין משיגין בחי' האורו' דאצי' הנמשכי' מאור א\"ס ב\"ה שכשמובן הוא שאין לו תכלה כלל כו', כך אין משיגים בחי' הכלי' דאצי' שמצמצמי' ומגבילין את השפע דאור א\"ס ב\"ה שלא תתפשט בבחי' הפעולה רק בבחי' גבול שאף הם מיוחדים",[["842","66","<b>למנצח לבני קרח מזמור</b>: תהלים מז, א."],["843","67","<b>והימן ואיתן וכלכל ודרדע</b>: מלכים-א ה, יא."]]],[2100490211,"במאצילן והם בחי' א\"ס ממש בבחי' הכח שלהן זולתי הם בחי' גבול שבא\"ס דהיינו לצמצם השפע דא\"ס בבחי' הפעולה בלבד (שהוא שיעור קומה של מ\"ב שנמדד בבחי' גבול דאצי') וכמ\"ש בלק\"א ע\"ש והיינו שהמאציל ית' הוא כ\"ל יכו\"ל לכך מצטרך להיות נמצא אף בחי' הגבול בא\"ס דהיינו כח הפעולה בבחי' גבול בלבד שנמצא בכלי' דאצי' המיוחדים במאצילן ב\"ה דאל\"כ לא יהי' תכלית השלימות ח\"ו ולא יהי' כל יכול ח\"ו כו' וזהו עיקר השלימות שלמעלה שהוא כל יכול שאף בחי' הגבול נמצא בא\"ס כנ\"ל וד\"ל.\n<b>אך</b> הנה הכלים דבריאה הם בחי' גבו\"ל ממש דהיינו שאף בכחן הם בחי' גבול ממש שלא ימצא בהם הכח והיכולת בבחי' אין סוף ולזאת מהם יתהוו המלאכים הבע\"ג ותכלית בחומר וצורה שלהן שהחומר הוא הכלי של המלאך שיש לו גבול שגבוה ת\"ק שנה כו' והצורה הוא האור השכל וההשגה שלו שיש לו גבול להשגתו כו' והוא מצד המשכתן מהכלי' דבריאה שהם בחי' גבול ממש בבחי' הכ\"ח שלהן, והנה נז' בע\"ח שאף בבריאה ימצא בחי' כלים דאצי' המלובשים בבריאה שהם בחי' אלקות ממש דאיהו וגרמוהי חד ונפש רוח דבריאה הם בחי' הכלים דבריאה בחי' גבו\"ל נפרד ממש שמשם יפרד כו' כנודע.\n<b>ובזה</b> יובן בפשיטות כונת הזהר א\"ל קב\"ה דוד חייך דאפי' במאנין דילי לא אשתמש כו' בהיות נת\"ל שעיקר הכונה של דשני עובדוי דעביד כהני וחסידי דלהוו אינ\"ן בדיחי דמלכא כו' בכדי שיומשך המ\"ד של אור א\"ס ב\"ה ממקום גבוה מאד נעלה במורד למטה מטה להיות מנוחתו כבוד בבית המקדש של אבני\"ם בחי' דומם דעשי' וזהו קומה ה' למנוחתך וגו' כנ\"ל. וזהו ההבטחה של המאצי' ב\"ה שהבטיח לו ע\"ז ואמר לו חייך דאפי' במאנין דילי לא אשתמש אלא במאנין דילך פי' שהבטיח לו שלא זו בלבד שיומשך השראת אור אין סוף ב\"ה למטה לשרות בבה\"ק דבריאה ע\"י ההתלבשותו בכלים דאצי' המלובשי' בבריאה שהם נשמה דבריאה אלא אף זו &lt;פ&gt;\nשירד השפע כ\"כ למטה להתלבש בכלי' דנפש רוח דבריאה ממש וזהו אפי' במאני\"ן דילי הם הכלי' דאצי' המלובשים בבריאה לא אשתמש אלא במאנין דילך הם הכלים דבריאה בחי' נפש רוח דבריאה שהם הכלי של דוד המלך ע\"ה כנודע שדוד<sup data-n=\"844\">68</sup> הוא בחי' מל' דאצי' ומאנין דילי' הם הכלי' דבריאה ממש שנק' מאני\"ן דילך כנ\"ל. וזהו ענין כונת הזוהר לפרש תחלת הענין שהתחיל בפ' ויקח<sup data-n=\"845\">69</sup> מאבני המקום שע\"ז קאי וסובב ענין זה שסיים מענין הפתיחה דהיינו שמאנין דדו\"ד מלכא הם הכלים דנפש ורוח דבריאה שנק' בחי' אבני המקום שלגבי אצי' נק' בחי' אבני\"ם בחי' דומם ממש כמ\"ש ומעפר<sup data-n=\"846\">70</sup> אשר בקרקע המשכן כו' וכתיב הכל<sup data-n=\"847\">71</sup> הי' מן העפר כו' כנודע שנק' בחי' אבני' ועפר והיינו בחי' י\"ב<sup data-n=\"848\">72</sup> בקר דים של שלמה שלשה פונים צפונה",[["844","68","<b>שדוד. . מל' דאצילות</b>: מאו\"א אות ד, ס\"ט."],["845","69","<b>ויקח מאבני המקום</b>: ויצא כח, יא."],["846","70","<b>ומעפר אשר בקרקע המשכן</b>: נשא ה, יז."],["847","71","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["848","72","<b>י\"ב בקר דים של שלמה</b>: מלכים-א ז, כג-כה. ראה זהר ויחי רמז, א. וראה תו\"א ויחי קג, סע\"א ואילך. לקו\"ת בלק סח, ג. אוה\"ת ויקרא ע' קל."]]],[2100490212,"ושלשה פונים ימה כו' והים עליהם מלמעלה שהם בחי' המרכבה דבריאה שתחת מל' דאצי' כנודע שלגבי אצי' נק' הכלי' הללו מאני\"ן דדוד בחי' אבנ\"י המקום, וזה המשיך דוד המלך בתפלתו קומה ה' למנוחתך ושני עובדי דכהני וחסידי להוי בדיחי דמלכא עד שהבטיח לו המאצי' ב\"ה שיוסיפו השפע דאור א\"ס כ\"כ במורד למטה להשתמש במאנין דילי' בכלי' דבריאה שנק' אבני המקום ואזי ממילא ישרה בבהמ\"ק של אבנים שלמטה דהא בהא תלי' כנ\"ל. וכן הוה שבמעשה הקרבנות ארז\"ל פני נשר יורד ומקבל כל תורין ובני יונה כו' שאין הכונה בחי' כלי' דנח\"י דאצי' שבבריאה שיש בהם גם פני נשר כו' יורדי' לקבל הקרבנין דתורין כו' כ\"א אף בחי' הכלי' דנפש רוח דבריאה שהוא פני נשר שבמרכבה דבריאה יורדי' לקבל הקרבנין וכן פני שור ופני ארי' כו' וכנ\"ל, ולא זז מתמן עד דנפק ליה מתנן ונבזבזן כו' היינו שנתן המאצי' ב\"ה לדוד בחי' מל' דאצי' מתנן ונבזבזין הם כל האורות דאצי' שיתלבשו בכלי' דבריאה שלו שנק' מאני\"ן דדוד מלכא וכנ\"ל וד\"ל."],[2100490213,"<h3>למה נסמכה פ' מיתת מרים לפ' פרה</h3>\n<b>בעזר\"ה</b>\n<b>למה</b><sup data-n=\"849\">1</sup> נסמכה<sup data-n=\"850\">2</sup> פ' מיתת מרים לפ' פרה אדומה לומר לך מה פרה מכפרת אף מיתת צדיקים מכפרת כו', הנה בדרש הזה יש לדקדק הרבה דמ\"מ מה זו סמיכה שסמך דוקא [לפרה<sup data-n=\"851\">3</sup> אדומה הנעשה חוץ לשלש מחנות ולא נסמכה] לפ' חטאת שנעשי' בפנים שנעשי' לכפרה ע\"ג מזבח ממש ופ' פרה לא נאמרה בפי' לכפרה אלא רק דחטאת<sup data-n=\"852\">4</sup> קרי רחמנא, ודרש זה אינו אלא ללמד שמיתת צדיקים מכפרת, א\"כ הי' לו לסמוך דוקא לפי שנאמר בה קרבן חטאת שנעשי' בפנים לכפרה ע\"ג המזבח כו'.",[["849","1","<b>למה נסמכה פ' מיתת מרים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 עו, ב.\nמאמר זה הוא ביאור על אגה\"ק סי' כח. וראה שיעורים בס' בתניא. ליקוט פירושים — חיטריק על סימן זה. (איזה הערות ומראי מקומות כאן נעתקו מליקוט פירושים).\nבאגה\"ק שם כתוב: מה שכתב למחותנו הרב הגאון המפורסם איש אלקים קדוש ה' נ\"י ע\"ה פ\"ה מו\"ה לוי יצחק נ\"ע אב\"ד דק\"ק בארדיטשוב לנחמו על פטירת בנו הרב החסיד מו\"ה מאיר נ\"ע."],["850","2","<b>למה נסמכה פ' מרים לפ' פרה לומר לך מה פרה מכפרת וכו'</b>: מו\"ק כח, א. הובא בפרש\"י חוקת כ, א. וז\"ל הגמרא שם: ”למה נסמכה מיתת מרים לפרשת פרה אדומה לומר לך מה פרה אדומה מכפרת אף מיתתן של צדיקים מכפרת\", בתוס' רוצים לבאר שזה קאי על מעשה העגל, אבל בחי' מהרש\"א דוחה ומפרש וכתב: ”דאע\"ג דמוכח בכמה דוכתין דפרה קדשי בדק הבית היא מ\"מ חטאת קרייה רחמנא גם שהיא נקחית מתרומת הלשכה כמו שאר קרבנות\". ע\"ש.\nוראה לקו\"ש חי\"ב ע' 36: שכשם שענינם של מי חטאת הוא לטהר טומאת מת ”אף שהוא אבי אבות וכו' ולמטה מטה מנוגה\", כך מיתת צדיקים ”פועל ישועות בקרב הארץ לכפר על עון הדור אף גם על הזדונות שלמטה מנוגה\". תורת מנחם כרך א' ע' 142."],["851","3","<b>[לפרה אדומה. . נסמכה]</b>: שורה זו ניתוספה כאן מאגה\"ק שם.."],["852","4","<b>דחטאת קרי רחמנא</b>: ע\"ז כג, ב. וראה דרך מצותיך קיא, ב."]]],[2100490214,"<b>אך</b><sup data-n=\"853\">5</sup> הנה נודע סוד<sup data-n=\"854\">6</sup> הקרבנות מהאריז\"ל<sup data-n=\"855\">7</sup> שהן בחי'<sup data-n=\"856\">8</sup> העלאות מ\"נ מנה\"ב ששרשו נלקח מבחי' ד'<sup data-n=\"857\">9</sup> חיות המרכבה הנושאות<sup data-n=\"858\">10</sup> את הכסא פני שור ופני נשר כו', ועי\"ז נמשכים<sup data-n=\"859\">11</sup> ויורדים בחי' מ\"ד מאדם<sup data-n=\"860\">13</sup> העליון שעל הכסא<sup data-n=\"861\">14</sup> הנק'<sup data-n=\"862\">15</sup><sup data-n=\"863\">16</sup> מלכא וגם נק' ז\"א<sup data-n=\"864\">12</sup> כידוע.\n<b>וביאור</b><sup data-n=\"865\">17</sup> הדברים ידוע להיות שנאמר האכל<sup data-n=\"866\">18</sup> יאכל וארז\"ל בב'<sup data-n=\"867\">19</sup> אכילות הכתוב מדבר א' באכילת מזבח וא' באכילת אדם כו', והיינו מה שהבהמה הגשמי' ששרשה מבחי' פני שור שבמרכבה דבי\"ע נשרפת ונכללת באש שלמעלה ע\"ג המזבח שלמטה זה נק' אכילת מזבח ומה שהכהנים<sup data-n=\"868\">20</sup> אוכלים ובעלים מתכפרין זהו הנק' אכילת אדם ואין אכילת אדם מכפר אלא לאחר כפרת המזבח כשנזרק הדם ונקטר",[["853","5","<b>אך הנה נודע</b>: בהבא לקמן ראה בארוכה לקו\"ת ר\"פ חוקת (הערת כ\"ק אדמו\"ר זי\"ע לאגה\"ק שם)."],["854","6","<b>סוד הקרבנות</b>: מבואר בכמה מקומות בדא\"ח, ומהם ראה תו\"א כו, ד. עא, סע\"א. לקו\"ת ויקרא שה\"ש כח, ג. מובא גם באוה\"ת יתרו ע' א'לה. סה\"מ תקס\"ז ע' רפט. מובא גם באוה\"ת ויקרא כרך ב ע' תקעא. כרך ג ע' תשכט. פנחס ע' א'פז. שה\"ש כרך א קסב.\nנזכר בלקו\"ת מסעי צב, ג. ראה אוה\"ת בראשית כרך א קפט, א. כרך ז' תתשפב, א."],["855","7","<b>מהאריז\"ל</b>: לקו\"ת להאריז\"ל פרשת ויקרא. שם באגה\"ק: מזוה\"ק [ח\"א סד, ב] והאריז\"ל.\nע' ע\"ח ש\"נ שער קיצור אבי\"ע סוף פ\"ב — (לקוטי הגהות לתניא ע' פב)."],["856","8","<b>בחי' העלאת מ\"נ</b>: נתבאר בסה\"מ תקס\"ה כרך א ע' קסג. דרך מצותיך צא, א-ב שצריכים ענין העלאת מ\"ן כדי להמשיך ממנו ית' בבחי' ההארה שבהשתלשלות בסוד תוספת מרובה על העיקר. ראה אוה\"ת שמות כרך א ע' שי.\nראה לקוטי הגהות לתניא ע' פג בשם הצ\"צ: ע' פ' נשא בביאור מעט ע\"פ זאת חנוכת [לקו\"ת נשא כט, ג: ”והנה מבואר במ\"א באגה\"ק ד\"ה למה נסמכה פ' מרים שע\"י העלאת מ\"ן של הקרבנות שע\"ג המזבח נמשכים ויורדים מ\"ד מבחי' אדם שעל הכסא הנק' ז\"א דאצילות\"]. ע' פ' פנחס ע\"פ את קרבני לחמי קיצור לאות ג' [לקו\"ת פנחס עז, ב] קרבן עיקרו המשכת מ\"ד מז\"א. ע' פ' מסעי [לקו\"ת מסעי צב, ג: ”וכמ\"כ הוא ג\"כ בענין הקרבנות שהן בחי' העלאת מ\"ן מנפש הבהמית שבנוגע כו' ועי\"ז נמשכים ויורדים מ\"ד (עיין באגה\"ק בד\"ה למה נסמכה\"] בביאור אלה מסעי אות ב' העלאת מ\"ן."],["857","9","<b>ד' חיות המרכבה</b>: יחזקאל פ\"א."],["858","10","<b>הנושאות את הכסא</b>: בחיי תרומה כה, י. ובכ\"מ."],["859","11","<b>נמשכים ויורדים בחי' מ\"ד</b>: ראה זח\"ג ריז, סע\"א. אוה\"ת יתרו ע' תתקנז. ויקרא כרך ג ע' תשכט. נזכר באוה\"ת שה\"ש כרך ג ע' תתסד. בסה\"מ תרס\"ג ע' נב. אוה\"ת תצוה ע' א'תשס."],["860","13","<b>מאדם העליון</b>: מובא באוה\"ת בראשית כרך א קפט, ב: ”ועיין באג\"ה סי' כח ד\"ה למה נסמכה מובן כמ\"ש שהקרבנות להמשיך האור בבחי' אדם העליון\". ובכרך ה תתקצז, ב."],["861","14","<b>מאדם. . על הכסא</b>: ראה יחזקאל א, כו."],["862","15","<b>הנק' מלכא</b>: ראה זח\"ג י, א."],["863","16","<b>נק' ז\"א</b>: ראה זח\"ג סו, ב. ושם רכו, א."],["864","12","<b>ויורדים. . ז\"א</b>: מובא באוה\"ת משפטים ע' א'קעא: ”בד\"ה זאת חנוכת המזבח [כנראה הכוונה ללקו\"ת נשא כט, א] משמע שההמשכה רק מבחי' ז\"א כמש\"ש שזהו\"ע כן לב האדם לאדם, וכן מבואר באג\"ה סי' כח\". וקודם לזה מביא מלקו\"ת שה\"ש כח, ג דשם מבאר שהקרבן עולה עד אוא\"ס ע\"ש."],["865","17","<b>וביאור הדברים</b>: בהבא לקמן — ראה גם אוה\"ת בראשית כרך ז תתשפב, א ואילך. סה\"מ ה'ש\"ת ע' סב ואילך."],["866","18","<b>האכל יאכל</b>: צו ז, יח."],["867","19","<b>בב' אכילות הכתוב מדבר</b>: זבחים יג, ב. וראה לקו\"ת ר\"פ צו. שלח מא, ג. סה\"מ תקס\"ה ע' קסג ואילך. דרך מצותיך צ, ב ואילך."],["868","20","<b>שהכהנים אוכלים ובעלים מתכפרים</b>: פסחים נט, ב. רמב\"ם הל' מעשה הקרבנות פ\"י ה\"א."]]],[2100490215,"האימורים כידוע וכך הדוגמא מזה יובן במזבח העליון ששם יורד<sup data-n=\"869\">21</sup> בחי' אש שלמעלה ג\"כ ואוכל הקרבנות היינו מה שבחי' הגבורות עליונות דנוק' דז\"א כו' שהוא בחי' מל' דאצי' אוכלת וכוללת בעצמה מכל מיני בהמות וחיות שנמשכו בד' חיות שבמרכבה פני שור ופני נשר כו' בכלל מפני שמתבטלים ונכללין במקור חוצבם כו' זהו הנק' אכילת מזבח העליון, ומהם הנעשה אח\"כ הוא בחי' העלאת מ\"נ בכלל כלפי מעלה דהיינו לגבי בחי' אדם עליון שעל הכסא הנק' ז\"א כו' ואכילת אדם זהו עד\"מ שיאכל אדם מאכל אחר שהוכשר ונתברר מכל סיגי כו' ומה שיתחזק שכלו ולבו מזה המאכל עד\"מ זהו הנק' בחי' המשכת מ\"ד דהיינו מוחין חדשים שנוספים למעלה בבחי' ז\"א ע\"י אכילת הקרבנות שנק' אכילת אדם ע\"ד דוגמא של אכילת הכהן למטה שהוא בחי' המשכת שפע עליונים וכמ\"ש במ\"א באריכות ע\"פ כי הוא יברך הזבח כו' וזהו שאמרו בכתבי האריז\"ל דרך כלל שהקרבנות מפני נשר ופני שור כו' הן בחי' העלאת מ\"נ, ועי\"ז נמשכים ויורדים בחי' מ\"ד מז\"א שנק' אדם שעל הכסא כידוע והיינו משארז\"ל על ענין רעייתי<sup data-n=\"870\">23</sup> פרנסתי ישראל מפרנסין לאביהם שבשמים וכמ\"ש לחמי<sup data-n=\"871\">24</sup> לאשי כו' וכמ\"ש באתי לגני<sup data-n=\"872\">25</sup> כו' אכלתי יערי כו' ייני עם חלבי כו' שהוא ענין כללות הקרבנות ובפרט יש כמה פרטי מדריגות בכל קרבן לפי מה שהוא ומעלה מ\"נ וממשיכים מ\"ד כו' והן חטאת ועולה ושלמים מפני שמחולקים במדריגת הכפרה כו' כידוע וד\"ל.\n<b>ואמנם</b> הנה כ\"ז דוקא בקרבנות הנעשי' בפנים לכפרה ע\"ג המזבח כנ\"ל אבל בשריפת פרה אדומה שנעשי' בחוץ ענין מעלה ומדריגה יתירה הי' בה מכל הקרבנות שנעשו בפנים כו'.\n<b>ולהבין</b> זה הנה תחלה יש להקדים שרש ענין מעשה שריפת פרה אדומה, דהנה ענין נתינת מים<sup data-n=\"873\">26</sup> החיים לתוך אפר פרה נק' במשנה<sup data-n=\"874\">27</sup> קידוש מי חטאת כידוע,",[["869","21","<b>יורד בחי' אש שלמעלה</b>: ראה תו\"א כב, ד. סב, ב. לקו\"ת אמור לח, ד. ובכ\"מ.\n22)וכמ\"ש במ\"א. . ע\"פ כי הוא יברך הזבח: ראה סה\"מ תקס\"ה ע' קסב ואילך."],["870","23","<b>רעייתי פרנסתי ישראל מפרנסין</b>: שה\"ש א, טו. וראה זהר ויקרא ז, ב."],["871","24","<b>לחמי לאשי</b>: פינחס כח, ב."],["872","25","<b>באתי לגני</b>: שה\"ש ה, א."],["873","26","<b>מים החיים לתוך אפר פרה</b>: ראה אוה\"ת חוקת ע' תשצז: ענין פרה אדומה פי' בפנ\"י על התשובה [ראה שם ע' תשעא: ”בחי' בע\"ת שזהו אפר ע\"ג מים\", שם ע' תשעד, תשעו, ושם ע' תת: ”אפר פרה כענין העלאת האבק עד כסה\"כ והוא ענין בע\"ת\". פי' הפנים יפות — נתבאר באוה\"ת שם ע' תשעו], (וכ\"מ באגה\"ק סי' כח בד\"ה למה נסמכה פ' פרה כו' יעו\"ש), והיינו כי הזאת מי חטאת הוא ע\"ד וזרקתי עליכם מים טהורים כו' וכן ע\"ד ואת רוה\"ט אעביר כו'. . וע\"י התשובה מחזיר הניצוצות שנפלו לג\"ק לקדש ממש, וכ\"ה בענין טהרת הטמא ע\"י עפר הפרה כמ\"ש באגה\"ק סי' הנ\"ל.\nנתבאר באוה\"ת חקת ע' תשפז. תשצו. תתג. סה\"מ תרכ\"ט ע' רסד. ענין מים חיים נתבאר בלקו\"ת חוקת ס, ג. באוה\"ת בראשית נג, ב. ושם בדף נד, א. בהקיצור ”ונשרף עד שנעשה אפר, וע\"י המים חיים. זהו ענין שלום לרחוק שנעשה קרוב וממשיך מבחי' אחכמה והיא רחוקה ממני, לטהר מטומאת מת זמ\"ל דתהו\". ע\"ש.\nבאוה\"ת מג\"א ע' ב'שעב מבאר: ”דכדי להיות אתהפכא חשוכא לנהורא צ\"ל נמשך ממקום גבוה יותר כן נתבאר בענין מים חיים דאפר פרה\", ע\"ש. נזכר באוה\"ת ויקרא כרך א ע' שיד. נ\"ך כרך א ע' תרסג. ובאוה\"ת דרושים ליוהכ\"פ ע' א'תקצד. סה\"מ תרכ\"ז ע' ריג."],["874","27","<b>במשנה קידוש מי חטאת</b>: מס' פרה פ\"ו. באוה\"ת חקת ע' תשצ מבאר: שע\"י שהחטאת נשרף ונהפך לטוב נמשך מים חיים\". ובאוה\"ת בראשית נד, א בשם המק\"מ פי' מי חטאת פי' המים מתקנים חטאת שהיא ק\"נ."]]],[2100490216,"והטעם שנק' בשם קידוש הענין הוא משום דשרש מים חיים הללו הוא בבחי' קדש העליון על כל הקדושו' העליונות שבאצי', והיינו בחי'<sup data-n=\"875\">28</sup> טלא דבדולחא, כמ\"ש בזוה\"ק<sup data-n=\"876\">29</sup> ע\"פ הזה עליהם מי חטאת שיורי טלא דבדולחא כו', וענין טלא דבדולחא ידוע שהוא בחי' ח\"ס, ונק' מ\"ס דא\"א ולכך היא בחי' קדש העליון על כל הקדושות, להיותה בחי' מקור ושרש הראשון להתהוות מציאת החכ' באצי' הנק' בשם קדש כידוע, והנה ענין נתינת מים על אפר הפרה היינו לברר בירורי רפ\"ח ניצוצין שנפלו בשבירה, והוא האפר דפרה אדומה ששרשה מבחי' גבורות דב\"ן דתוהו כמ\"ש במ\"א. ולהיות כי בחכ'<sup data-n=\"877\">30</sup> אתברירו, הענין הוא בבחי' ח\"ס<sup data-n=\"878\">31</sup> דא\"א הנק' טלא דבדולחא, והוא משום דעלה הוא דאתמר דוקא בכמה דוכתי בזוה\"ק בחכמה אתברירו כו', ומטעם הנ\"ל דהוא שרש ומקור החכ' ע\"כ עיקר הבירור במים, במים החיים שנותנים על אפר הפרה והוא הנק' קידוש מי חטאת, וענין הבירור הוא לאהפכא<sup data-n=\"879\">32</sup> חשוכא לנהורא",[["875","28","<b>בחי' טלא דבדולחא</b>: נזכר באוה\"ת חקת ע' תתג. וראה בארוכה באוה\"ת — מארז\"ל וענינים ע' נט שכן משמע בזהר ח\"ג דף מט דבחי' טל ומי חטאת ענין א' הם. בדרך מצותיך מצות תפילין יז, א מבאר למה נק' קדש.\nבאוה\"ת ויקהל ע' ב'קלה כ': ”טלא דבדולחא היינו גבורה דעתיק המלובש במו\"ס שמשם מקור ושרש המשכת מ\"ד ע\"י המ\"ן מהבירורים עיין באגה\"ק ד\"ה למה נסמכה פ' פרה. ועיין בסידור ע\"פ ברוך אומר ועושה ברוך גוזר ומקיים\". ע\"ש. ראה ביאוה\"ז להצ\"צ כרך א ע' שלח."],["876","29","<b>כמ\"ש בזוה\"ק</b>: זח\"ג קכח, ב. שם קלה, ב. וראה זח\"ג מט, א."],["877","30","<b>בחכ' אתברירו</b>: עיין ע\"ח שנ\"ג שער מוחין דצלם פ\"ח במחשבה אתברירו, וע' של\"ט שער מ\"ן ומ\"ד דרוש א' המחשבה עליונה שהיא ח\"ס דברישא דע\"ק כו', ובשער י\"ט רפ\"ח ניצוצין פ\"ה במחשבה אתברירו בשם זהר פקודי.\nע' תולדות יעקב יוסף בראשית י, ע\"א במחשבה אתברירו, וע' בשמונה שערים שער ז דף ג ע\"א כולא אתברר במחשבה כנזכר בהיכלות דפקודי שכל הש\"ך נקודות אתברירו במחשבה — (לקוטי הגהות לתניא ע' פג)."],["878","31","<b>ח\"ס דא\"א</b>: באוה\"ת מארז\"ל וענינים ע' נט כ' שכאן מבאר ההפרש בין מ\"ד דקרבנות למ\"ד דפרה שזהו מז\"א וקידוש מי חטאת ממזלות דא\"א. וראה גם באוה\"ת שה\"ש כרך ב ע' תקסב.\nוענין חכמה סתימאה דא\"א מבואר בביאה\"ז להצ\"צ כרך א ע' שלח: ”שהיא למעלה מחכמה הנגלית שהיא מקורה\".\nנזכר בלקו\"ת שה\"ש מח, ב (ונעתק גם בסה\"מ תרכ\"ז ע' סג). באוה\"ת מג\"א ע' ב'שעא-ב. כי תצא ע' תתרכ בסופו. בראשית כרך ו תתרצו, ב (”שלכן נק' קידוש מי חטאת לפי שהוא המש' ממו\"ס כו'\").\nע' פ' חוקת ע\"פ ויקחו אליך אות ב' [לקו\"ת חקת ס, ג: ומים חיים הוא מקור החכמה שנק' מים חיים בחי' מעין וכמ\"ש והחכמה מאין תמצא והוא מבחי' טלא דבדולחא מקור החכמה סתימאה כידוע (ומבואר בזהר פ' תזריע דמ\"ט ע\"א, ועיין בזהר תרומה דקע\"ח סע\"ב בספרא דצניעותא פ\"ה. וע' מ\"ש באגה\"ק ד\"ה למה נסמכה פ' מרים כו')]. ע' פ' בלק בביאור ע\"פ מי מנה אות ב' [לקו\"ת בלק סט, ג: ”ומקור הבירורים הוא ע\"י מו\"ס דא\"א וכמ\"ש באג\"ה בד\"ה למה נסמכה פ' מרים\"]. ע' בביאור ע\"פ כי על כל כבוד חופה אות ב' [לקו\"ת שה\"ש מח, ב: מו\"ס הוא מקור כל הבירורים כי מ\"ש בחכמה אתברירו שרשה מן מו\"ס הנעלם ששם עיקר הבירור (כמ\"ש בד\"ה למה נסמכה כו'')]. ע' פ' בהעלותך בביאור ד\"ה הנה השמן [לקו\"ת בהעלותך לא, א: ”ועיקר הבירורים הוא במו\"ס דהיינו בירור עולם התיקון מעולם התהו ושבירת הכלים שנפלו לבי\"ע כו' כמ\"ש באגה\"ק סי' כ\"ח\"]."],["879","32","<b>לאהפכא חשוכא לנהורא</b>: ראה זח\"א ד, א. וראה תקו\"ז תכ\"א."]]],[2100490217,"כידוע, והיינו לברר ולתקן מה שנפל<sup data-n=\"880\">*32</sup> מעולם התהו בבי\"ע, והוא הנק' חשוכא שמתהפך לנהורא, היינו שיהי' בבחי' התיקון שנק' נהורא, והוא ע\"י בחי' מ\"ס דא\"א הנ\"ל שמברר ומתקן בחי' התוהו כידוע וד\"ל.\n<b>ולזה</b> הטעם הזאת מי חטאת דאפר הפרה מטהרת טמאין אפי' הטמאין בטומאת מת שהוא אבי<sup data-n=\"881\">33</sup> אבות הטומאה, דהיינו למטה מטה גם מקליפת נוגה, דקליפת נוגה מעורבת טו\"ר כידוע ואבי אבות הטומאה הוא בחי' מקור הטומאה שמג' קליפות הטמאות לגמרי כו', להיות כי שרש התהוות החשך והרע הגמור שהן ג' קה\"ט לגמרי הוא מסיבת השבירה דז' מלכים מעולם התוהו שמתו וכידוע שירדו ונפלו עד למטה מטה ומזה הוא התהוות המיתה גשמי הנק' אבי אבות הטומאה כו', ואין תיקון ובירור הטומאה דאבי אבות כו' כ\"א במקור ושרש של החכ' הנק' מוחא סתימאה דא\"א, אבל לא מאור החכ' שנאצל באצי', הגם שנאמר בה והחכ'<sup data-n=\"882\">34</sup> תחי', אבל שתחי' גם המת אין ביכולתה, והוא ענין הנ\"ל דלאהפכא חשוכא לנהורא אין ביכולת רק בבחי' מו\"ס דא\"א ועלה הוא דאתמר דוקא בחכ' אתברירו כו' וכמ\"ש הטעם במ\"א דלכך אמר שלמה על מעשה פרה אמרתי<sup data-n=\"883\">35</sup> אחכמה והיא רחוקה ממני מפני שהבירור הוא ממקור כל הבירורי' דהיינו מבחי' מו\"ס דא\"א שלמעלה מבחי' גילוי אור החכ' כו' וד\"ל. ובכ\"ז יובן ענין המעלה ומדריגה יתירה שבמעשה פרה אדומה יותר מקרבנות הנעשות בפנים שהרי בקרבנות הנעשות בפנים הגם שהן נעשים ע\"ג המזבח לכפרה כנ\"ל, מ\"מ אין בחי' הבירור שלהן כלל ברפ\"ח ניצוצין שנפלו בנוגה משבירת הכלים דתוהו כו' אלא רק בירור בחי' נוגה עצמה בד' חיות שבמרכבה פני נשר פני שור כו' שהיא מעורב טו\"ר ואינו רע גמור משא\"כ בירור שע\"י מי חטאת דפרה הוא בירור רפ\"ח שנפלו למטה מטה מקליפת נוגה לאהפכא חשוכא ממש לנהורא כו' כנ\"ל וד\"ל.\n<b>והנה</b> לפ\"ז מובן ממילא ענין העיקר ושרש יתרון מעלת ומדריגת מצות פרה הוא מפני ששרש בחי' המ\"ד שבא לברר בירורים שלמטה מנוגה הוא בא ממקום עליון הרבה יותר מבחי' המ\"ד שבא לברר בחי' נוגה בקרבנות שנעשו בפנים כו', כי הנה מבואר למעלה דבחי' מ\"ד שירד בקרבנות שנעשו בפנים הוא מבחי' ז\"א דאצי' הנק' אדם כו' ושרשו מבחי' מוחין דאור אבא בלבד כידוע אבל בחי' המ\"ד שמברר גם למטה מנוגה במצות פרה אדומה הוא בא מלמעלה הרבה גם מבחי' מוחין דאור אבא שהרי הוא מבחי' מזל ונוצר שהוא תיקון הח' ממזלות דא\"א שרש יניקות אור אבא, וכידוע בכמה דוכתי דאבא<sup data-n=\"884\">36</sup> יונק ממזל הח' כו', ופי' יונק הוא רק בבחי' צמצום האור",[["880","*32","<b>שנפל מעולם התהו בבי\"ע</b>: מובא בסה\"מ תרכ\"ז ע' רעט ובסה\"מ תרכ\"ט ע' קצג שהניצוצים שנפלו בשבירה נקראים בשם טמא מת, ע\"ש."],["881","33","<b>אבי אבות הטומאה. . מקליפת נוגה</b>: באוה\"ת מארז\"ל וענינים ע' ס: להיותו מקור בחי' שבה\"כ וימלוך וימת כו' זהו מקור כל התהוות הקליפות כו'.\nההפרש בין טומאת מת לשארי הטומאות נתבאר בלקו\"ש ח\"ח ע' 326.\nנזכר בביאוה\"ז להצ\"צ כרך ב ע' תתקצא. בסה\"מ תרכ\"ז ע' ריג. סה\"מ תרנ\"ט ע' קסד."],["882","34","<b>והחכמה תחי'</b>: קהלת ז, יב."],["883","35","<b>אמרתי אחכמה והיא רחוקה ממני</b>: קהלת שם, כג."],["884","36","<b>דאבא יונק ממזל הח'</b>: ע\"ח שעה\"כ פ\"ה. שם שער יג ספ\"ט. שער יד ספ\"ג ופ\"ח, ועוד."]]],[2100490218,"והשפע מאד, אבל כשמאיר ומתגלה אותו תיקון ונוצר חסד כמו שהוא בבחי' מו\"ס דא\"א עצמה אזי נק' רצון דבחי' המ\"ד שנמשך משם יוכל לטהר גם המת אבי אבות כו' שלמטה מנוגה מטעם שהוא למעלה מבחי' המיתה ששרשה אינו אלא מן השבירה דרפ\"ח כו', והוא הנק' טלא דבדולחא והיינו הטל שעתיד להחיות המתים לע\"ל כמ\"ש כי<sup data-n=\"885\">37</sup> טל אורות טלך כו', משום דלגבי אור זה דטלא דבדולחא נאמ' גם חושך לא יחשיך ממך כו', וזהו פי' מחי' מתים בר\"ר כו', וכידוע<sup data-n=\"886\">38</sup> הכלל שכל שהוא גבוה גבוה יותר במעלה ומדריגה יוכל להשפיל א\"ע יותר ע\"כ מבחי' מ\"ס דא\"א יכול לברר גם מה שלמטה מנוגה ובזאת יתרון מעלת מצות פרה אדומה על כל הקרבנות והגם שנעשות לכפרה ע\"ג המזבח אבל טהרת מי חטאת דפרה גבוה מבחי' כפרה דמזבח מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> למה נסמכה פ' מיתת מרים לפ' פרה לומר לך מה פרה מכפרת אף מיתת צדיקים מכפרת כו', דהנה ידוע דנשמות הצדיקים במס\"נ<sup data-n=\"887\">39</sup> בעבודה שבלב בק\"ש שחרית וערבית בחייהם הן מעלים מ\"נ לאו\"א כמ\"ש<sup data-n=\"888\">40</sup> בע\"ח ועי\"ז יורד ונמשך בחי' מ\"ד מתיקון ונוצר חסד במזל הח' דמ\"ס דא\"א כנ\"ל, והנה זאת היא יתרון מעלה ומדריגה במיתת צדיקים כמארז\"ל גדולים<sup data-n=\"889\">41</sup> צדיקים במיתתן יותר מבחייהם כו', במה שמתגלה ומאיר עליהם בעת פטירתם בבחי' גילוי אור ביותר מלמעלה למטה, וענין יתרון הגילוי היינו שמבחי' תיקון ונוצר שהיו מעלין מ\"נ לשם בחייהם הוא שמתגלה ומאיר באותיות רצון שהאותיות רצון הוא בחי' הפנימי' של אותו תיקון הי\"ג דמזל ונוצר כו', כי ונוצר אותיות צינור הוא כמו בחי' צינור דק בלבד להשפיע לאור אבא, וכענין הנ\"ל דאבא יונק ממזל הח' כו', אבל אותיות רצון הוא מ\"ש בזהר<sup data-n=\"890\">42</sup> בכמה דוכתי כד אתגלי רעוא דכ\"ר כו', וגם בנשמה האלקי' לפעמים מתגלה בה מבחי' רצון זה שהוא בבחי' הפנימי' דמ\"ס דא\"א והוא מ\"ש במגילת אסתר אשר<sup data-n=\"891\">43</sup> חפץ בה המלך ונקראה בשם כמ\"ש במ\"א וד\"ל, ולהיות כי בחייהן היו מעלין מ\"נ לשם הענין הוא משום דמעמל האדם בכל אשר יעמול תחת השמש בעוד הנשמה בגוף הנה יעלה אותו העמל והעבודה האלקי' למעלה ותאיר שם בבחי' ההעלם והסתר אם הייתה עמלו בחכ' והשגה אלקי' בידיעת והשגת התורה בנגלה ונסתר יעלה אותו העמל בבחי' העלאת מ\"נ לאו\"א דאוריי' מח\"ע נפקת וכמו שעמל האדם במס\"נ בק\"ש מעלה מ\"נ לאו\"א וה\"ט משום שהוא במס\"נ בבחי' היחוד בפסוק ראשון כידוע, ואם הייתה עמלו במדת אהוי\"ר יעלה לבחי' ז\"א כו', ועד\"ז בכל פרטי העמל, אך זה הכלל דבעת פטירת האדם מתגלה ומאיר על נפשו מאותו אור הנעלם ונסתר שהי' מוסתר ונעלם למעלה",[["885","37","<b>כי טל אורות טלך</b>: ישעי' כו, יט."],["886","38","<b>וכידוע הכלל שכל שהוא גבוה</b>: ראה שערי אורה שער הפורים נח, א. סה, א. תו\"ח בראשית כה, א."],["887","39","<b>במס\"נ. . בק\"ש</b>: ראה זח\"א קכד, ב (מדה\"נ). תקו\"ז י, ב. פע\"ח שער ק\"ש פי\"ב. ב\"ח טואו\"ח ריש סי' סא."],["888","40","<b>כמ\"ש בע\"ח</b>: ראה ע\"ח שער הכללים פ\"א. וראה זח\"ג נו, ב."],["889","41","<b>גדולים צדיקים במיתתן יותר מבחייהן</b>: חולין ז, ב. וש\"נ."],["890","42","<b>בזוהר בכמה דוכתי כד אתגלי רעוא דכ\"ר</b>: ראה זח\"ג קלז, ב."],["891","43","<b>אשר חפץ בה המלך</b>: ראה אסתר ו, ו."]]],[2100490219,"כל ימי היותו מעלה מ\"נ לשם כל ימי חייו כו' וד\"ל. וא\"כ בבחי' גילוי אותו האור הנעלם שבאו\"א ה\"ז בודאי יתרון מעלה ומדריגה הרבה מאותו האור שהי' נשאר בהעלם מחמת העלאת מ\"נ בחייו כו', והיינו ענין גילוי בחי' רצון מתיקון ונוצר, כי בהגלות נגלות האור צריך שיתגלה משרש ומקור של אותו האור, והיינו הנק' בחי' עת רצון שהוא בפנימי' במ\"ס דא\"א כנ\"ל, והוא המתגלה ומאיר מלמעלה למטה דוקא בעת פטירתו של נשמת הצדיק, מפני שאז מתגלה ומאיר בו בגילוי כל מה שנשאר בהעלם והסתר מכל עבודתו שעבד במס\"נ בכל ימי חייו כו', וע\"כ ארז\"ל דגדולים צדיקים במיתתן יותר מבחייהן כו' (ומטעם זה נק'<sup data-n=\"892\">44</sup> אצלם בשם הילולא כו' כמ\"ש במ\"א וד\"ל).\n<b>וז\"ש</b> למה נסמכה פ' מיתת מרים לפ' פרה כו', דהנה ארז\"ל דמיתת צדיקים מכפרת על עון הדור כידוע, והרי בכלל עון הדור נכלל בודאי גם העבירות החמורות ששרשם מג' קליפות הטמאות לגמרי שלמטה מטה מקליפת נוגה כנ\"ל, ומיתת צדיקים מכפרת גם עליהם וע\"כ אמר שלזה הטעם נסמכה פ' מרים לפ' פרה דוקא, כי במצות פרה מטהרת גם הטמאים מאבי אבות הטומאה מטעם ששרשם מהמים חיים בעפר, הוא מבחי' מ\"ס דא\"א שבבחי' הפנימי' שהוא בחי' עת רצון שבמזל ונוצר כנ\"ל, וע\"כ גם למטה מטה מנוגה ג\"כ מהפך מחשוכא לנהורא כו'. והרי גם במיתת צדיקים להיות שמתגלה בהם אז מבחי' פנימי' דמזל ונוצר דהיינו עת רצון ג\"כ כנ\"ל, ע\"כ מכפרת על עון הדור הגם שהוא מג' קליפות הטמאות לגמרי וא\"כ בהכרח לומר שנסמכה פ' מיתת מרים לפ' פרה דוקא שנעשי' בחוץ לטהר גם הטמאים כו' ולא לפ' חטאת הנעשי' בפנים, כי בקרבנות הנעשות בפנים אין<sup data-n=\"893\">45</sup> מבררין אלא על השגגות כנודע ולא על הזדונות, והוא לפי שענין הקרבנות אינו אלא אתהפכות חשוכא לנהורא בבחי' קליפת נוגה בלבד בדברים המותרים ולא בדברים האסורים לגמרי כנ\"ל קליפות הטמאות כו' וד\"ל. והטעם מבואר למעלה דפני נשר פני שור כו' הן המעלין מ\"נ בקרבנות וכמ\"ש בלק\"ת<sup data-n=\"894\">46</sup> בפ' ויקרא אבל בחי' הרע הגמור שנפל בשבירה למטה מטה מנוגה כמו הזדונות של עבירות אין הקרבנות מכפרים אלא דוקא ע\"י בחי' מו\"ס דא\"א מקור כל הבירורים ומשם יוכל להיות ענין הבירור שלהם והיינו לאתהפכ' חשוכא לנהורא פי' מתהו שנק' חשוכא לנהורא הוא בחי'<sup data-n=\"895\">47</sup> התיקון כנ\"ל וד\"ל. ובכ\"ז מתורץ הקושי' הנ\"ל למה א' לפ' פרה דוקא, כי דומה לגמרי למצות פרה דוקא, וע\"כ א' מה פרה מכפרת",[["892","44","<b>נק' אצלם בשם הילולא כו' כמ\"ש במ\"א</b>: ראה אגרת הקודש של אדה\"ז ח\"א ע' צח-ט, וש\"נ. וראה ד\"ה להבין ענין הילולא דרשב\"י תרנ\"ד (סה\"מ תרנ\"ד ע' רסא ואילך)."],["893","45","<b>אין מבררין אלא על השגגות</b>: נזכר באוה\"ת ויקרא כרך ג ע' תשכט. במדבר-חקת ע' תשפז. שם בהוספות ע' 27. המשך תערב כרך ג ע' א'רנב. ראה סה\"מ תקס\"ח ע' רפט. אוה\"ת קדושים ע' תקעא. מטות ע' א'רסה. דרך מצותיך קיא, א.\nומה שאשם בא על המזיד (לפי גירסת ילקוט שמעוני יביא אשם ויתכפר לו) זהו דוקא כשעושה תשובה, וע\"י תשובה זו נעשים הזדונות כשגגות ואז מהני קרבן — (לקו\"ש ח\"ח ע' 158 הערה 58. וראה בדרך מצותיך מצות עגלה ערופה קיא, ב (מובא בלקו\"ש שם)."],["894","46","<b>בלק\"ת בפ' ויקרא</b>: לקו\"ת להאריז\"ל."],["895","47","<b>בחי' התיקון</b>: וזהו ועתה פון ישלח ידו ולקח מעץ החיים היינו כיון שלא ימות לא יתכפר הזדונות של העולם וזהו וירד עד איש העדלמי — (לקוטי הגהות לתניא ע' קלה)."]]],[2100490220,"כלומר גם על הטמאים לגמרי כך מיתת צדיקים מכפרת גם על הזדונות שיהיו כזכיות כי ע\"י גילוי מזל ונוצר באותיות רצון כנ\"ל שמאיר ומתגלה בפטירתו מאיר חסד ה' מעולם ועד עולם<sup data-n=\"896\">48</sup> על יריאיו ופועל<sup data-n=\"897\">49</sup> ישועות בקרב הארץ לכפר<sup data-n=\"898\">50</sup> על עון הדור גם על הזדונות ומטעם הנ\"ל וד\"ל. והנה בילקוט<sup data-n=\"899\">51</sup> הגירסא כך היא מה מי חטאת וכו'.",[["896","48","<b>עולם על יריאיו</b>: ע\"פ ל' הכתוב תהלים קג, טז."],["897","49","<b>ופועל ישועות בקרב הארץ</b>: ע\"פ לשון הכתוב תהלים עד, יב."],["898","50","<b>לכפר על עון הדור</b>: זח\"ג נו, ב. מו\"ק כח, א. ויק\"ר כ, יב. בלקוטי הגהות לתניא ע' פג: ע' פ' מסעי ד\"ה ביאור ענין מוצאיהם ד\"ה וענין פרה."],["899","51","<b>בילקוט הגי'. . מי חטאת</b>: ילקוט שמעוני רמז. .. שם מובא המאמר, ובמקום ”מה פרה מכפרת\" הגי' שם ”מי חטאת\". זה מתאים יותר למה שהוסבר לעיל, שענין הפרה המכפרת ופועלת על ג' קליפות הטמאות — הוא הרי ענין קידוש מי חטאת שבפרה (לא שריפת הפרה, שברוחניות הענינים היא ענין על העלאה — כי אם ”קידוש מי חטאת\" שהוא המשכה מ”קדש העליון\" עד ”חכמה סתימאה\" מקור הבירורים) — (שיעורים בספר התניא)."]]],[2100490221,"<h3>ויאבק איש עמו</h3>\n<b>בעז\"ה שבת פ' וישלח</b>\n<b>ויאבק</b><sup data-n=\"900\">1</sup> איש עמו<sup data-n=\"901\">2</sup> וכו' וירא כי לא יכול לו ויגע בכף יריכו כו'. (בזוהר פ' וישלח דק\"ע ע\"א) ר' שמעון אמר מן אבק אבק תפל לעפר, מה בין אבק לעפר אבק דא דאשתאר מן נורא ולא עביד איבין לעלמין, עפר דכל איבין נפקין מיני', ואיהו כללא דעילא ותתא ע\"כ. והנה להבין ענין המאמר יש להקדי' תחלה כללו' ענין מלחמה זו דיעקב עם שר של עשיו כמ\"ש ויאבק איש עמו וידוע דברי רז\"ל במס' חולין<sup data-n=\"902\">3</sup> בזה הפסוק אריב\"ל מלמד שהעלו אבק ברגליהם עד כסא הכבוד כו'. הנה נודע שמלחמה זו דיעקב הי' ענין מלחמה למעלה בסט' דקדושה עם סט' דקליפה משום דאת<sup data-n=\"903\">4</sup> זה לעו\"ז עשה האלקי' כידוע וזהו מ\"ש מלחמה<sup data-n=\"904\">5</sup> לה' בעמלק כו' שהמלחמה תמידי' למעלה, ונודע מ\"ש בפרדס<sup data-n=\"905\">6</sup> ע\"פ זה ויגע בכף יריכו כו' שפגם בחי' הנצח דקדושה שמשם אור הנבואה שופע למטה בנשמו' כו', וע\"כ לא היתה הנבואה בישראל עד שמואל הנביא כי שמואל להיות שרש נשמתו מבחי' נצח על ידו הי' בחי' תיקון לבחי' הפגם שנעשה בירך יעקב וכמ\"ש שמואל",[["900","1","<b>ויאבק איש עמו</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 עח, א. 68 כה, א. נמצא ג\"כ בכת\"י 671 כז, ב.\nהנחת ר' משה בן כ\"ק אדה\"ז נדפס לקמן ע' קסד. בהתחלה: בזוהר (פ' וישלח. . . ) ויאבק איש עמו.\nעוד נוסח נדפס בתו\"א כו, א.\nחלק מהמאמר עם הגהות נמצא באוה\"ת וישלח כרך ה' תתעה, א. וראה גם כרך ז תתתל, א. אוה\"ת חקת ע' תשסד ואילך."],["901","2","<b>ויאבק איש עמו</b>: וישלח לב, כה."],["902","3","<b>במס' חולין</b>: צא, א. הובא ברש\"י שם."],["903","4","<b>דאת זה לעו\"ז עשה האלקים</b>: קהלת ז, יד."],["904","5","<b>מלחמה לה' בעמלק</b>: בשלח יז, טז."],["905","6","<b>בפרדס. . בשער ירך יעקב</b>: שער יז."]]],[2100490222,"וגם<sup data-n=\"906\">7</sup> נצח ישראל לא ישקר כו' וכמ\"ש שם באריכות בשער ירך יעקב. וא\"כ מובן מזה לכאורה שהמלחמה באמתיות הי' מאחר שנעשה פגם גמור בנצח דקדושה ע\"י התגברות הקליפה כו'. וזה פלאי מאד מאד, דהאיך יתכן שתהא מלחמה זו אמיתי' להיות הסט' דקליפה ילחם נגד הקדושה ולנצח לפעמים כו', הלא ידוע גם בספרי הקבלה שאין מציאות חיות ושפע כלל וכלל לחיצוני' כ\"א מה שמקבלי' מסט' דקדושה בלבד וכמ\"ש בע\"ח דכתר דקליפה דבוק באחורי' דנוק' כו' ולכך נק' אלקי' אחרים כו', והמופת לזה דכאשר יכלה קץ וגבול קבלת שפעם שמקבלים מן הקדושה כו' כמו לע\"ל הנה כתי' בלע<sup data-n=\"907\">8</sup> המות לנצח כו' ואת<sup data-n=\"908\">9</sup> רוח הטומאה אעביר מן הארץ כו', והוא מפני דגם מה שבלעו כבר יוציאו מהם וכמ\"ש חיל<sup data-n=\"909\">10</sup> בלע ויקיאנו וכמ\"ש עת<sup data-n=\"910\">11</sup> אשר שלט האד\"ם באד\"ם לרע לו כידוע וא\"כ ממילא היו כלא יהיו הרי מזה הוראה גמורה שאין להם חיות מצד עצמם כלום שאם הי' להם אור וחיות מצד עצמם למה יכלו ויאבדו לגמרי בעת קץ כו', וא\"כ מאד יפלא ענין מלחמה זו שלהם נגד הקדושה עד שיכלו לפגום בבחי' נצח דקדושה כנ\"ל, דמשמעות הענין שיש להם חיות אור מצד עצמם ללחום ולנצח, וזה אינו שבודאי אין להם חיות אור כלל רק מה שמקבלי' מהיכלות דקדושה כנ\"ל.\n<b>אך</b> הענין יובן בהקדי' הפסוק ואלה<sup data-n=\"911\">12</sup> המלכי' אשר מלכו בארץ אדום לפני מלוך מלך לבנ\"י כו', דהנה ידוע בסדר ההשתלשלו' בכלל אצי' בריאה יצי' עשי' הנה הוא בא ויורד ונמשך מעילה לעילה בהדרגה מבחי' התחתונה שבעליון נעשה בחי' שרש וראש לתחתון דהיינו מבחי' מל' שבמאציל נעשה כתר לנאצלים. ועד\"ז יורד עוד ונעשה מבחי' מל' דאצי' כתר לבריאה כו' עד שמשתלשל ע\"ד הזה עד סוף כל המדריגו' והוא בחי' מל' די\"ס דעשי' שהוא ראש ומקור לכל הנמצאים הגשמיי' שבעוה\"ז השפל כו'. וידוע ג\"כ שזה הסדר של ירידו' המדריגו' בכלל נעשה אח\"כ אבל בתחלה כשעלה ברצון המאציל להאציל ולברוא כו' לא הי' באור שפע עדיין שום ענין ירידו' מדרגות וחלוקי אופנים שונים אלא הי' רק בחי' אור חסד עליון פשוט בתכלית להשפיע בכלל לכולם בהשוואה אחת מבלתי הי' נמצא יתרון מעלה ומדרגה בא' על זולתו כלל וכלל אלא הי' הכל שוין לפניו ממש וזהו מטעם משום דלפני עצמו' המאציל כי להיותו מרומם ומובדל בערך לגמרי מכל מה שנשפע מאתו ע\"כ שוין לפניו כקטן כגדול וכמ\"ש כחשיכה<sup data-n=\"912\">13</sup> כאורה כו' שגם חושך ואור שוין ממש בהשווא' א' לפניו ולכך עצמו' המאציל נק' בשם סוכ\"ע כידוע.\n<b>ויובן</b> מזה שלזה הטעם הי' אור השפע שנשפע מאתו מאירה גם לחיצוני' כמו לפנימיי' באין הפרש כלל כמו עד\"מ השממית ההולכת בהיכל מלך שאינו נותן",[["906","7","<b>וגם נצח ישראל לא ישקר</b>: שמואל א טו, כט."],["907","8","<b>בלע המות לנצח</b>: ישעי' כה, ח."],["908","9","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["909","10","<b>חיל בלע ויקיאנו</b>: איוב כ, טו."],["910","11","<b>עת אשר שלט האדם באדם</b>: קהלת ח, ט."],["911","12","<b>ואלה המלכי' אשר מלכו</b>: וישלח לו, לא."],["912","13","<b>כחשיכה כאורה</b>: תהלים קלט, יב. ראה עטרת ראש לעשי\"ת ע' נא. אוה\"ת וישלח כרך ה תתעה, א."]]],[2100490223,"לב עלי' כלל וכלל וכמ\"ש שממית<sup data-n=\"913\">14</sup> בידים תתפש והיא בהיכלי מלך כו', כך מפני שכולם אינם תופסים מקום כלל וכלל בבחי' עצמות הרוממו' ע\"כ גם החיצוני' יכולים לקבל אור שפע והוא מפני העדר תפיסת מקום אצלו כל עיקר ההשפעה מפני עוצם הרוממו' עד\"מ המלך הגדול בהגלות נגלות מאתו אור חסד ישוה לפניו קטן וגדול שיקבלו אותו החסד בהשווא' א' והיינו מפני עוצם רוממו' גדולתו אין החסד תופס מקום וגם המקבלים אינם תופסי' מקום עד שיתן דעתו לדקדק בזאת השפע ליתנה לראוי דוקא ולא לשאינו ראוי לה כו' וכמו בדור<sup data-n=\"914\">15</sup> אנוש שהי' להם כל רב טוב חסד עליון אע\"פ שהיו עובדי ע\"ז כידוע, וכמארז\"ל מפני<sup data-n=\"915\">16</sup> שהיו ניזונין בחסדו של הקב\"ה פי' מפני שבחי' אור החסד שיוצא מעצמו' המאציל הרי קמי' כחשיכה כאורה כנ\"ל ע\"כ גם לעע\"ז ישפיע אעפ\"י שהן עוברי<sup data-n=\"916\">17</sup> רצונו כי מה תופס מקום כל עיקר וכמ\"ש אם<sup data-n=\"917\">18</sup> צדקת מה תתן לו כו', ולפי שהי' אור החסד העליון הזה פשוט בתכלית מעצמו' המאציל היו הכל מקבלים ממנו כי אור זה הפשוט ביכולתו להאיר עד אין קץ ושיעור למטה מטה מטעם הנ\"ל. ויובן דוגמתו במה שאמרו אברהם<sup data-n=\"918\">19</sup> יצא ממנו ישמעאל, פי' מפני שהי' אברהם איש החסד<sup data-n=\"919\">20</sup> בטבעו כידוע ע\"כ אמר גם<sup data-n=\"920\">21</sup> ישמעאל יחי' לפני ה' וגם שאינו ראוי לזה כי הי' עובד ע\"ז אך מפני שהי' תגבורת מדת החסד באברהם יצא אור שפע חסדו בלתי שיעור למטה להאיר גם בישמעאל כו' וזהו הנק' מותרי<sup data-n=\"921\">22</sup> החסדי' כו' כידוע. ועד\"ז יובן למעלה שבהיות אור חסד העליון של המאציל פשוט הי' אור שפעו יורד גם עד למטה מטה מאד עד שגם בחי' החיצוני' מקבלי' בהשווא' א' עם בחי' הפנימיי' הקרובי' לאא\"ס בבחי' הביטול כו' והוא לפי שאין תופס מקום כלל גם בחי' הקירוב של הפנימיי' עם היותם קרובי' בערך ההשתלשלו', אמנם לגבי עצמו' המאציל שלמעלה מגדר ההשתלשלו' בחי' הקירוב ובחי' הריחוק אחת היא כו' וד\"ל.\n<b>והנה</b> כדי להמשיך אור השפע מאור חסד עליון של המאציל להיות בא י\"ס דוקא בבחי' פנימיו' הקרובים לאא\"ס ולהתרחק מן החיצוני' הרחוקי' וכיוצא הי' צריך שיהא זה דוקא ע\"י צמצום האור בעצמו' המאציל, ועד\"מ שיתן המלך דעתו לדקדק באור חסדו שיתנו לראוי לה ולא לשאינו ראוי שזהו בחי' צמצום גדול לגבי עצם רוממותו כו' וזהו עיקר ענין<sup data-n=\"922\">23</sup> הצמצומי' הנזכר בע\"ח שהי' קודם שנאצל כל האצי' שהוא רק כדי להיות אוא\"ס בבחי' י\"ס אורו' וכלים דוקא בבחי' הקדושה האלקי', והנה חב\"ד וחג\"ת ונה\"י הן בכלל, חב\"ד*<sup data-n=\"923\">*23</sup> הוא בבחי' הביטול יותר להיותם",[["913","14","<b>שממית בידים תתפש</b>: משלי ל, כח."],["914","15","<b>דור אנוש. . עובדי ע\"ז</b>: ראה בראשית ד, כו. שבת קיח, ב. רמב\"ם ריש הל' ע\"ז."],["915","16","<b>מפני שהיו ניזונין בחסדו של הקב\"ה</b>: ראה שבת קיח, ב. פסחים קיח, א."],["916","17","<b>עוברי רצונו</b>: ראה מכות כד, ב."],["917","18","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["918","19","<b>אברהם יצא ממנו ישמעאל</b>: ראה פסחים נו, א."],["919","20","<b>אברהם איש החסד</b>: ראה זהר בראשית מז, ב."],["920","21","<b>גם ישמעאל יחי' לפני ה'</b>: ראה לך לך יז, יח."],["921","22","<b>מותרי החסדי' כו' כידוע</b>: ראה ג\"כ תורת חיים שמות [הוצאת קה\"ת — תשס\"ג] כד, ד."],["922","23","<b>ענין הצמצומי' הנזכר בע\"ח</b>: ראה ש\"א ענף ב."],["923","*23","<b>חב\"ד הוא בחי' הביטול יותר</b>: באוה\"ת וישלח תתעה, ב — (זה צ\"ע דבאדם כשנמשך ההת-פעלות באהוי\"ר בלב חשוב יותר מאלו ההתבוננות רק במוחו ושכלו ולא נגע ללב וצ\"ע בסש\"ב פט\"ז בענין מחשבה טובה הקב\"ה מצרפה למעשה)."]]]]});
